window.GUIA_EX = window.GUIA_EX || {};
window.GUIA_EX.p3 = {"pagina":3,"titulo":"Busca vetorial e índices","capitulos":["O custo de olhar para tudo","Aproximar: a troca entre recall e custo","HNSW por dentro","Os três parâmetros: m, ef_construction, ef_search","A alternativa: IVFFlat","pgvector na prática: DDL, consulta e EXPLAIN","Filtros sobre um índice aproximado","Medir: recall do índice, latência e memória","Operação: construir, manter, decidir","No projeto: integração"],"itens":[{"cap":1,"tipo":"python","nivel":1,"tempo":8,"titulo":"A conta da varredura completa","enunciado":"Escreva `custo_varredura(n, d, bytes_por_numero=4)` que devolve `{\"multiplicacoes\": n*d, \"bytes\": n*d*bytes_por_numero}`: o custo aritmético e a memória percorrida por consulta numa busca exata sobre `n` vetores de `d` dimensões.","esqueleto":"def custo_varredura(n, d, bytes_por_numero=4):\n    ...\n","testes":[{"nome":"base pequena","codigo":"assert custo_varredura(10_000, 768) == {\"multiplicacoes\": 7_680_000, \"bytes\": 30_720_000}"},{"nome":"um milhão","codigo":"assert custo_varredura(1_000_000, 768)[\"bytes\"] == 3_072_000_000"},{"nome":"halfvec","codigo":"assert custo_varredura(1_000, 768, 2)[\"bytes\"] == 1_536_000"}],"solucao":"```python\ndef custo_varredura(n, d, bytes_por_numero=4):\n    return {\"multiplicacoes\": n * d, \"bytes\": n * d * bytes_por_numero}\n```\nLinear em `n` e em `d`: dobrou a base, dobrou o custo. E repare no segundo número: 1 milhão de vetores de 768 dimensões são 3 GB percorridos **por consulta**. O gargalo é memória lida, não aritmética.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-01"},{"cap":1,"tipo":"python","nivel":1,"tempo":10,"titulo":"A varredura, com o contador","enunciado":"Escreva `varredura(consulta, base, k)` que devolve `(ids, distancias)`: os `k` ids de `base` (dicionário `id → vetor`) mais próximos por cosseno decrescente (empate pelo id) e **quantas distâncias foram calculadas**. O contador é o que a página 3 inteira tenta reduzir. `cosseno(a, b)` já está definida.","esqueleto":"import math\n\ndef cosseno(a, b):\n    na = math.sqrt(sum(x*x for x in a)); nb = math.sqrt(sum(x*x for x in b))\n    return sum(x*y for x, y in zip(a, b)) / (na * nb) if na and nb else 0.0\nBASE = {\"a\": [1.0, 0.0, 0.0], \"b\": [0.9, 0.1, 0.0], \"c\": [0.0, 1.0, 0.0], \"d\": [0.0, 0.0, 1.0], \"e\": [0.7, 0.7, 0.0]}\n\ndef varredura(consulta, base, k):\n    ...\n","setup":"import math\n\ndef cosseno(a, b):\n    na = math.sqrt(sum(x*x for x in a)); nb = math.sqrt(sum(x*x for x in b))\n    return sum(x*y for x, y in zip(a, b)) / (na * nb) if na and nb else 0.0\nBASE = {\"a\": [1.0, 0.0, 0.0], \"b\": [0.9, 0.1, 0.0], \"c\": [0.0, 1.0, 0.0], \"d\": [0.0, 0.0, 1.0], \"e\": [0.7, 0.7, 0.0]}\n","testes":[{"nome":"top-2 e contador","codigo":"assert varredura([1, 0, 0], BASE, 2) == ([\"a\", \"b\"], 5)"},{"nome":"o contador é sempre N","codigo":"assert varredura([0, 0, 1], BASE, 1) == ([\"d\"], 5) and varredura([0, 0, 1], BASE, 5)[1] == 5"},{"nome":"empate pelo id","codigo":"assert varredura([0, 0, 1], {\"y\": [0, 1, 0], \"x\": [1, 0, 0]}, 2) == ([\"x\", \"y\"], 2)"}],"solucao":"```python\ndef varredura(consulta, base, k):\n    ordem = sorted(base, key=lambda i: (-cosseno(consulta, base[i]), i))\n    return (ordem[:k], len(base))\n```\nO contador não depende de `k` nem da consulta: é sempre `N`. É essa constante que o índice quebra.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-02"},{"cap":1,"tipo":"calculo","nivel":1,"tempo":6,"titulo":"Medir uma vez, extrapolar","enunciado":"Nesta máquina, uma varredura exata sobre 10.000 vetores de 768 dimensões levou 8 ms. Os vetores são `float32` (4 bytes por número).","campos":[{"label":"multiplicações por consulta com 10 mil linhas","valor":7680000,"rel":0.001},{"label":"tempo estimado para 1 milhão de linhas (ms)","valor":800,"tol":1},{"label":"tempo estimado para 10 mil linhas com 256 dimensões (ms)","valor":2.67,"tol":0.02},{"label":"GB percorridos por consulta com 1 milhão de linhas (1 GB = 10⁹ bytes)","valor":3.07,"tol":0.02}],"solucao":"10.000 × 768 = 7,68 M multiplicações. 1 milhão é 100× a base → 800 ms. 256 dimensões é um terço → 2,67 ms. Memória: 10⁶ × 768 × 4 = 3,07 GB por consulta. Linear é previsível: mediu uma vez, extrapola com segurança.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-03"},{"cap":1,"tipo":"python","nivel":2,"tempo":10,"titulo":"Extrapolar sem medir de novo","enunciado":"Escreva `extrapolar(ms, n0, d0, n1, d1)` que devolve o tempo estimado (em ms) para `n1` linhas e `d1` dimensões, sabendo que `n0` linhas com `d0` dimensões levaram `ms`. O custo é linear nos dois.","esqueleto":"def extrapolar(ms, n0, d0, n1, d1):\n    ...\n","testes":[{"nome":"dobrar as linhas","codigo":"assert abs(extrapolar(8, 10_000, 768, 20_000, 768) - 16) < 1e-9"},{"nome":"reduzir as dimensões","codigo":"assert abs(extrapolar(8, 10_000, 768, 10_000, 256) - 8/3) < 1e-9"},{"nome":"cem vezes maior","codigo":"assert abs(extrapolar(8, 10_000, 768, 1_000_000, 768) - 800) < 1e-9"},{"nome":"os dois ao mesmo tempo","codigo":"assert abs(extrapolar(10, 1_000, 100, 4_000, 50) - 20) < 1e-9"}],"solucao":"```python\ndef extrapolar(ms, n0, d0, n1, d1):\n    return ms * (n1 / n0) * (d1 / d0)\n```\nSó vale porque o custo é linear. Nenhum índice aproximado permite essa conta: neles o custo cresce com o logaritmo de N e depende dos parâmetros.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-04"},{"cap":1,"tipo":"python","nivel":2,"tempo":10,"titulo":"Os k melhores sem ordenar tudo","enunciado":"Escreva `top_k(scores, k)` que devolve os `k` maiores de uma lista de `(id, score)` em ordem decrescente de score (empate pelo id), mantendo no máximo `k` itens em memória durante a passagem — use `heapq.nsmallest`/`nlargest` ou uma fila de prioridade, não `sorted(...)` na lista inteira. Ordenar tudo custa N·log N; manter os k melhores custa N·log k.","esqueleto":"import heapq\n\ndef top_k(scores, k):\n    ...\n","testes":[{"nome":"ordem decrescente","codigo":"assert top_k([(\"a\", 0.2), (\"b\", 0.9), (\"c\", 0.5)], 2) == [(\"b\", 0.9), (\"c\", 0.5)]"},{"nome":"empate pelo id","codigo":"assert top_k([(\"z\", 0.5), (\"a\", 0.5), (\"m\", 0.9)], 3) == [(\"m\", 0.9), (\"a\", 0.5), (\"z\", 0.5)]"},{"nome":"k maior que a lista","codigo":"assert top_k([(\"a\", 1.0)], 5) == [(\"a\", 1.0)]"},{"nome":"vazio","codigo":"assert top_k([], 3) == []"}],"solucao":"```python\nimport heapq\n\ndef top_k(scores, k):\n    return heapq.nsmallest(k, scores, key=lambda p: (-p[1], p[0]))\n```\nA chave `(-score, id)` faz o desempate alfabético. Em bases grandes a diferença entre N·log N e N·log k some diante do custo de ler os vetores, mas é a forma certa de escrever.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-05"},{"cap":1,"tipo":"js","nivel":1,"tempo":8,"titulo":"A varredura em JavaScript","enunciado":"Escreva `varredura(q, base, k)` que recebe um array de `{id, vetor}` e devolve `{ids, distancias}`: os `k` ids mais próximos por cosseno decrescente e o número de distâncias calculadas.","esqueleto":"function varredura(q, base, k) {\n  // ...\n}\n","exports":["varredura"],"testes":[{"nome":"ids e contador","codigo":"(() => { const r = varredura([1, 0], [{id: \"a\", vetor: [1, 0]}, {id: \"b\", vetor: [0.6, 0.8]}, {id: \"c\", vetor: [0, 1]}], 2); return iguais(r.ids, [\"a\", \"b\"]) && r.distancias === 3; })()"},{"nome":"contador não depende de k","codigo":"varredura([1, 0], [{id: \"a\", vetor: [1, 0]}, {id: \"b\", vetor: [0, 1]}], 1).distancias === 2"},{"nome":"base vazia","codigo":"(() => { const r = varredura([1, 0], [], 3); return iguais(r.ids, []) && r.distancias === 0; })()"}],"solucao":"```js\nfunction varredura(q, base, k) {\n  const dot = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0), n = (a) => Math.hypot(...a);\n  const scores = base.map(({ id, vetor }) => ({ id, s: dot(q, vetor) / (n(q) * n(vetor) || 1) }));\n  scores.sort((a, b) => b.s - a.s || a.id.localeCompare(b.id));\n  return { ids: scores.slice(0, k).map((x) => x.id), distancias: base.length };\n}\n```\nÉ o que o experimento \"cronômetro da varredura completa\" roda no navegador.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-06"},{"cap":1,"tipo":"calculo","nivel":2,"tempo":8,"titulo":"Quantas linhas cabem no orçamento","enunciado":"O ia-worker tem um orçamento de 50 ms para a etapa de recuperação. A varredura exata mede 8 ms para 10.000 linhas de 768 dimensões. Cada consulta do sistema faz uma busca vetorial.","campos":[{"label":"linhas que cabem no orçamento com 768 dimensões","valor":62500,"rel":0.02},{"label":"linhas que cabem se truncar para 256 dimensões","valor":187500,"rel":0.02},{"label":"tempo da varredura com 30 mil linhas (ms)","valor":24,"tol":0.5}],"solucao":"8 ms / 10.000 linhas → 50 ms comportam 62.500 linhas; com 256 dimensões o custo por linha cai a um terço, então cabem 187.500. Os 30 mil dispositivos da base curada levam 24 ms: ainda dentro do orçamento, e é por isso que a decisão de indexar no projeto veio da previsão de crescimento, não do tamanho de hoje.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-07"},{"cap":1,"tipo":"python","nivel":2,"tempo":10,"titulo":"A partir de quantas linhas indexar","enunciado":"Escreva `limite_de_linhas(ms_alvo, ms_medido, n_medido)` que devolve quantas linhas cabem no orçamento (inteiro, arredondado para baixo) e `precisa_indice(n, ms_alvo, ms_medido, n_medido)` que devolve `True` se `n` linhas estourarem o orçamento.","esqueleto":"def limite_de_linhas(ms_alvo, ms_medido, n_medido):\n    ...\n\ndef precisa_indice(n, ms_alvo, ms_medido, n_medido):\n    ...\n","testes":[{"nome":"limite","codigo":"assert limite_de_linhas(50, 8, 10_000) == 62_500"},{"nome":"arredonda para baixo","codigo":"assert limite_de_linhas(10, 3, 1_000) == 3_333"},{"nome":"não precisa","codigo":"assert precisa_indice(30_000, 50, 8, 10_000) is False"},{"nome":"precisa","codigo":"assert precisa_indice(500_000, 50, 8, 10_000) is True"},{"nome":"no limite exato não precisa","codigo":"assert precisa_indice(62_500, 50, 8, 10_000) is False"}],"solucao":"```python\ndef limite_de_linhas(ms_alvo, ms_medido, n_medido):\n    return int(n_medido * ms_alvo / ms_medido)\n\ndef precisa_indice(n, ms_alvo, ms_medido, n_medido):\n    return n > limite_de_linhas(ms_alvo, ms_medido, n_medido)\n```\nA regra do capítulo 9 em código: meça a exata, indexe quando a latência exigir. Não indexe \"porque é o certo\".","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-08"},{"cap":1,"tipo":"sql","nivel":1,"tempo":6,"titulo":"A varredura exata em SQL","enunciado":"Escreva a consulta que devolve os 12 trechos mais próximos de `%s::vector` em `rag.trecho_normativo`, com a similaridade como `1 - (embedding <=> %s::vector)`, sem nenhum índice envolvido (é o `Seq Scan` do capítulo 1). Filtre por `modelo_embedding = %s`.","esqueleto":"SELECT ...\n","checks":[{"re":"rag\\.trecho_normativo","msg":"consulta a tabela do projeto"},{"re":"1\\s*-\\s*\\(\\s*embedding\\s*<=>\\s*%s::vector\\s*\\)","msg":"similaridade como 1 − distância"},{"re":"WHERE\\s+modelo_embedding\\s*=\\s*%s","msg":"filtra pelo modelo"},{"re":"ORDER BY\\s+embedding\\s*<=>\\s*%s::vector","msg":"ordena pela distância de cosseno"},{"re":"LIMIT\\s+12","msg":"limita a 12"}],"solucao":"```sql\nSELECT id, dispositivo, 1 - (embedding <=> %s::vector) AS similaridade\nFROM rag.trecho_normativo\nWHERE modelo_embedding = %s\nORDER BY embedding <=> %s::vector\nLIMIT 12;\n```\nSem índice na coluna, esta consulta é um `Seq Scan` + `Sort`: exata por definição (recall 100%) e linear. A forma do `ORDER BY` já é a certa para quando o índice existir — o capítulo 6 explica por quê.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-09"},{"cap":1,"tipo":"dados","nivel":1,"tempo":6,"titulo":"A tabela de tempos","enunciado":"Uma varredura de 10.000 linhas com 768 dimensões leva 8 ms. Complete os tempos, uma linha por caso, no formato `linhas x dims: T ms` (T com uma casa decimal, ponto como separador): 20.000×768, 10.000×384, 100.000×768, 5.000×1536.","modo":"conjunto","esperado":"20000 x 768: 16.0 ms\n10000 x 384: 4.0 ms\n100000 x 768: 80.0 ms\n5000 x 1536: 8.0 ms","solucao":"Linear nos dois fatores: dobrar linhas dobra o tempo (16 ms); metade das dimensões, metade do tempo (4 ms); 10× linhas, 10× tempo (80 ms); metade das linhas com o dobro das dimensões dá exatamente o mesmo (8 ms). É o produto N × d que manda.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-10"},{"cap":1,"tipo":"js","nivel":1,"tempo":6,"titulo":"Memória percorrida por consulta","enunciado":"Escreva `bytesPercorridos(n, d, tipo = \"vector\")` que devolve os bytes lidos numa varredura exata: `vector` usa 4 bytes por dimensão, `halfvec` usa 2. E `emGB(bytes)`, com duas casas decimais (1 GB = 10⁹ bytes).","esqueleto":"function bytesPercorridos(n, d, tipo = \"vector\") {\n  // ...\n}\nfunction emGB(bytes) {\n  // ...\n}\n","exports":["bytesPercorridos","emGB"],"testes":[{"nome":"vector","codigo":"bytesPercorridos(1e6, 768) === 3.072e9"},{"nome":"halfvec é metade","codigo":"bytesPercorridos(1e6, 768, \"halfvec\") === 1.536e9"},{"nome":"em GB","codigo":"emGB(3.072e9) === 3.07 && emGB(1.536e9) === 1.54"}],"solucao":"```js\nfunction bytesPercorridos(n, d, tipo = \"vector\") {\n  return n * d * (tipo === \"halfvec\" ? 2 : 4);\n}\nfunction emGB(bytes) {\n  return Math.round(bytes / 1e9 * 100) / 100;\n}\n```\nO `halfvec` corta a memória do vetor pela metade com uma perda de precisão que raramente importa — o capítulo 8 mostra que ele não corta as ligações do índice.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-11"},{"cap":1,"tipo":"texto","nivel":2,"tempo":8,"titulo":"Linear: a qualidade e o defeito","enunciado":"Em até 5 linhas: por que a busca exata é linear, por que isso é a maior qualidade dela em bases pequenas e o maior defeito em bases grandes.","rubrica":["Linear porque cada linha exige um produto escalar de d multiplicações: custo N × d, sem exceção","Qualidade: previsível (mediu uma vez, extrapola), exata por definição (recall 100%) e sem nada para configurar ou manter","Defeito: dobrou a base, dobrou o tempo — não existe escala que o salve","Citou que o custo dominante real é percorrer os vetores na memória, não a aritmética"],"solucao":"É linear porque cada linha custa um produto escalar de `d` multiplicações e não há como pular linhas: são N × d operações e N vetores lidos. Em base pequena isso é uma virtude tripla: recall 100% por definição, latência previsível (mediu 10 mil, sabe 30 mil) e zero manutenção. Em base grande é fatal, porque não há constante que segure crescimento linear: paralelismo divide por um fator fixo, o índice muda a curva para logarítmica.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-12"},{"cap":1,"tipo":"texto","nivel":1,"tempo":5,"titulo":"Paralelizar não resolve","enunciado":"Em 3 linhas: por que paralelizar a varredura (workers do PostgreSQL, GPU) não substitui um índice.","rubrica":["Paralelismo divide o tempo por um fator fixo (número de workers/núcleos)","A base cresce sem limite; a constante não acompanha","O índice muda a forma do custo, de linear para aproximadamente logarítmico — é isso que escala"],"solucao":"Paralelizar divide o tempo por uma constante: com 8 workers, 800 ms viram 100 ms, e é só. A base, porém, cresce sem teto, e a cada duplicação o tempo volta a dobrar. O índice não divide o custo, muda a curva — de linear em N para aproximadamente logarítmico —, e é isso que ainda funciona quando a base multiplica por mil.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-13"},{"cap":1,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"Paralelismo contra índice","enunciado":"Base de 1 milhão de linhas, varredura exata em 800 ms. A máquina tem 8 workers paralelos. Um HNSW responde em 2 ms.","campos":[{"label":"tempo da varredura com 8 workers (ms)","valor":100,"tol":1},{"label":"tempo da varredura paralela se a base for a 10 milhões (ms)","valor":1000,"tol":5},{"label":"quantas vezes o índice é mais rápido que a varredura paralela em 1 milhão","valor":50,"tol":1}],"solucao":"800 / 8 = 100 ms. Com 10× a base, a paralela volta a 1.000 ms: a constante não acompanha o crescimento. O índice em 2 ms é 50× mais rápido que a paralela hoje — e a distância aumenta a cada duplicação da base, porque um custo é linear e o outro é logarítmico.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-14"},{"cap":1,"tipo":"projeto","nivel":2,"tempo":25,"titulo":"Medir a varredura exata no seu banco","enunciado":"No PostgreSQL do Ex. 3, com a tabela carregada e **sem** índice vetorial, rode `EXPLAIN (ANALYZE, BUFFERS)` da consulta exata para 5 perguntas diferentes. Anote o `Execution Time` da segunda execução em diante (índice quente) e confirme que o plano é `Seq Scan`. Depois estime, com a regra linear, o tempo para 10× e 100× a base atual.","entrega":"Cinco tempos medidos, o plano observado e as duas extrapolações.","rubrica":["Rodei EXPLAIN (ANALYZE, BUFFERS) e vi `Seq Scan` (nenhum índice vetorial existe ainda)","Descartei a primeira execução e usei as seguintes (cache quente)","Anotei o Execution Time de 5 consultas, não de uma só","Extrapolei linearmente para 10× e 100× a base e disse a partir de onde o índice passa a ser necessário"],"solucao":"O esperado com a base do guia (dezenas de trechos a alguns milhares): `Seq Scan` com `Execution Time` de fração de milissegundo a poucos milissegundos, praticamente constante entre consultas — a varredura não depende da consulta, só do tamanho. Extrapolar é multiplicar: 100× a base, 100× o tempo. O número que interessa não é o de hoje, é onde a reta cruza o orçamento de latência.","ligacoes":["03-busca-vetorial.html#c1"],"id":"p3-c1-15"},{"cap":2,"tipo":"python","nivel":1,"tempo":8,"titulo":"Recall do índice","enunciado":"Escreva `recall_indice(exato, aprox)` que devolve a fração dos ids da lista `exato` (a resposta da busca exata) que aparecem em `aprox` (a resposta do índice). Divida sempre por `len(exato)`; lista exata vazia devolve `0.0`.","esqueleto":"def recall_indice(exato, aprox):\n    ...\n","testes":[{"nome":"nove de dez","codigo":"assert abs(recall_indice(list(\"abcdefghij\"), list(\"abcdefghix\")) - 0.9) < 1e-9"},{"nome":"ordem não importa","codigo":"assert recall_indice([\"a\", \"b\", \"c\"], [\"c\", \"b\", \"a\"]) == 1.0"},{"nome":"nenhum","codigo":"assert recall_indice([\"a\", \"b\"], [\"x\", \"y\"]) == 0.0"},{"nome":"exato vazio","codigo":"assert recall_indice([], [\"a\"]) == 0.0"},{"nome":"extras não contam","codigo":"assert abs(recall_indice([\"a\", \"b\"], [\"a\", \"x\", \"y\", \"z\"]) - 0.5) < 1e-9"}],"solucao":"```python\ndef recall_indice(exato, aprox):\n    if not exato: return 0.0\n    return len(set(exato) & set(aprox)) / len(exato)\n```\nRepare que a ordem não entra: recall mede **quais** vizinhos vieram, não em que posição. É uma propriedade do índice, medida contra a busca exata com as mesmas consultas.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-01"},{"cap":2,"tipo":"python","nivel":2,"tempo":10,"titulo":"Média e pior caso","enunciado":"Escreva `resumo_recall(pares)` que recebe uma lista de `(exato, aprox)` e devolve `{\"medio\": …, \"minimo\": …, \"perfeitos\": n}`: o recall médio, o pior recall e quantas consultas tiveram recall 1,0. Média esconde; o mínimo é o que você mostra ao lado dela.","esqueleto":"def recall_indice(exato, aprox):\n    if not exato: return 0.0\n    return len(set(exato) & set(aprox)) / len(exato)\n\ndef resumo_recall(pares):\n    ...\n","setup":"def recall_indice(exato, aprox):\n    if not exato: return 0.0\n    return len(set(exato) & set(aprox)) / len(exato)\n","testes":[{"nome":"três consultas","codigo":"P = [(list(\"abcd\"), list(\"abcd\")), (list(\"abcd\"), list(\"abcx\")), (list(\"abcd\"), list(\"abxy\"))]\nr = resumo_recall(P)\nassert abs(r[\"medio\"] - 0.75) < 1e-9 and abs(r[\"minimo\"] - 0.5) < 1e-9 and r[\"perfeitos\"] == 1"},{"nome":"todas perfeitas","codigo":"r = resumo_recall([([\"a\"], [\"a\"]), ([\"b\"], [\"b\"])])\nassert r == {\"medio\": 1.0, \"minimo\": 1.0, \"perfeitos\": 2}"},{"nome":"lista vazia","codigo":"assert resumo_recall([]) == {\"medio\": 0.0, \"minimo\": 0.0, \"perfeitos\": 0}"}],"solucao":"```python\ndef resumo_recall(pares):\n    if not pares:\n        return {\"medio\": 0.0, \"minimo\": 0.0, \"perfeitos\": 0}\n    rs = [recall_indice(e, a) for e, a in pares]\n    return {\"medio\": sum(rs) / len(rs), \"minimo\": min(rs), \"perfeitos\": sum(1 for r in rs if r == 1.0)}\n```\nConsultas em regiões densas (os incisos do art. 75, por exemplo) perdem mais vizinhos: a média de 0,95 pode esconder uma consulta em 0,5.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-02"},{"cap":2,"tipo":"calculo","nivel":2,"tempo":8,"titulo":"Os dois recalls se compõem","enunciado":"O modelo de embedding coloca o trecho esperado entre os 12 primeiros da busca **exata** em 90% das perguntas. O índice HNSW tem recall@12 = 0,95. O conjunto de avaliação tem 200 perguntas.","campos":[{"label":"perguntas com o trecho esperado no top-12 da busca exata","valor":180,"tol":0.5},{"label":"estimativa do acerto do sistema com o índice (fração)","valor":0.855,"tol":0.002},{"label":"perguntas perdidas por causa do índice","valor":9,"tol":0.5}],"solucao":"180 das 200 perguntas têm o trecho no top-12 exato. Com o índice devolvendo 95% dos vizinhos verdadeiros, sobram 0,90 × 0,95 = 0,855, ou 171 perguntas: 9 perdidas por conta do índice, não do modelo. Os dois recalls se multiplicam, e é por isso que o do índice se mede separado.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-03"},{"cap":2,"tipo":"texto","nivel":2,"tempo":8,"titulo":"Dois recalls com o mesmo nome","enunciado":"Em até 5 linhas: qual é a diferença entre o recall do índice (esta página) e o recall@k da página 8, e por que os dois precisam ser medidos separadamente.","rubrica":["Recall do índice: dos k vizinhos que a busca exata devolveria, quantos o índice devolveu — propriedade do índice, medida contra a exata","Recall@k da página 8: em quantas perguntas o trecho esperado está entre os k — propriedade do modelo, da segmentação e da busca","Os dois se compõem (multiplicam), então um número ruim no sistema pode vir de qualquer um dos dois","Medir separado é o que permite saber qual botão mexer: ef_search/m ou modelo/segmentação"],"solucao":"O recall do índice compara duas listas de vizinhos: a do índice contra a da busca exata, com a mesma consulta. Ele mede só o que a aproximação perdeu, e não sabe nada sobre relevância. O recall@k da página 8 compara a lista com o **trecho esperado** de uma pergunta: mede modelo, segmentação e busca juntos. Como os dois se multiplicam, medir só o de baixo não diz qual camada está falhando — e cada uma tem botões diferentes.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-04"},{"cap":2,"tipo":"python","nivel":3,"tempo":12,"titulo":"Onde a curva achata","enunciado":"Escreva `ponto_de_achatamento(medicoes, ganho_minimo=0.01)` que recebe uma lista de `{\"ef\": …, \"recall\": …}` ordenada por `ef` crescente e devolve o menor `ef` a partir do qual **dobrar** o esforço não rende mais que `ganho_minimo` de recall. Compare cada medição com a seguinte; se nenhuma achatar, devolva o maior `ef`.","esqueleto":"def ponto_de_achatamento(medicoes, ganho_minimo=0.01):\n    ...\n","testes":[{"nome":"achata em 40","codigo":"M = [{\"ef\": 10, \"recall\": 0.72}, {\"ef\": 20, \"recall\": 0.88}, {\"ef\": 40, \"recall\": 0.95}, {\"ef\": 80, \"recall\": 0.955}, {\"ef\": 160, \"recall\": 0.957}]\nassert ponto_de_achatamento(M) == 40"},{"nome":"nunca achata","codigo":"M = [{\"ef\": 10, \"recall\": 0.5}, {\"ef\": 20, \"recall\": 0.7}, {\"ef\": 40, \"recall\": 0.9}]\nassert ponto_de_achatamento(M) == 40"},{"nome":"achata logo","codigo":"M = [{\"ef\": 10, \"recall\": 0.99}, {\"ef\": 20, \"recall\": 0.992}, {\"ef\": 40, \"recall\": 0.993}]\nassert ponto_de_achatamento(M) == 10"}],"solucao":"```python\ndef ponto_de_achatamento(medicoes, ganho_minimo=0.01):\n    for atual, seguinte in zip(medicoes, medicoes[1:]):\n        if seguinte[\"recall\"] - atual[\"recall\"] <= ganho_minimo:\n            return atual[\"ef\"]\n    return medicoes[-1][\"ef\"]\n```\nÉ a leitura da curva recall × custo: o ponto onde o recall já estabilizou e o custo ainda é baixo. Acima dele você paga latência por décimos de recall.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-05"},{"cap":2,"tipo":"python","nivel":2,"tempo":10,"titulo":"O menor esforço que atinge o alvo","enunciado":"Escreva `escolher_ef(medicoes, alvo)` que devolve o menor `ef` cujo recall alcança `alvo`, ou `None` se nenhum alcançar. É a última linha do protocolo do capítulo 8.","esqueleto":"def escolher_ef(medicoes, alvo):\n    ...\n","testes":[{"nome":"menor que atinge","codigo":"M = [{\"ef\": 10, \"recall\": 0.72}, {\"ef\": 40, \"recall\": 0.95}, {\"ef\": 100, \"recall\": 0.98}]\nassert escolher_ef(M, 0.95) == 40"},{"nome":"nenhum atinge","codigo":"M = [{\"ef\": 10, \"recall\": 0.72}, {\"ef\": 40, \"recall\": 0.9}]\nassert escolher_ef(M, 0.99) is None"},{"nome":"fora de ordem","codigo":"M = [{\"ef\": 100, \"recall\": 0.98}, {\"ef\": 10, \"recall\": 0.96}, {\"ef\": 40, \"recall\": 0.97}]\nassert escolher_ef(M, 0.95) == 10"}],"solucao":"```python\ndef escolher_ef(medicoes, alvo):\n    validos = [m[\"ef\"] for m in medicoes if m[\"recall\"] >= alvo]\n    return min(validos) if validos else None\n```\nRepare no último teste: a função não pode supor que a lista veio ordenada. E `None` é uma resposta legítima — significa que o problema não está no `ef_search`, e sim em `m` ou `ef_construction`.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-06"},{"cap":2,"tipo":"calculo","nivel":1,"tempo":5,"titulo":"Ler um recall","enunciado":"Um índice mede recall@10 = 0,93 sobre 60 consultas de avaliação.","campos":[{"label":"vizinhos exatos recuperados, em média, por consulta","valor":9.3,"tol":0.01},{"label":"vizinhos exatos perdidos no total das 60 consultas","valor":42,"tol":0.5},{"label":"recall se o índice devolvesse 10 de 10 em 55 consultas e 5 de 10 nas outras 5","valor":0.958,"tol":0.002}],"solucao":"0,93 × 10 = 9,3 vizinhos por consulta; 0,7 perdidos por consulta × 60 = 42 no total. No terceiro caso, (55 × 10 + 5 × 5) / 600 = 575/600 = 0,958: uma média alta que esconde cinco consultas com metade dos vizinhos perdidos. Média sem mínimo engana.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-07"},{"cap":2,"tipo":"js","nivel":1,"tempo":8,"titulo":"Recall em JavaScript","enunciado":"Escreva `recall(exato, aprox)` (fração dos ids de `exato` presentes em `aprox`) e `recallMedio(pares)` que recebe um array de `[exato, aprox]` e devolve a média com 3 casas decimais.","esqueleto":"function recall(exato, aprox) {\n  // ...\n}\nfunction recallMedio(pares) {\n  // ...\n}\n","exports":["recall","recallMedio"],"testes":[{"nome":"recall simples","codigo":"aprox(recall([\"a\", \"b\", \"c\", \"d\"], [\"a\", \"b\", \"c\", \"x\"]), 0.75)"},{"nome":"exato vazio","codigo":"recall([], [\"a\"]) === 0"},{"nome":"média arredondada","codigo":"recallMedio([[[\"a\", \"b\"], [\"a\", \"b\"]], [[\"a\", \"b\"], [\"a\", \"x\"]]]) === 0.75"},{"nome":"três casas","codigo":"recallMedio([[[\"a\", \"b\", \"c\"], [\"a\", \"b\", \"c\"]], [[\"a\", \"b\", \"c\"], [\"a\", \"x\", \"y\"]]]) === 0.667"}],"solucao":"```js\nfunction recall(exato, aprox) {\n  if (!exato.length) return 0;\n  const s = new Set(aprox);\n  return exato.filter((x) => s.has(x)).length / exato.length;\n}\nfunction recallMedio(pares) {\n  if (!pares.length) return 0;\n  const m = pares.reduce((acc, [e, a]) => acc + recall(e, a), 0) / pares.length;\n  return Math.round(m * 1000) / 1000;\n}\n```","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-08"},{"cap":2,"tipo":"dados","nivel":1,"tempo":6,"titulo":"A curva em números","enunciado":"De uma rodada do experimento do capítulo 4: ef_search 10 → recall 0,72 e 180 distâncias; 20 → 0,88 e 340; 40 → 0,95 e 660; 80 → 0,955 e 1300; 160 → 0,957 e 2580. Escreva, uma linha por passo, o ganho de recall e o custo extra em distâncias ao dobrar o ef, no formato `10→20: +0.16 recall, +160 distancias`. Uma linha para cada um dos quatro passos.","modo":"conjunto","esperado":"10→20: +0.16 recall, +160 distancias\n20→40: +0.07 recall, +320 distancias\n40→80: +0.005 recall, +640 distancias\n80→160: +0.002 recall, +1280 distancias","solucao":"O retorno decrescente fica evidente: de 10 para 20 o recall sobe 0,16 pagando 160 distâncias; de 80 para 160 sobe 0,002 pagando 1.280. A curva achatou em 40 — dali em diante você compra latência, não recall.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-09"},{"cap":2,"tipo":"texto","nivel":1,"tempo":6,"titulo":"Recall 0,95 é bom?","enunciado":"Em 3 linhas: por que 0,95 em k = 12 é confortável para este projeto, e o que faria você subir ou não subir esse número.","rubrica":["A busca híbrida traz 50 candidatos de cada lado antes de fundir; o modelo lê 12 — um vizinho perdido em 20 raramente é o único trecho relevante","Abaixo de ~0,90 vale subir o esforço; acima de ~0,98 o custo extra quase nunca compensa","O número certo vem do efeito no recall do sistema, medido no conjunto de avaliação da página 8"],"solucao":"Porque o índice não é a última palavra: ele entrega 50 candidatos que a fusão RRF e o modelo ainda filtram, então perder um vizinho em vinte quase nunca é perder o único trecho que respondia. Abaixo de 0,90 começa a valer subir o `ef_search`; acima de 0,98 você paga latência por décimos. E quem decide é o conjunto de avaliação: recall do índice se calibra pelo efeito no recall do sistema.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-10"},{"cap":2,"tipo":"texto","nivel":2,"tempo":6,"titulo":"Por que não uma árvore","enunciado":"Em 3 linhas: por que estruturas exatas como k-d trees não resolvem a busca de vizinhos em 768 dimensões.","rubrica":["Árvores funcionam bem até umas 20 dimensões","Em alta dimensão as distâncias ficam todas parecidas (\"maldição da dimensionalidade\") e a árvore acaba visitando quase tudo","Por isso os índices que escalam em 768 dimensões são aproximados: grafos (HNSW), partições (IVF) e quantização"],"solucao":"k-d trees e ball trees dividem o espaço por eixos ou esferas e só funcionam enquanto uma divisão consegue descartar grande parte dos pontos — o que vale até umas 20 dimensões. Em 768, as distâncias entre pontos ficam todas parecidas e nenhum corte descarta muito: a árvore visita quase tudo e vira uma varredura com sobrecarga. Em alta dimensão, exato e rápido não coexistem; sobram os aproximados.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-11"},{"cap":2,"tipo":"python","nivel":3,"tempo":12,"titulo":"Recall por região","enunciado":"Escreva `recall_por_regiao(resultados)` que recebe uma lista de `{\"regiao\": str, \"exato\": [...], \"aprox\": [...]}` e devolve `{regiao: recall_medio}` com as chaves em ordem alfabética e cada média arredondada a 3 casas. É como se descobre que as regiões densas perdem mais.","esqueleto":"def recall_indice(exato, aprox):\n    if not exato: return 0.0\n    return len(set(exato) & set(aprox)) / len(exato)\n\ndef recall_por_regiao(resultados):\n    ...\n","setup":"def recall_indice(exato, aprox):\n    if not exato: return 0.0\n    return len(set(exato) & set(aprox)) / len(exato)\n","testes":[{"nome":"duas regiões","codigo":"R = [{\"regiao\": \"densa\", \"exato\": list(\"abcd\"), \"aprox\": list(\"abxy\")},\n     {\"regiao\": \"densa\", \"exato\": list(\"abcd\"), \"aprox\": list(\"abcx\")},\n     {\"regiao\": \"esparsa\", \"exato\": list(\"abcd\"), \"aprox\": list(\"abcd\")}]\nassert recall_por_regiao(R) == {\"densa\": 0.625, \"esparsa\": 1.0}"},{"nome":"ordem alfabética","codigo":"R = [{\"regiao\": \"z\", \"exato\": [\"a\"], \"aprox\": [\"a\"]}, {\"regiao\": \"a\", \"exato\": [\"b\"], \"aprox\": [\"x\"]}]\nassert list(recall_por_regiao(R)) == [\"a\", \"z\"]"}],"solucao":"```python\ndef recall_por_regiao(resultados):\n    por = {}\n    for r in resultados:\n        por.setdefault(r[\"regiao\"], []).append(recall_indice(r[\"exato\"], r[\"aprox\"]))\n    return {k: round(sum(v) / len(v), 3) for k, v in sorted(por.items())}\n```\nConsultas em aglomerados (muitos trechos quase empatados) perdem mais vizinhos que consultas em regiões vazias. É a razão de medir com dezenas de consultas reais, não com vetores aleatórios.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-12"},{"cap":2,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"Quanto custa cada décimo","enunciado":"Da curva do experimento: ef 40 dá recall 0,950 com 660 distâncias por consulta; ef 160 dá 0,957 com 2.580.","campos":[{"label":"ganho de recall ao ir de 40 para 160","valor":0.007,"tol":0.0005},{"label":"distâncias extras por consulta","valor":1920,"tol":1},{"label":"distâncias extras por ponto de recall ganho (por 0,001)","valor":274,"tol":3}],"solucao":"Ganho de 0,007 por 1.920 distâncias extras: cerca de 274 distâncias por milésimo de recall. Compare com o primeiro trecho da curva, onde 160 distâncias compravam 0,16 (1 distância por milésimo). O retorno decrescente é de três ordens de grandeza.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-13"},{"cap":2,"tipo":"python","nivel":2,"tempo":10,"titulo":"Compor os dois recalls","enunciado":"Escreva `recall_sistema(recall_modelo, recall_indice)` que devolve a estimativa do recall do sistema (produto) e `perda_do_indice(n_perguntas, recall_modelo, recall_indice)` que devolve quantas perguntas se perdem por causa do índice, arredondado para o inteiro mais próximo.","esqueleto":"def recall_sistema(recall_modelo, recall_indice):\n    ...\n\ndef perda_do_indice(n_perguntas, recall_modelo, recall_indice):\n    ...\n","testes":[{"nome":"produto","codigo":"assert abs(recall_sistema(0.90, 0.95) - 0.855) < 1e-9"},{"nome":"índice perfeito não perde","codigo":"assert recall_sistema(0.9, 1.0) == 0.9 and perda_do_indice(200, 0.9, 1.0) == 0"},{"nome":"nove perguntas","codigo":"assert perda_do_indice(200, 0.90, 0.95) == 9"},{"nome":"índice ruim","codigo":"assert perda_do_indice(100, 1.0, 0.8) == 20"}],"solucao":"```python\ndef recall_sistema(recall_modelo, recall_indice):\n    return recall_modelo * recall_indice\n\ndef perda_do_indice(n_perguntas, recall_modelo, recall_indice):\n    return round(n_perguntas * recall_modelo * (1 - recall_indice))\n```\nA composição é aproximada (supõe independência), mas serve para o que importa: dizer se o índice é ou não o gargalo antes de mexer nos parâmetros.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-14"},{"cap":2,"tipo":"projeto","nivel":2,"tempo":20,"titulo":"As duas previsões","enunciado":"Antes de rodar o experimento do capítulo 4, escreva as suas previsões: o que acontece com o recall e com o tempo quando (a) a base dobra de tamanho e (b) o `ef_search` dobra. Depois rode o experimento com 1.000 e 2.000 vetores e com ef 40 e 80, e compare com o que você previu.","entrega":"As duas previsões escritas antes, os quatro números medidos e o que surpreendeu.","rubrica":["Escrevi as previsões antes de rodar (o exercício não vale se for depois)","Medi base 1.000 e 2.000 com o mesmo ef, e ef 40 e 80 com a mesma base","Observei que dobrar a base quase não muda o tempo por consulta (custo logarítmico), diferente da varredura exata","Observei que dobrar o ef_search sobe recall e custo juntos, com retorno decrescente"],"solucao":"O que o experimento mostra: dobrar a base aumenta pouco o custo por consulta (o caminho no grafo cresce com o logaritmo de N) e mexe pouco no recall; dobrar o `ef_search` sobe o recall com retorno decrescente e o custo quase linearmente. A surpresa comum é a primeira: quem vem da varredura exata espera que o dobro da base custe o dobro, e não custa — é exatamente por isso que o índice existe.","ligacoes":["03-busca-vetorial.html#c2"],"id":"p3-c2-15"},{"cap":3,"tipo":"python","nivel":3,"tempo":12,"titulo":"A descida gulosa","enunciado":"Escreva `busca_gulosa(entrada, q)` que caminha pelo `GRAFO`: a partir de `entrada`, olha os vizinhos do ponto atual e pula para o mais próximo de `q` **se** ele estiver estritamente mais perto que o atual; para quando nenhum vizinho melhorar. Devolva `(ponto_final, visitados)`, onde `visitados` é o número de distâncias calculadas (uma por vizinho examinado, mais a do ponto de entrada). `PONTOS`, `GRAFO` e `dist(a, b)` já estão definidos.","esqueleto":"import math\n\nPONTOS = {\"p1\": [0.0, 0.0], \"p2\": [1.0, 0.0], \"p3\": [0.0, 1.0], \"p4\": [0.5, 0.5], \"p5\": [3.0, 0.0], \"p6\": [3.5, 0.5]}\nGRAFO = {\"p1\": [\"p2\", \"p3\"], \"p2\": [\"p1\", \"p4\"], \"p3\": [\"p1\", \"p4\"], \"p4\": [\"p2\", \"p3\", \"p5\"], \"p5\": [\"p4\", \"p6\"], \"p6\": [\"p5\"]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n\ndef busca_gulosa(entrada, q):\n    ...\n","setup":"import math\n\nPONTOS = {\"p1\": [0.0, 0.0], \"p2\": [1.0, 0.0], \"p3\": [0.0, 1.0], \"p4\": [0.5, 0.5], \"p5\": [3.0, 0.0], \"p6\": [3.5, 0.5]}\nGRAFO = {\"p1\": [\"p2\", \"p3\"], \"p2\": [\"p1\", \"p4\"], \"p3\": [\"p1\", \"p4\"], \"p4\": [\"p2\", \"p3\", \"p5\"], \"p5\": [\"p4\", \"p6\"], \"p6\": [\"p5\"]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n","testes":[{"nome":"para num mínimo local","codigo":"assert busca_gulosa(\"p1\", [4.0, 0.0])[0] == \"p2\""},{"nome":"conta as distâncias","codigo":"assert busca_gulosa(\"p1\", [4.0, 0.0])[1] == 5"},{"nome":"vindo do outro lado chega ao melhor","codigo":"assert busca_gulosa(\"p5\", [4.0, 0.0])[0] == \"p6\""},{"nome":"já está no melhor","codigo":"assert busca_gulosa(\"p6\", [4.0, 0.0]) == (\"p6\", 2)"}],"solucao":"```python\ndef busca_gulosa(entrada, q):\n    atual = entrada\n    d_atual = dist(PONTOS[atual], q)\n    visitados = 1\n    while True:\n        melhor, d_melhor = None, d_atual\n        for v in GRAFO[atual]:\n            visitados += 1\n            d = dist(PONTOS[v], q)\n            if d < d_melhor:\n                melhor, d_melhor = v, d\n        if melhor is None:\n            return (atual, visitados)\n        atual, d_atual = melhor, d_melhor\n```\nSaindo de `p1` rumo a `[4, 0]`, a busca chega em `p2` e trava: os dois vizinhos de `p2` estão mais longe, embora `p6` esteja logo adiante. É o mínimo local — a razão de existir a lista de candidatos.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-01"},{"cap":3,"tipo":"python","nivel":3,"tempo":20,"titulo":"A lista de candidatos (ef)","enunciado":"Escreva `busca_camada(entrada, q, ef, k)` — a busca do HNSW na camada 0. Mantenha um conjunto de visitados, uma fila de candidatos a expandir e uma lista `W` com os `ef` melhores encontrados. A cada passo, expanda o candidato mais próximo; se ele estiver mais longe que o pior de `W` (com `W` cheio), pare. Cada vizinho ainda não visitado entra em `W` e na fila se `W` não estiver cheio ou se for melhor que o pior. Devolva os `k` ids mais próximos, em ordem.","esqueleto":"import math\n\nPONTOS = {\"p1\": [0.0, 0.0], \"p2\": [1.0, 0.0], \"p3\": [0.0, 1.0], \"p4\": [0.5, 0.5], \"p5\": [3.0, 0.0], \"p6\": [3.5, 0.5]}\nGRAFO = {\"p1\": [\"p2\", \"p3\"], \"p2\": [\"p1\", \"p4\"], \"p3\": [\"p1\", \"p4\"], \"p4\": [\"p2\", \"p3\", \"p5\"], \"p5\": [\"p4\", \"p6\"], \"p6\": [\"p5\"]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n\ndef busca_camada(entrada, q, ef, k):\n    ...\n","setup":"import math\n\nPONTOS = {\"p1\": [0.0, 0.0], \"p2\": [1.0, 0.0], \"p3\": [0.0, 1.0], \"p4\": [0.5, 0.5], \"p5\": [3.0, 0.0], \"p6\": [3.5, 0.5]}\nGRAFO = {\"p1\": [\"p2\", \"p3\"], \"p2\": [\"p1\", \"p4\"], \"p3\": [\"p1\", \"p4\"], \"p4\": [\"p2\", \"p3\", \"p5\"], \"p5\": [\"p4\", \"p6\"], \"p6\": [\"p5\"]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n","dica":"Use `heapq` com duas filas: candidatos por distância crescente e `W` como um max-heap (guarde `-distancia`).","testes":[{"nome":"ef = 1 é o guloso puro e trava","codigo":"assert busca_camada(\"p1\", [4.0, 0.0], 1, 1) == [\"p2\"]"},{"nome":"ef = 2 escapa do mínimo local","codigo":"assert busca_camada(\"p1\", [4.0, 0.0], 2, 1) == [\"p6\"]"},{"nome":"ef alto acha os dois melhores","codigo":"assert busca_camada(\"p1\", [4.0, 0.0], 6, 2) == [\"p6\", \"p5\"]"},{"nome":"k maior que o encontrado","codigo":"assert busca_camada(\"p6\", [4.0, 0.0], 1, 3) == [\"p6\"]"}],"solucao":"```python\nimport heapq\n\ndef busca_camada(entrada, q, ef, k):\n    d0 = dist(PONTOS[entrada], q)\n    visitados = {entrada}\n    candidatos = [(d0, entrada)]          # min-heap: mais perto primeiro\n    W = [(-d0, entrada)]                  # max-heap: o pior no topo\n    while candidatos:\n        d, atual = heapq.heappop(candidatos)\n        if len(W) >= ef and d > -W[0][0]:\n            break\n        for v in GRAFO[atual]:\n            if v in visitados:\n                continue\n            visitados.add(v)\n            dv = dist(PONTOS[v], q)\n            if len(W) < ef or dv < -W[0][0]:\n                heapq.heappush(candidatos, (dv, v))\n                heapq.heappush(W, (-dv, v))\n                if len(W) > ef:\n                    heapq.heappop(W)\n    melhores = sorted((-d, i) for d, i in W)\n    return [i for _, i in melhores[:k]]\n```\nCom `ef = 1` a lista não guarda alternativa nenhuma e a busca é o guloso puro: para em `p2`. Com `ef = 2` ela segura `p4` como alternativa, expande, encontra `p5` e daí `p6`. Esse é o `hnsw.ef_search` inteiro, em vinte linhas.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-02"},{"cap":3,"tipo":"python","nivel":2,"tempo":10,"titulo":"O sorteio do nível","enunciado":"Escreva `nivel(u, m=16)` que devolve o nível máximo de um ponto novo a partir de um número `u` sorteado em (0, 1]: `floor(-ln(u) / ln(m))`. É o que produz as camadas do HNSW — cada camada com cerca de 1/m dos pontos da anterior.","esqueleto":"import math\n\ndef nivel(u, m=16):\n    ...\n","testes":[{"nome":"a maioria fica na camada 0","codigo":"assert nivel(0.99) == 0 and nivel(0.5) == 0"},{"nome":"um em dezesseis sobe","codigo":"assert nivel(0.05) == 1"},{"nome":"mais raro, mais alto","codigo":"assert nivel(0.001) == 2 and nivel(0.0001) == 3"},{"nome":"m menor sobe mais fácil","codigo":"assert nivel(0.05, 2) == 4"}],"solucao":"```python\nimport math\n\ndef nivel(u, m=16):\n    return int(-math.log(u) / math.log(m))\n```\nA distribuição é geométrica: com `m = 16`, cerca de 1 ponto em 16 chega à camada 1, 1 em 256 à camada 2, e assim por diante. É isso que faz o número de camadas crescer com o logaritmo de N.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-03"},{"cap":3,"tipo":"calculo","nivel":2,"tempo":8,"titulo":"Quantas camadas, quantos pontos","enunciado":"Um HNSW com `m = 16` sobre 1 milhão de pontos.","campos":[{"label":"pontos esperados na camada 1","valor":62500,"rel":0.02},{"label":"pontos esperados na camada 2","valor":3906,"rel":0.02},{"label":"número aproximado de camadas (log na base 16 de 1 milhão)","valor":4.98,"tol":0.05},{"label":"pontos esperados na camada 4","valor":15.3,"rel":0.05}],"solucao":"Cada camada tem cerca de 1/16 da anterior: 10⁶/16 = 62.500 na camada 1, 3.906 na 2, 244 na 3, 15 na 4. O número de camadas é log₁₆(10⁶) ≈ 4,98, ou seja 5 ou 6 no total. A descida pelo topo custa pouquíssimas distâncias; o trabalho está na camada 0, controlado pelo `ef_search`.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-04"},{"cap":3,"tipo":"js","nivel":2,"tempo":10,"titulo":"A descida gulosa em JavaScript","enunciado":"Escreva `gulosa(grafo, pontos, entrada, q)` que devolve `{no, visitados}`: o ponto onde a descida gulosa para e quantas distâncias foram calculadas (o ponto de entrada mais cada vizinho examinado). Distância euclidiana.","esqueleto":"function gulosa(grafo, pontos, entrada, q) {\n  // ...\n}\n","exports":["gulosa"],"testes":[{"nome":"caminha pela cadeia","codigo":"(() => { const P = {a: [0, 0], b: [1, 0], c: [2, 0], d: [3, 0]}; const G = {a: [\"b\"], b: [\"a\", \"c\"], c: [\"b\", \"d\"], d: [\"c\"]};\n  const r = gulosa(G, P, \"a\", [3, 0]); return r.no === \"d\" && r.visitados === 7; })()"},{"nome":"para no mínimo local","codigo":"(() => { const P = {a: [0, 0], b: [1, 0], c: [0.5, 0.5], d: [3, 0]}; const G = {a: [\"b\"], b: [\"a\", \"c\"], c: [\"b\", \"d\"], d: [\"c\"]};\n  return gulosa(G, P, \"a\", [4, 0]).no === \"b\"; })()"},{"nome":"já no melhor","codigo":"gulosa({a: [\"b\"], b: [\"a\"]}, {a: [0, 0], b: [5, 0]}, \"b\", [5, 0]).no === \"b\""}],"solucao":"```js\nfunction gulosa(grafo, pontos, entrada, q) {\n  const d = (p) => Math.hypot(...pontos[p].map((x, i) => x - q[i]));\n  let atual = entrada, dAtual = d(entrada), visitados = 1;\n  for (;;) {\n    let melhor = null, dMelhor = dAtual;\n    for (const v of grafo[atual]) { visitados++; const dv = d(v); if (dv < dMelhor) { melhor = v; dMelhor = dv; } }\n    if (melhor === null) return { no: atual, visitados };\n    atual = melhor; dAtual = dMelhor;\n  }\n}\n```","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-05"},{"cap":3,"tipo":"python","nivel":3,"tempo":15,"titulo":"A heurística de vizinhos","enunciado":"Ao ligar um ponto novo, o HNSW não escolhe simplesmente os `m` mais próximos: prefere vizinhos em **direções diferentes**. Escreva `selecionar_vizinhos(novo, candidatos, m)` que percorre os candidatos do mais próximo de `novo` para o mais distante e aceita um candidato só se ele estiver mais perto de `novo` do que de **qualquer** vizinho já aceito. `PONTOS` e `dist` estão definidos; `candidatos` é uma lista de ids.","esqueleto":"import math\n\nPONTOS = {\"p1\": [0.0, 0.0], \"p2\": [1.0, 0.0], \"p3\": [0.0, 1.0], \"p4\": [0.5, 0.5], \"p5\": [3.0, 0.0], \"p6\": [3.5, 0.5]}\nGRAFO = {\"p1\": [\"p2\", \"p3\"], \"p2\": [\"p1\", \"p4\"], \"p3\": [\"p1\", \"p4\"], \"p4\": [\"p2\", \"p3\", \"p5\"], \"p5\": [\"p4\", \"p6\"], \"p6\": [\"p5\"]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n\ndef selecionar_vizinhos(novo, candidatos, m):\n    ...\n","setup":"import math\n\nPONTOS = {\"p1\": [0.0, 0.0], \"p2\": [1.0, 0.0], \"p3\": [0.0, 1.0], \"p4\": [0.5, 0.5], \"p5\": [3.0, 0.0], \"p6\": [3.5, 0.5]}\nGRAFO = {\"p1\": [\"p2\", \"p3\"], \"p2\": [\"p1\", \"p4\"], \"p3\": [\"p1\", \"p4\"], \"p4\": [\"p2\", \"p3\", \"p5\"], \"p5\": [\"p4\", \"p6\"], \"p6\": [\"p5\"]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\nPONTOS[\"q1\"] = [1.0, 1.0]\nPONTOS[\"e1\"] = [1.0, 1.2]\nPONTOS[\"e2\"] = [1.0, 1.3]\nPONTOS[\"e3\"] = [1.0, 1.4]\nPONTOS[\"o1\"] = [1.0, 0.5]\n","testes":[{"nome":"descarta os empilhados","codigo":"assert selecionar_vizinhos(\"q1\", [\"e1\", \"e2\", \"e3\", \"o1\"], 3) == [\"e1\", \"o1\"]"},{"nome":"respeita o máximo","codigo":"assert len(selecionar_vizinhos(\"q1\", [\"e1\", \"o1\", \"e2\", \"e3\"], 1)) == 1"},{"nome":"sem candidatos","codigo":"assert selecionar_vizinhos(\"q1\", [], 3) == []"},{"nome":"o mais próximo sempre entra","codigo":"assert selecionar_vizinhos(\"q1\", [\"e3\", \"e2\", \"e1\"], 3) == [\"e1\"]"}],"solucao":"```python\ndef selecionar_vizinhos(novo, candidatos, m):\n    ordenados = sorted(candidatos, key=lambda c: dist(PONTOS[novo], PONTOS[c]))\n    aceitos = []\n    for c in ordenados:\n        if len(aceitos) >= m:\n            break\n        d_novo = dist(PONTOS[novo], PONTOS[c])\n        if all(d_novo < dist(PONTOS[c], PONTOS[a]) for a in aceitos):\n            aceitos.append(c)\n    return aceitos\n```\nOs pontos `e1`, `e2` e `e3` estão empilhados na mesma direção: aceito `e1`, os outros dois estão mais perto dele do que de `q1` e são descartados. Sobra espaço para `o1`, que aponta para outro lado. É essa heurística que mantém o grafo navegável dentro de aglomerados.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-06"},{"cap":3,"tipo":"python","nivel":2,"tempo":10,"titulo":"A poda das ligações","enunciado":"Quando um vizinho recebe uma ligação de volta e ultrapassa o máximo, ele poda. Escreva `podar(no, ligacoes, maximo)` que devolve as `maximo` ligações mais próximas de `no` (empate pelo id), descartando o resto.","esqueleto":"import math\n\nPONTOS = {\"p1\": [0.0, 0.0], \"p2\": [1.0, 0.0], \"p3\": [0.0, 1.0], \"p4\": [0.5, 0.5], \"p5\": [3.0, 0.0], \"p6\": [3.5, 0.5]}\nGRAFO = {\"p1\": [\"p2\", \"p3\"], \"p2\": [\"p1\", \"p4\"], \"p3\": [\"p1\", \"p4\"], \"p4\": [\"p2\", \"p3\", \"p5\"], \"p5\": [\"p4\", \"p6\"], \"p6\": [\"p5\"]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n\ndef podar(no, ligacoes, maximo):\n    ...\n","setup":"import math\n\nPONTOS = {\"p1\": [0.0, 0.0], \"p2\": [1.0, 0.0], \"p3\": [0.0, 1.0], \"p4\": [0.5, 0.5], \"p5\": [3.0, 0.0], \"p6\": [3.5, 0.5]}\nGRAFO = {\"p1\": [\"p2\", \"p3\"], \"p2\": [\"p1\", \"p4\"], \"p3\": [\"p1\", \"p4\"], \"p4\": [\"p2\", \"p3\", \"p5\"], \"p5\": [\"p4\", \"p6\"], \"p6\": [\"p5\"]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n","testes":[{"nome":"poda as mais distantes","codigo":"assert podar(\"p1\", [\"p2\", \"p5\", \"p4\", \"p6\"], 2) == [\"p4\", \"p2\"]"},{"nome":"não poda se couber","codigo":"assert podar(\"p1\", [\"p2\", \"p4\"], 4) == [\"p4\", \"p2\"]"},{"nome":"empate pelo id","codigo":"assert podar(\"p1\", [\"p3\", \"p2\"], 1) == [\"p2\"]"}],"solucao":"```python\ndef podar(no, ligacoes, maximo):\n    return sorted(ligacoes, key=lambda v: (dist(PONTOS[no], PONTOS[v]), v))[:maximo]\n```\nNo pgvector o máximo é `2·m` na camada 0 e `m` nas demais. A poda é o que impede o grafo de crescer sem limite conforme os pontos vão sendo inseridos.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-07"},{"cap":3,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"Distâncias: grafo contra força bruta","enunciado":"Um HNSW sobre 110 pontos, `m = 5`, encontrou o vizinho exato calculando 38 distâncias. A força bruta calcularia todas.","campos":[{"label":"distâncias da força bruta","valor":110,"tol":0.5},{"label":"fração da base examinada pelo índice","valor":0.345,"tol":0.005},{"label":"distâncias da força bruta se a base fosse 100× maior","valor":11000,"tol":1}],"solucao":"Força bruta: 110 distâncias, e 11.000 com 100× a base. O índice examinou 38, ou 34,5% — pouco impressionante nesta escala, e é justamente o ponto: em 110 pontos o índice quase não compensa. Com 1 milhão, a força bruta faz 1 milhão de distâncias e o HNSW continua na casa das centenas.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-08"},{"cap":3,"tipo":"dados","nivel":1,"tempo":5,"titulo":"Quem sobe até onde","enunciado":"Cinco pontos sortearam os números `u` a seguir na inserção, com `m = 16`. Escreva, uma linha por ponto, o nível máximo de cada um, no formato `ponto: nivel`. a: 0,80 · b: 0,04 · c: 0,50 · d: 0,0005 · e: 0,20","modo":"conjunto","esperado":"a: 0\nb: 1\nc: 0\nd: 2\ne: 0","solucao":"`floor(-ln(u)/ln(16))`: a → 0,08 → 0; b → 1,16 → 1; c → 0,25 → 0; d → 2,74 → 2; e → 0,58 → 0. Três dos cinco ficam só na camada 0, um sobe à 1 e um à 2 — a distribuição geométrica que dá ao grafo a forma de pirâmide.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-09"},{"cap":3,"tipo":"texto","nivel":2,"tempo":8,"titulo":"HNSW para quem conhece \"seis graus de separação\"","enunciado":"Explique a busca no HNSW em até 6 linhas, usando a analogia das redes sociais: camadas, ponto de entrada, descida, lista de candidatos.","rubrica":["Ligações curtas ligam cada ponto aos seus vizinhos próximos; ligações longas encurtam o caminho (o \"seis graus\")","As camadas organizam as ligações longas: a camada 0 tem todos os pontos, cada camada acima tem ~1/m dos pontos da anterior","A busca começa no topo, no ponto de entrada, e em cada camada anda de vizinho em vizinho na direção da consulta até nenhum melhorar","Ao parar, desce uma camada a partir dali, com ligações mais curtas e precisas","Na camada 0 guarda uma lista dos ef_search melhores em vez de só o melhor, e os k primeiros são a resposta"],"solucao":"Imagine que cada pessoa conhece os vizinhos de rua (ligações curtas) e que algumas conhecem gente em outra cidade (ligações longas). Para chegar a alguém do outro lado do país, você usa primeiro os contatos distantes, que cobrem muito terreno, e só no fim os vizinhos de rua, que dão a precisão. O HNSW organiza isso em camadas: no topo, poucos pontos e ligações longuíssimas; embaixo, todos os pontos e ligações curtas. A busca entra no topo, anda sempre para o vizinho mais próximo da consulta até nenhum melhorar, desce uma camada e repete. Na camada 0 ela não guarda só o melhor: mantém uma lista dos `ef_search` melhores candidatos, para não parar num beco sem saída.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-10"},{"cap":3,"tipo":"texto","nivel":1,"tempo":5,"titulo":"Por que o guloso puro erra","enunciado":"Em 3 linhas: o que é um mínimo local na busca do HNSW e como a lista de candidatos resolve.","rubrica":["Mínimo local: um ponto cujos vizinhos imediatos estão todos mais longe da consulta, embora exista ponto melhor duas ou mais ligações adiante","O guloso (ef = 1) só avança se um vizinho for estritamente melhor, então para ali","A lista de candidatos (ef > 1) guarda caminhos alternativos para explorar antes de desistir: quanto maior, menos mínimos locais enganam"],"solucao":"Um mínimo local é um ponto que parece o melhor da vizinhança: nenhum vizinho imediato está mais perto da consulta, mas duas ligações adiante existe alguém muito melhor. Com `ef = 1` a busca só anda para quem melhora agora, então trava ali. A lista de candidatos guarda os pontos \"quase bons\" que ela viu no caminho e volta a expandi-los antes de desistir — `ef` é literalmente a tolerância a mínimos locais, e 1 não tolera nenhum.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-11"},{"cap":3,"tipo":"texto","nivel":2,"tempo":6,"titulo":"O grafo não é determinístico","enunciado":"Em 3 linhas: por que dois índices HNSW construídos sobre os mesmos dados podem ter recalls diferentes, e o que isso implica para a sua medição.","rubrica":["A busca é determinística dado um grafo, mas a construção sorteia o nível de cada ponto","Grafos diferentes → caminhos diferentes → recall ligeiramente diferente","Implicação: meça o recall do índice que você construiu, não confie num número de referência de outro lugar"],"solucao":"A busca, dado um grafo, é determinística. A construção não: cada ponto sorteia o nível máximo, então a mesma tabela indexada duas vezes gera pirâmides diferentes, com caminhos e recalls ligeiramente diferentes. A consequência prática é direta: recall de índice é medida do **seu** índice, construído com os seus dados e os seus parâmetros. Um número lido em benchmark de outra pessoa não substitui a medição do capítulo 8.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-12"},{"cap":3,"tipo":"texto","nivel":2,"tempo":6,"titulo":"Remover é a operação difícil","enunciado":"Em 3 linhas: por que remover um ponto de um HNSW é caro, o que o pgvector faz, e por que isso quase não incomoda neste projeto.","rubrica":["Remover pode quebrar caminhos do grafo (o ponto podia ser a ponte entre duas regiões)","O pgvector marca a linha como morta, o VACUUM limpa depois, e com muita rotatividade o grafo degrada e pede REINDEX","No projeto a base muda por versão: inserções quando entra norma nova, reindexação completa quando muda o modelo; remoções são raras"],"solucao":"Cada ponto do grafo pode ser a única ponte entre duas regiões; tirá-lo pode deixar vizinhos inalcançáveis, e refazer as ligações direito custa quase tanto quanto inserir. Por isso o pgvector não remove: marca a linha como morta, deixa o `VACUUM` recolher e, com muita rotatividade, o grafo degrada até um `REINDEX`. No projeto a base normativa é acrescida (norma nova) ou reconstruída inteira (troca de modelo), e \"atualizar o vetor de uma linha\" nem existe como operação — seria uma remoção mais uma inserção.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-13"},{"cap":3,"tipo":"python","nivel":3,"tempo":12,"titulo":"Quantas ligações o grafo guarda","enunciado":"Escreva `ligacoes_totais(n, m=16)` que estima o número de ligações de um HNSW com `n` pontos: a camada 0 dá `2*m` ligações por ponto; cada camada acima tem `n / m**nivel` pontos com `m` ligações cada, enquanto esse número for pelo menos 1. Devolva o total arredondado para o inteiro mais próximo.","esqueleto":"def ligacoes_totais(n, m=16):\n    ...\n","testes":[{"nome":"base pequena","codigo":"assert ligacoes_totais(16) == 528"},{"nome":"duas camadas acima","codigo":"assert ligacoes_totais(256) == 8464"},{"nome":"um milhão","codigo":"assert ligacoes_totais(1_000_000) == 33_066_650"},{"nome":"m maior, mais ligações embaixo","codigo":"assert ligacoes_totais(16, 32) == 1024"}],"solucao":"```python\ndef ligacoes_totais(n, m=16):\n    total = n * 2 * m\n    nivel = 1\n    while n / m ** nivel >= 1:\n        total += (n / m ** nivel) * m\n        nivel += 1\n    return round(total)\n```\nA camada 0 domina: das 33 milhões de ligações de 1 milhão de pontos, 32 milhões estão nela. É por isso que subir `m` engorda o índice quase proporcionalmente — e é a base da calculadora de memória do capítulo 8.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-14"},{"cap":3,"tipo":"projeto","nivel":2,"tempo":25,"titulo":"O experimento do grafo, com anotação","enunciado":"No experimento \"A busca no grafo, passo a passo\" (capítulo 3), coloque a consulta entre dois aglomerados com `ef_search = 1` e `k = 3` e vá ao fim: anote quantos vizinhos exatos foram perdidos e quantas distâncias foram calculadas. Repita no mesmo lugar com `ef_search = 6`, depois com `m = 2` e `m = 8`.","entrega":"Tabela (m, ef_search) × (vizinhos perdidos, distâncias calculadas) com pelo menos quatro combinações, e a combinação que deu recall 100% com menos distâncias.","rubrica":["Usei a mesma posição de consulta em todas as combinações (senão não dá para comparar)","Anotei vizinhos perdidos e distâncias calculadas em cada combinação","Observei que ef = 1 perde vizinhos com frequência, e que subir ef corrige com custo","Observei o efeito de m: com m = 2 o grafo fica mal conectado e nenhum ef salva por completo"],"solucao":"O padrão que aparece: com `ef = 1` a busca costuma perder um dos três vizinhos exatos quando a consulta está entre aglomerados; `ef = 6` normalmente recupera todos, calculando algumas dezenas de distâncias a mais (ainda muito abaixo das 110 da força bruta). Com `m = 2` o grafo tem poucas ligações e regiões mal conectadas: subir o `ef` ajuda mas não conserta, porque o caminho simplesmente não existe. Com `m = 8` o recall fica alto já com `ef` baixo, ao custo de mais ligações por ponto. É o capítulo 4 antecipado: a construção define o teto, o `ef_search` escolhe o ponto abaixo dele.","ligacoes":["03-busca-vetorial.html#c3"],"id":"p3-c3-15"},{"cap":4,"tipo":"dados","nivel":1,"tempo":6,"titulo":"Fixo na criação ou ajustável na sessão","enunciado":"Para cada um dos três parâmetros do HNSW no pgvector, escreva uma linha no formato `parametro: padrao quando`, onde `quando` é `criacao` (fixado no `CREATE INDEX`, mudar exige reconstruir) ou `sessao` (ajustável por consulta). Os parâmetros são `m`, `ef_construction` e `hnsw.ef_search`.","modo":"conjunto","esperado":"m: 16 criacao\nef_construction: 64 criacao\nhnsw.ef_search: 40 sessao","solucao":"`m` = 16 e `ef_construction` = 64 são fixados no `CREATE INDEX`: mudar qualquer um exige reconstruir o índice. `hnsw.ef_search` = 40 é um parâmetro de sessão (`SET`, `SET LOCAL`, `ALTER DATABASE`), e é o único botão de ajuste fino em produção.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-01"},{"cap":4,"tipo":"python","nivel":2,"tempo":12,"titulo":"O verificador de parâmetros","enunciado":"Escreva `avisos(m, ef_construction, ef_search, limit)` que devolve a lista ordenada de problemas: `\"ef_search < limit\"` se o `ef_search` for menor que o `LIMIT` (o índice não devolve mais linhas do que `ef_search`); `\"m baixo\"` se `m < 8`; `\"ef_construction baixo\"` se for menor que `m`; `\"ef_search alto\"` se passar de 1000. Lista vazia significa configuração sadia.","esqueleto":"def avisos(m, ef_construction, ef_search, limit):\n    ...\n","testes":[{"nome":"padrões com LIMIT 12","codigo":"assert avisos(16, 64, 40, 12) == []"},{"nome":"o erro clássico","codigo":"assert avisos(16, 64, 40, 50) == [\"ef_search < limit\"]"},{"nome":"grafo mal construído","codigo":"assert avisos(4, 2, 40, 12) == [\"ef_construction baixo\", \"m baixo\"]"},{"nome":"exagero","codigo":"assert avisos(16, 64, 2000, 12) == [\"ef_search alto\"]"}],"solucao":"```python\ndef avisos(m, ef_construction, ef_search, limit):\n    fora = []\n    if ef_search < limit:\n        fora.append(\"ef_search < limit\")\n    if m < 8:\n        fora.append(\"m baixo\")\n    if ef_construction < m:\n        fora.append(\"ef_construction baixo\")\n    if ef_search > 1000:\n        fora.append(\"ef_search alto\")\n    return sorted(fora)\n```\nO primeiro aviso é o que mais aparece em produção: com `ef_search = 40` e `LIMIT 50` a consulta devolve no máximo 40 linhas, sem erro nenhum.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-02"},{"cap":4,"tipo":"sql","nivel":1,"tempo":8,"titulo":"O CREATE INDEX do projeto","enunciado":"Escreva o `CREATE INDEX` chamado `trecho_emb_hnsw` sobre `rag.trecho_normativo`, coluna `embedding`, usando HNSW com a classe de operador de cosseno e os parâmetros do projeto (`m = 16`, `ef_construction = 64`).","esqueleto":"CREATE INDEX ...\n","checks":[{"re":"CREATE INDEX\\s+trecho_emb_hnsw","msg":"nome do índice"},{"re":"ON\\s+rag\\.trecho_normativo","msg":"tabela do projeto"},{"re":"USING\\s+hnsw","msg":"método hnsw"},{"re":"embedding\\s+vector_cosine_ops","msg":"coluna e classe de operador de cosseno"},{"re":"WITH\\s*\\([^)]*m\\s*=\\s*16","msg":"m = 16"},{"re":"ef_construction\\s*=\\s*64","msg":"ef_construction = 64"}],"solucao":"```sql\nCREATE INDEX trecho_emb_hnsw ON rag.trecho_normativo\n  USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);\n```\nA classe de operador precisa combinar com o operador da consulta: `vector_cosine_ops` para `<=>`. Indexar em cosseno e consultar com `<->` faz o índice ser ignorado em silêncio.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-03"},{"cap":4,"tipo":"sql","nivel":2,"tempo":8,"titulo":"A transação de busca","enunciado":"Escreva o bloco que o ia-worker executa a cada busca: abre a transação, define `hnsw.ef_search = 100` e `hnsw.iterative_scan = relaxed_order` **só para a transação**, e fecha. Use `SET LOCAL`.","esqueleto":"BEGIN;\n...\nCOMMIT;\n","checks":[{"re":"BEGIN\\s*;","msg":"abre a transação"},{"re":"SET LOCAL\\s+hnsw\\.ef_search\\s*=\\s*100","msg":"SET LOCAL do ef_search em 100"},{"re":"SET LOCAL\\s+hnsw\\.iterative_scan\\s*=\\s*relaxed_order","msg":"SET LOCAL do iterative_scan"},{"re":"COMMIT\\s*;","msg":"fecha a transação"}],"solucao":"```sql\nBEGIN;\nSET LOCAL hnsw.ef_search = 100;\nSET LOCAL hnsw.iterative_scan = relaxed_order;\n-- a consulta vetorial vem aqui\nCOMMIT;\n```\n`SET LOCAL` vale só para a transação, o que evita que uma conexão do pool carregue a configuração de uma busca para outra. E, estando no código, a configuração entra no controle de versão junto com a consulta.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-04"},{"cap":4,"tipo":"calculo","nivel":1,"tempo":5,"titulo":"ef_search precisa acompanhar o LIMIT","enunciado":"A busca híbrida do projeto pede 50 candidatos vetoriais. Os padrões do pgvector são `ef_search = 40`.","campos":[{"label":"linhas que o índice devolve no máximo com ef_search = 40 e LIMIT 50","valor":40,"tol":0.5},{"label":"candidatos vetoriais que faltariam para a fusão","valor":10,"tol":0.5},{"label":"ef_search mínimo para atender o LIMIT","valor":50,"tol":0.5}],"solucao":"O índice nunca devolve mais linhas do que o tamanho da lista de candidatos: com `ef_search = 40`, o `LIMIT 50` vira 40, faltando 10 candidatos para a fusão RRF. O mínimo útil é 50, e o projeto usa 100 para ter folga e recall melhor.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-05"},{"cap":4,"tipo":"python","nivel":1,"tempo":8,"titulo":"O ef_search mínimo","enunciado":"Escreva `ef_minimo(limit, folga=2.0)` que devolve o menor múltiplo de 10 maior ou igual a `limit * folga`, com piso em 40 (o padrão do pgvector). É a regra prática do capítulo: `ef_search` sempre acima do `LIMIT`, com alguma folga.","esqueleto":"import math\n\ndef ef_minimo(limit, folga=2.0):\n    ...\n","testes":[{"nome":"o caso do projeto","codigo":"assert ef_minimo(50) == 100"},{"nome":"limites pequenos ficam no piso","codigo":"assert ef_minimo(12) == 40 and ef_minimo(5) == 40"},{"nome":"sem folga","codigo":"assert ef_minimo(50, 1.0) == 50"},{"nome":"arredonda para cima","codigo":"assert ef_minimo(33, 1.0) == 40 and ef_minimo(41, 1.0) == 50"}],"solucao":"```python\nimport math\n\ndef ef_minimo(limit, folga=2.0):\n    return max(40, int(math.ceil(limit * folga / 10) * 10))\n```\nCom `LIMIT 50` e folga 2, dá exatamente os 100 que o projeto usa. O piso de 40 evita \"otimizar\" para baixo do padrão sem medir.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-06"},{"cap":4,"tipo":"python","nivel":3,"tempo":12,"titulo":"Ler a tabela do experimento","enunciado":"Escreva `recomendar(medicoes, alvo=0.95)` que recebe as linhas do experimento (`{\"m\", \"ef_c\", \"ef_s\", \"recall\", \"distancias\"}`) e devolve a que atinge o `alvo` com **menos distâncias**; entre empates em distâncias, a de maior recall. Devolve `None` se nenhuma atingir.","esqueleto":"def recomendar(medicoes, alvo=0.95):\n    ...\n","testes":[{"nome":"a mais barata que atinge","codigo":"M = [{\"m\": 16, \"ef_c\": 64, \"ef_s\": 40, \"recall\": 0.95, \"distancias\": 660},\n     {\"m\": 16, \"ef_c\": 64, \"ef_s\": 160, \"recall\": 0.97, \"distancias\": 2580},\n     {\"m\": 32, \"ef_c\": 64, \"ef_s\": 40, \"recall\": 0.96, \"distancias\": 900}]\nassert recomendar(M)[\"ef_s\"] == 40 and recomendar(M)[\"m\"] == 16"},{"nome":"nenhuma atinge","codigo":"M = [{\"m\": 4, \"ef_c\": 64, \"ef_s\": 40, \"recall\": 0.7, \"distancias\": 300}]\nassert recomendar(M, 0.95) is None"},{"nome":"empate em distâncias","codigo":"M = [{\"m\": 16, \"ef_c\": 64, \"ef_s\": 40, \"recall\": 0.95, \"distancias\": 660},\n     {\"m\": 16, \"ef_c\": 200, \"ef_s\": 40, \"recall\": 0.98, \"distancias\": 660}]\nassert recomendar(M)[\"ef_c\"] == 200"}],"solucao":"```python\ndef recomendar(medicoes, alvo=0.95):\n    validas = [m for m in medicoes if m[\"recall\"] >= alvo]\n    if not validas:\n        return None\n    return min(validas, key=lambda m: (m[\"distancias\"], -m[\"recall\"]))\n```\nO terceiro teste é o capítulo em uma linha: subir `ef_construction` melhorou o recall **sem custo de consulta**, porque ele só afeta a construção.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-07"},{"cap":4,"tipo":"js","nivel":1,"tempo":8,"titulo":"O verificador em JavaScript","enunciado":"Escreva `checarParametros({m, efConstruction, efSearch, limit})` que devolve um array de avisos: `\"ef_search < limit\"`, `\"m baixo\"` (m < 8) e `\"ef_construction baixo\"` (menor que m), em ordem alfabética.","esqueleto":"function checarParametros(cfg) {\n  // ...\n}\n","exports":["checarParametros"],"testes":[{"nome":"tudo certo","codigo":"iguais(checarParametros({m: 16, efConstruction: 64, efSearch: 100, limit: 50}), [])"},{"nome":"ef menor que limit","codigo":"iguais(checarParametros({m: 16, efConstruction: 64, efSearch: 40, limit: 50}), [\"ef_search < limit\"])"},{"nome":"dois avisos","codigo":"iguais(checarParametros({m: 4, efConstruction: 2, efSearch: 40, limit: 12}), [\"ef_construction baixo\", \"m baixo\"])"}],"solucao":"```js\nfunction checarParametros({ m, efConstruction, efSearch, limit }) {\n  const fora = [];\n  if (efSearch < limit) fora.push(\"ef_search < limit\");\n  if (m < 8) fora.push(\"m baixo\");\n  if (efConstruction < m) fora.push(\"ef_construction baixo\");\n  return fora.sort();\n}\n```","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-08"},{"cap":4,"tipo":"texto","nivel":2,"tempo":8,"titulo":"Se ef_search resolve, por que m importa?","enunciado":"Em até 5 linhas: por que subir o `ef_search` não compensa um `m` pequeno ou um `ef_construction` baixo.","rubrica":["ef_search só explora o grafo que já existe: ele não cria ligações","Com m pequeno o grafo tem regiões mal conectadas — não há caminho, e nenhum ef alcança sem virar varredura","ef_construction baixo faz cada ponto escolher vizinhos ruins: o índice \"nasce ruim\"","A regra: a construção define o teto de recall; o ef_search escolhe o ponto abaixo dele"],"solucao":"`ef_search` é a largura da exploração, não a qualidade do mapa. Com `m` pequeno o grafo tem poucas ligações e regiões que simplesmente não se alcançam a partir do ponto de entrada: aumentar a lista de candidatos faz a busca visitar mais, sem nunca chegar lá, até degenerar em varredura. Com `ef_construction` baixo cada ponto se liga aos vizinhos errados, e o grafo nasce impreciso. A construção define o teto de recall; o `ef_search` só escolhe onde você fica abaixo dele.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-09"},{"cap":4,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"O que cada parâmetro custa","enunciado":"Uma construção com `m = 16` e `ef_construction = 64` levou 4 minutos e gerou um índice de 500 MB.","campos":[{"label":"tempo aproximado com ef_construction = 200 (minutos)","valor":12.5,"tol":0.5},{"label":"tamanho aproximado do índice com ef_construction = 200 (MB)","valor":500,"tol":5},{"label":"tamanho aproximado com m = 32 e ef_construction = 64 (MB)","valor":1000,"tol":20}],"solucao":"`ef_construction` é aproximadamente proporcional ao tempo de construção (200/64 ≈ 3,1 → 12,5 min) e **não muda o tamanho** nem a velocidade de consulta: continua 500 MB. `m` é que engorda o índice, porque são ligações a mais por ponto: dobrar `m` aproximadamente dobra o espaço das ligações. Construção lenta é barata quando roda uma vez e a base fica meses.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-10"},{"cap":4,"tipo":"python","nivel":1,"tempo":8,"titulo":"Precisa reconstruir?","enunciado":"Escreva `precisa_reconstruir(antes, depois)` que recebe dois dicionários com `m`, `ef_construction` e `ef_search` e devolve `True` se a mudança exigir um novo `CREATE INDEX`. Só `ef_search` muda sem reconstruir.","esqueleto":"def precisa_reconstruir(antes, depois):\n    ...\n","testes":[{"nome":"só ef_search","codigo":"assert precisa_reconstruir({\"m\": 16, \"ef_construction\": 64, \"ef_search\": 40}, {\"m\": 16, \"ef_construction\": 64, \"ef_search\": 100}) is False"},{"nome":"mudou m","codigo":"assert precisa_reconstruir({\"m\": 16, \"ef_construction\": 64, \"ef_search\": 40}, {\"m\": 32, \"ef_construction\": 64, \"ef_search\": 40}) is True"},{"nome":"mudou ef_construction","codigo":"assert precisa_reconstruir({\"m\": 16, \"ef_construction\": 64, \"ef_search\": 40}, {\"m\": 16, \"ef_construction\": 200, \"ef_search\": 40}) is True"},{"nome":"nada mudou","codigo":"assert precisa_reconstruir({\"m\": 16, \"ef_construction\": 64, \"ef_search\": 40}, {\"m\": 16, \"ef_construction\": 64, \"ef_search\": 40}) is False"}],"solucao":"```python\ndef precisa_reconstruir(antes, depois):\n    return antes[\"m\"] != depois[\"m\"] or antes[\"ef_construction\"] != depois[\"ef_construction\"]\n```\nÉ a fronteira operacional do capítulo: um lado é `ALTER DATABASE … SET`, o outro é uma janela de manutenção com `CREATE INDEX CONCURRENTLY`.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-11"},{"cap":4,"tipo":"dados","nivel":2,"tempo":6,"titulo":"Que botão mexer","enunciado":"Para cada sintoma, escreva `sintoma: parametro` com o parâmetro que você mexeria primeiro (`ef_search`, `m` ou `ef_construction`). Sintomas: `recall 0,88 com ef_search 40` · `recall 0,89 mesmo com ef_search 400` · `recall bom mas latência alta` · `LIMIT 50 devolvendo 40 linhas`.","modo":"conjunto","esperado":"recall 0,88 com ef_search 40: ef_search\nrecall 0,89 mesmo com ef_search 400: m\nrecall bom mas latência alta: ef_search\nLIMIT 50 devolvendo 40 linhas: ef_search","solucao":"Recall baixo com `ef_search` baixo: suba o `ef_search`, é grátis e não toca no índice. Recall que não sobe nem com `ef_search` alto: o teto é da construção, e o suspeito é `m` (grafo mal conectado); `ef_construction` seria o segundo. Latência alta com recall bom: baixe o `ef_search`, você está pagando por décimos. Linhas a menos que o `LIMIT`: `ef_search` de novo — ele é o teto do número de linhas devolvidas.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-12"},{"cap":4,"tipo":"texto","nivel":1,"tempo":6,"titulo":"Os padrões servem?","enunciado":"Em 3 linhas: os padrões do pgvector (16 / 64 / 40) servem para este projeto? O que você mudaria e por quê.","rubrica":["Servem para começar: m = 16 e ef_construction = 64 são bons padrões para embeddings de texto","O ajuste que quase sempre vale é ef_search = 100, porque a busca híbrida pede 50 candidatos e 40 é menos que isso","m e ef_construction só mudam se o recall medido ficar abaixo do alvo mesmo com ef_search alto"],"solucao":"Servem para começar. `m = 16` e `ef_construction = 64` são padrões razoáveis para embeddings de texto, e não vale mexer neles sem medida. O que precisa mudar é o `ef_search`: 40 é menor que os 50 candidatos que a busca híbrida pede, então o projeto usa 100 na transação. Se, com `ef_search` alto, o recall medido continuar abaixo do alvo, aí sim entram `m` e `ef_construction` — com reconstrução.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-13"},{"cap":4,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"Ler a curva do experimento","enunciado":"Uma rodada do experimento: ef_search 10 → recall 0,72 / 180 distâncias; 40 → 0,95 / 660; 100 → 0,965 / 1620; 200 → 0,968 / 3220. A busca exata calcularia 3.000 distâncias.","campos":[{"label":"fração da base examinada com ef_search = 40","valor":0.22,"tol":0.005},{"label":"fração examinada com ef_search = 200","valor":1.07,"tol":0.01},{"label":"ganho de recall de 40 para 200","valor":0.018,"tol":0.001}],"solucao":"Com `ef_search = 40` o índice olha 22% da base para 0,95 de recall. Com 200 ele olha **mais** que a base inteira (3.220 contra 3.000 distâncias, porque revisita pontos) para ganhar 0,018 — a busca exata seria mais rápida e teria recall 1,0. É o sinal de que a base é pequena demais para esse `ef`, ou de que o índice não deveria existir ainda.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-14"},{"cap":4,"tipo":"projeto","nivel":2,"tempo":30,"titulo":"Os três movimentos do capítulo","enunciado":"No experimento \"Recall × custo nos seus parâmetros\", faça três séries com 3.000 vetores: (1) padrões 16/64/40 e depois só `ef_search` em 10, 20, 100 e 200; (2) volte a `ef_search` 40 e baixe `m` para 4; (3) `m = 16` com `ef_construction = 8`. Anote recall, distâncias e tempo de construção de cada rodada.","entrega":"Tabela com as rodadas e uma frase por série dizendo o que ela demonstrou.","rubrica":["Fiz a série de ef_search com m e ef_construction fixos, e vi a curva achatar","Com m = 4 o recall despencou e nenhum ef_search recuperou por completo","Com ef_construction = 8 o índice \"nasceu ruim\": recall baixo desde o começo","Concluí que a construção define o teto e o ef_search escolhe o ponto abaixo dele"],"solucao":"A série de `ef_search` desenha a curva com retorno decrescente: o salto grande está entre 10 e 40, e de 100 para 200 quase nada muda. Com `m = 4` o recall cai muito e sobe pouco com `ef_search`, porque faltam ligações — o grafo não tem os caminhos. Com `ef_construction = 8` cada ponto escolheu vizinhos ruins e o índice nasce com teto baixo, mesmo com `m = 16`. Três rodadas, três lições: `ef_search` move dentro do teto; `m` e `ef_construction` movem o teto.","ligacoes":["03-busca-vetorial.html#c4"],"id":"p3-c4-15"},{"cap":5,"tipo":"python","nivel":1,"tempo":10,"titulo":"As regras de bolso do IVFFlat","enunciado":"Escreva `lists_recomendado(n)` e `probes_recomendado(lists)` seguindo a documentação do pgvector: `lists = n / 1000` até 1 milhão de linhas, `lists = sqrt(n)` acima disso; `probes = sqrt(lists)`. Arredonde ambos para o inteiro mais próximo, com mínimo 1.","esqueleto":"import math\n\ndef lists_recomendado(n):\n    ...\n\ndef probes_recomendado(lists):\n    ...\n","testes":[{"nome":"base média","codigo":"assert lists_recomendado(30_000) == 30 and probes_recomendado(30) == 5"},{"nome":"no limite do milhão","codigo":"assert lists_recomendado(1_000_000) == 1000"},{"nome":"acima de um milhão vira raiz","codigo":"assert lists_recomendado(4_000_000) == 2000"},{"nome":"mínimo 1","codigo":"assert lists_recomendado(100) == 1 and probes_recomendado(1) == 1"}],"solucao":"```python\nimport math\n\ndef lists_recomendado(n):\n    bruto = n / 1000 if n <= 1_000_000 else math.sqrt(n)\n    return max(1, round(bruto))\n\ndef probes_recomendado(lists):\n    return max(1, round(math.sqrt(lists)))\n```\nRepare que as duas fórmulas se encontram em 1 milhão (10⁶/1000 = 1000 = √10⁶): a regra é contínua. E `probes ≈ √lists` existe justamente para compensar o erro de fronteira.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-01"},{"cap":5,"tipo":"python","nivel":2,"tempo":12,"titulo":"Em que lista cada ponto cai","enunciado":"Escreva `atribuir(pontos, centroides)` que devolve `{id: lista}` com o índice do centroide mais próximo de cada ponto (empate: menor índice) e `tamanhos(atribuicao)` que devolve `{lista: quantidade}` em ordem de índice. `dist(a, b)`, `PONTOS` e `CENTROIDES` já estão definidos.","esqueleto":"import math\n\nCENTROIDES = {0: [0.0, 0.0], 1: [10.0, 0.0], 2: [0.0, 10.0], 3: [10.0, 10.0]}\nPONTOS = {\"a\": [0.5, 0.5], \"b\": [1.0, 0.0], \"c\": [9.5, 0.5], \"d\": [10.0, 1.0],\n          \"e\": [0.0, 9.5], \"f\": [1.0, 10.0], \"g\": [9.5, 9.5], \"h\": [4.9, 0.0], \"i\": [5.1, 0.0]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n\ndef atribuir(pontos, centroides):\n    ...\n\ndef tamanhos(atribuicao):\n    ...\n","setup":"import math\n\nCENTROIDES = {0: [0.0, 0.0], 1: [10.0, 0.0], 2: [0.0, 10.0], 3: [10.0, 10.0]}\nPONTOS = {\"a\": [0.5, 0.5], \"b\": [1.0, 0.0], \"c\": [9.5, 0.5], \"d\": [10.0, 1.0],\n          \"e\": [0.0, 9.5], \"f\": [1.0, 10.0], \"g\": [9.5, 9.5], \"h\": [4.9, 0.0], \"i\": [5.1, 0.0]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n","testes":[{"nome":"atribuição","codigo":"A = atribuir(PONTOS, CENTROIDES)\nassert A[\"a\"] == 0 and A[\"c\"] == 1 and A[\"e\"] == 2 and A[\"g\"] == 3"},{"nome":"a fronteira","codigo":"A = atribuir(PONTOS, CENTROIDES)\nassert A[\"h\"] == 0 and A[\"i\"] == 1"},{"nome":"tamanhos","codigo":"assert tamanhos(atribuir(PONTOS, CENTROIDES)) == {0: 3, 1: 3, 2: 2, 3: 1}"},{"nome":"empate pelo menor índice","codigo":"assert atribuir({\"x\": [5.0, 0.0]}, CENTROIDES) == {\"x\": 0}"}],"solucao":"```python\ndef atribuir(pontos, centroides):\n    return {i: min(centroides, key=lambda c: (dist(v, centroides[c]), c)) for i, v in pontos.items()}\n\ndef tamanhos(atribuicao):\n    contagem = {}\n    for lista in atribuicao.values():\n        contagem[lista] = contagem.get(lista, 0) + 1\n    return dict(sorted(contagem.items()))\n```\nOs pontos `h` e `i` estão a 0,2 de distância um do outro e caem em listas diferentes: é o erro de fronteira nascendo.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-02"},{"cap":5,"tipo":"python","nivel":3,"tempo":15,"titulo":"O erro de fronteira, medido","enunciado":"Escreva `busca_ivf(q, pontos, centroides, atribuicao, k, probes)` que devolve `(ids, perdidos)`: os `k` ids mais próximos de `q` **considerando apenas** as `probes` listas cujos centroides estão mais perto de `q`, e quantos dos `k` vizinhos exatos ficaram de fora por estarem em listas não sondadas. Empates de distância pelo id.","esqueleto":"import math\n\nCENTROIDES = {0: [0.0, 0.0], 1: [10.0, 0.0], 2: [0.0, 10.0], 3: [10.0, 10.0]}\nPONTOS = {\"a\": [0.5, 0.5], \"b\": [1.0, 0.0], \"c\": [9.5, 0.5], \"d\": [10.0, 1.0],\n          \"e\": [0.0, 9.5], \"f\": [1.0, 10.0], \"g\": [9.5, 9.5], \"h\": [4.9, 0.0], \"i\": [5.1, 0.0]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n\ndef busca_ivf(q, pontos, centroides, atribuicao, k, probes):\n    ...\n","setup":"import math\n\nCENTROIDES = {0: [0.0, 0.0], 1: [10.0, 0.0], 2: [0.0, 10.0], 3: [10.0, 10.0]}\nPONTOS = {\"a\": [0.5, 0.5], \"b\": [1.0, 0.0], \"c\": [9.5, 0.5], \"d\": [10.0, 1.0],\n          \"e\": [0.0, 9.5], \"f\": [1.0, 10.0], \"g\": [9.5, 9.5], \"h\": [4.9, 0.0], \"i\": [5.1, 0.0]}\n\ndef dist(a, b):\n    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))\n\nATRIB = {i: min(CENTROIDES, key=lambda c: (dist(v, CENTROIDES[c]), c)) for i, v in PONTOS.items()}\n","testes":[{"nome":"uma lista perde o vizinho do outro lado","codigo":"r = busca_ivf([5.0, 0.0], PONTOS, CENTROIDES, ATRIB, 2, 1)\nassert r[1] == 1 and len(r[0]) == 2"},{"nome":"duas listas recuperam","codigo":"r = busca_ivf([5.0, 0.0], PONTOS, CENTROIDES, ATRIB, 2, 2)\nassert r == ([\"h\", \"i\"], 0)"},{"nome":"sondar tudo é exato","codigo":"r = busca_ivf([0.4, 0.4], PONTOS, CENTROIDES, ATRIB, 3, 4)\nassert r[1] == 0"},{"nome":"longe da fronteira não perde","codigo":"r = busca_ivf([0.4, 0.4], PONTOS, CENTROIDES, ATRIB, 2, 1)\nassert r[1] == 0"}],"solucao":"```python\ndef busca_ivf(q, pontos, centroides, atribuicao, k, probes):\n    ordem_listas = sorted(centroides, key=lambda c: (dist(q, centroides[c]), c))[:probes]\n    sondadas = set(ordem_listas)\n    candidatos = [i for i in pontos if atribuicao[i] in sondadas]\n    por_dist = lambda i: (dist(q, pontos[i]), i)\n    ids = sorted(candidatos, key=por_dist)[:k]\n    exatos = sorted(pontos, key=por_dist)[:k]\n    return (ids, len(set(exatos) - set(ids)))\n```\nA consulta em `[5, 0]` cai exatamente na fronteira entre as listas 0 e 1: com `probes = 1` um dos dois vizinhos gêmeos fica invisível. Com `probes = 2`, os dois voltam.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-03"},{"cap":5,"tipo":"calculo","nivel":1,"tempo":6,"titulo":"Listas e sondagens para cada base","enunciado":"Aplique as regras de bolso do pgvector.","campos":[{"label":"lists para 30 mil linhas","valor":30,"tol":0.5},{"label":"probes para essas listas (√lists, arredondado)","valor":5,"tol":0.5},{"label":"lists para 4 milhões de linhas","valor":2000,"tol":1},{"label":"linhas por lista, em média, com 4 milhões e 2.000 listas","valor":2000,"tol":1}],"solucao":"30 mil / 1000 = 30 listas, √30 ≈ 5 sondagens. Acima de 1 milhão a regra vira √n: √4.000.000 = 2.000 listas, com 2.000 linhas em cada. Sondando 45 delas (√2000), a busca examina cerca de 90 mil linhas em vez de 4 milhões.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-04"},{"cap":5,"tipo":"sql","nivel":2,"tempo":8,"titulo":"CREATE INDEX do IVFFlat","enunciado":"Escreva o `CREATE INDEX` chamado `trecho_emb_ivf` sobre `rag.trecho_normativo (embedding)` usando `ivfflat` com a classe de cosseno e `lists = 30`, seguido do `SET LOCAL ivfflat.probes = 5` que a consulta usaria.","esqueleto":"CREATE INDEX ...\n","checks":[{"re":"CREATE INDEX\\s+trecho_emb_ivf","msg":"nome do índice"},{"re":"USING\\s+ivfflat","msg":"método ivfflat"},{"re":"embedding\\s+vector_cosine_ops","msg":"coluna e classe de cosseno"},{"re":"WITH\\s*\\([^)]*lists\\s*=\\s*30","msg":"lists = 30"},{"re":"SET LOCAL\\s+ivfflat\\.probes\\s*=\\s*5","msg":"SET LOCAL do probes"}],"solucao":"```sql\nCREATE INDEX trecho_emb_ivf ON rag.trecho_normativo\n  USING ivfflat (embedding vector_cosine_ops) WITH (lists = 30);\n\nSET LOCAL ivfflat.probes = 5;\n```\nDiferente do HNSW, este índice **precisa** ser criado depois de os dados estarem na tabela: os centroides saem de um k-means sobre as linhas existentes.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-05"},{"cap":5,"tipo":"texto","nivel":2,"tempo":8,"titulo":"O erro de fronteira é estrutural","enunciado":"Em até 5 linhas: o que é o erro de fronteira do IVFFlat, por que ele não some com um parâmetro de busca como o `ef_search` do HNSW, e o que o atenua.","rubrica":["A base é particionada por k-means; a consulta sonda só as `probes` listas de centroides mais próximos","Se a consulta cai perto da fronteira entre listas, vizinhos verdadeiros ficam do outro lado e são invisíveis","Não existe ef_search no IVFFlat: o que se ajusta é probes, e a fronteira continua existindo, só mais longe","Atenua-se com probes ≈ √lists; com probes = lists a busca vira exata (e lenta)"],"solucao":"O IVFFlat divide a base em `lists` grupos por k-means e, na consulta, só olha dentro das `probes` listas cujos centroides estão mais perto. Um vizinho verdadeiro que tenha caído na lista vizinha simplesmente não é examinado — não há caminho até ele, como haveria num grafo. Por isso não existe um `ef_search` que resolva: o botão é `probes`, e ele empurra a fronteira para mais longe sem eliminá-la. A regra `probes ≈ √lists` é o meio-termo; `probes = lists` recupera o recall 100% ao preço de virar varredura.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-06"},{"cap":5,"tipo":"dados","nivel":1,"tempo":6,"titulo":"HNSW contra IVFFlat","enunciado":"Escreva, uma linha por critério, no formato `criterio: vencedor`, com `hnsw`, `ivfflat` ou `empate`. Critérios: `tamanho do indice`, `tempo de construcao`, `recall para o mesmo custo`, `aceita dados novos sem degradar`, `pode ser criado com a tabela vazia`.","modo":"conjunto","esperado":"tamanho do indice: ivfflat\ntempo de construcao: ivfflat\nrecall para o mesmo custo: hnsw\naceita dados novos sem degradar: hnsw\npode ser criado com a tabela vazia: hnsw","solucao":"O IVFFlat vence em espaço (não guarda ligações, só a atribuição a um grupo) e em tempo de construção. O HNSW vence no que importa mais: recall para o mesmo custo de consulta, tolerância a inserções (no IVFFlat as linhas novas caem nos centroides antigos e o recall degrada) e a possibilidade de existir antes dos dados.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-07"},{"cap":5,"tipo":"js","nivel":1,"tempo":8,"titulo":"As regras de bolso em JavaScript","enunciado":"Escreva `lists(n)` e `probes(lists)` com as mesmas regras do pgvector (`n/1000` até 1 milhão, `√n` acima; `probes = √lists`), arredondando para o inteiro mais próximo, mínimo 1.","esqueleto":"function lists(n) {\n  // ...\n}\nfunction probes(l) {\n  // ...\n}\n","exports":["lists","probes"],"testes":[{"nome":"base média","codigo":"lists(30000) === 30 && probes(30) === 5"},{"nome":"acima do milhão","codigo":"lists(4000000) === 2000"},{"nome":"mínimo 1","codigo":"lists(100) === 1 && probes(1) === 1"}],"solucao":"```js\nfunction lists(n) {\n  return Math.max(1, Math.round(n <= 1e6 ? n / 1000 : Math.sqrt(n)));\n}\nfunction probes(l) {\n  return Math.max(1, Math.round(Math.sqrt(l)));\n}\n```","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-08"},{"cap":5,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"Mais listas, mais fronteira","enunciado":"Uma base de 12.000 pontos. Compare `lists = 12` com `lists = 32`, sondando uma lista em ambos os casos.","campos":[{"label":"pontos examinados por consulta com lists = 12 e probes = 1","valor":1000,"tol":1},{"label":"pontos examinados com lists = 32 e probes = 1","valor":375,"tol":1},{"label":"probes recomendado para lists = 32 (√lists, arredondado)","valor":6,"tol":0.5}],"solucao":"Com 12 listas, cada uma tem 1.000 pontos; com 32, apenas 375. Mais listas deixam a consulta mais barata, mas criam mais fronteiras: com `probes = 1` o recall cai. É a razão de a regra amarrar `probes` a `√lists` — com 32 listas você precisa sondar 6, examinando 2.250 pontos, mais que as 1.000 do caso anterior.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-09"},{"cap":5,"tipo":"texto","nivel":2,"tempo":6,"titulo":"Quando o IVFFlat é a escolha certa","enunciado":"Em 4 linhas: em que situação você escolheria IVFFlat em vez de HNSW, e por que ele não é a escolha do projeto.","rubrica":["A favor: base grande e estável (reconstruída em janelas planejadas) e memória limitada","A favor: também serve como primeiro índice num protótipo quando a construção do HNSW demora demais na máquina disponível","Contra: recall menor para o mesmo custo e degradação com inserções (centroides envelhecem)","No projeto, a base cresce (acórdãos, enunciados) e a memória não é o gargalo: HNSW"],"solucao":"IVFFlat entra quando a memória do índice é o gargalo e a base é estável, reconstruída em janelas planejadas — ou como índice provisório num protótipo, quando construir o HNSW demora demais na máquina disponível. Ele custa recall para o mesmo esforço e envelhece: linhas novas caem nos centroides antigos e a qualidade escorre. No projeto a base cresce continuamente e cabe em memória com folga, então o HNSW é a escolha e o IVFFlat fica como conhecimento para não ser surpreendido em outro sistema.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-10"},{"cap":5,"tipo":"python","nivel":2,"tempo":10,"titulo":"Quando sondar tudo","enunciado":"Escreva `recall_esperado(lists, probes)` que devolve `min(1.0, probes / lists)` como uma aproximação grosseira da fração de vizinhos alcançáveis, e `probes_para(lists, alvo)` que devolve o menor `probes` (inteiro ≥ 1) cuja aproximação atinge o `alvo`.","esqueleto":"import math\n\ndef recall_esperado(lists, probes):\n    ...\n\ndef probes_para(lists, alvo):\n    ...\n","testes":[{"nome":"fração simples","codigo":"assert abs(recall_esperado(12, 3) - 0.25) < 1e-9"},{"nome":"nunca passa de 1","codigo":"assert recall_esperado(12, 20) == 1.0"},{"nome":"probes para o alvo","codigo":"assert probes_para(12, 0.5) == 6 and probes_para(32, 0.25) == 8"},{"nome":"alvo 1 sonda tudo","codigo":"assert probes_para(12, 1.0) == 12"},{"nome":"mínimo 1","codigo":"assert probes_para(12, 0.01) == 1"}],"solucao":"```python\nimport math\n\ndef recall_esperado(lists, probes):\n    return min(1.0, probes / lists)\n\ndef probes_para(lists, alvo):\n    return max(1, min(lists, math.ceil(alvo * lists)))\n```\nÉ uma aproximação pessimista de propósito: na prática os vizinhos se concentram nas listas mais próximas, e `probes = √lists` já dá recall bem acima de `√lists / lists`. Serve para ver que `alvo = 1,0` significa `probes = lists`, ou seja, busca exata.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-11"},{"cap":5,"tipo":"texto","nivel":1,"tempo":4,"titulo":"Por que \"flat\"","enunciado":"Em 2 linhas: o que o \"flat\" do IVFFlat significa.","rubrica":["Dentro de cada lista os vetores ficam inteiros, sem compressão","A busca dentro da lista sondada é exata (força bruta sobre aquele subconjunto)"],"solucao":"\"Flat\" quer dizer que os vetores são guardados inteiros dentro de cada lista, sem compressão. A busca dentro das listas sondadas é força bruta exata; toda a aproximação está em **quais** listas você decidiu olhar. Variantes comprimidas (IVF-PQ) existem em outras ferramentas, não no pgvector.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-12"},{"cap":5,"tipo":"python","nivel":3,"tempo":12,"titulo":"Os centroides envelhecem","enunciado":"Escreva `desequilibrio(atribuicao)` que devolve a razão entre o tamanho da maior lista e o da menor (float; se alguma lista de `atribuicao` estiver vazia isso não acontece, pois só existem listas com pontos). Um IVFFlat recém-construído tem razão perto de 1; depois de muitas inserções, ela cresce — o sinal de que é hora de reconstruir.","esqueleto":"def desequilibrio(atribuicao):\n    ...\n","testes":[{"nome":"equilibrado","codigo":"assert desequilibrio({\"a\": 0, \"b\": 1, \"c\": 0, \"d\": 1}) == 1.0"},{"nome":"desequilibrado","codigo":"assert desequilibrio({\"a\": 0, \"b\": 0, \"c\": 0, \"d\": 1}) == 3.0"},{"nome":"uma lista só","codigo":"assert desequilibrio({\"a\": 0, \"b\": 0}) == 1.0"},{"nome":"vazio","codigo":"assert desequilibrio({}) == 1.0"}],"solucao":"```python\ndef desequilibrio(atribuicao):\n    if not atribuicao:\n        return 1.0\n    contagem = {}\n    for lista in atribuicao.values():\n        contagem[lista] = contagem.get(lista, 0) + 1\n    return max(contagem.values()) / min(contagem.values())\n```\nÉ a métrica de manutenção do IVFFlat: as inserções vão para o centroide mais próximo entre os antigos, e a distribuição real se afasta da que o k-means encontrou. Razão crescendo = recall caindo = `REINDEX`.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-13"},{"cap":5,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"Memória: ligações contra atribuição","enunciado":"Base de 1 milhão de vetores. No HNSW com `m = 16` são cerca de 33 milhões de ligações, 4 bytes cada. No IVFFlat, cada linha guarda só o número da lista a que pertence (4 bytes).","campos":[{"label":"MB de ligações do HNSW (1 MB = 10⁶ bytes)","valor":132,"tol":2},{"label":"MB de atribuição do IVFFlat","valor":4,"tol":0.2},{"label":"quantas vezes o HNSW é maior nessa parte","valor":33,"tol":1}],"solucao":"33 M ligações × 4 bytes = 132 MB só de estrutura; o IVFFlat gasta 4 MB. Em ambos, os vetores em si (3 GB) dominam — mas quando a memória disponível é apertada, 132 MB contra 4 MB é exatamente a conversa que faz alguém escolher IVFFlat.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-14"},{"cap":5,"tipo":"projeto","nivel":2,"tempo":25,"titulo":"A fronteira, no experimento","enunciado":"No experimento \"Partições e sondagens\", coloque `lists = 12` e `probes = 1` e clique bem na fronteira entre duas cores: anote quantos vizinhos exatos ficaram com contorno vermelho. Suba `probes` para 2 e 3 e refaça no mesmo ponto. Depois use `lists = 32` com `probes = 1`.","entrega":"Tabela (lists, probes) × (vizinhos perdidos na fronteira, recall médio das 80 consultas).","rubrica":["Cliquei no mesmo ponto de fronteira ao variar probes (senão a comparação não vale)","Vi os vizinhos perdidos caírem conforme probes sobe, e o recall médio estabilizar perto de √lists","Com lists = 32 e probes = 1 o recall caiu: mais listas, mais fronteiras","Relacionei o resultado com a regra probes ≈ √lists"],"solucao":"O padrão: na fronteira com `probes = 1` costuma faltar um ou dois vizinhos exatos; com `probes = 2` quase sempre voltam, e a partir de `√12 ≈ 3` o recall médio das 80 consultas estabiliza. Com `lists = 32`, cada lista tem menos pontos e há mais fronteiras: `probes = 1` perde mais, e a regra pede 6 sondagens. É a demonstração de que `lists` e `probes` se movem juntos.","ligacoes":["03-busca-vetorial.html#c5"],"id":"p3-c5-15"},{"cap":6,"tipo":"dados","nivel":1,"tempo":5,"titulo":"Operador, classe e métrica","enunciado":"Escreva, uma linha por métrica, no formato `metrica: operador classe`. Métricas: `cosseno`, `produto interno`, `euclidiana`.","modo":"conjunto","esperado":"cosseno: <=> vector_cosine_ops\nproduto interno: <#> vector_ip_ops\neuclidiana: <-> vector_l2_ops","solucao":"`<=>` com `vector_cosine_ops`, `<#>` com `vector_ip_ops`, `<->` com `vector_l2_ops`. A classe do índice precisa casar com o operador do `ORDER BY`: indexar em cosseno e consultar com `<->` faz o planejador ignorar o índice, sem aviso.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-01"},{"cap":6,"tipo":"python","nivel":3,"tempo":15,"titulo":"O índice vai ser usado?","enunciado":"Escreva `usa_indice(consulta)` que recebe `{\"classe\", \"operador\", \"forma\", \"limit\"}` e devolve `(True, \"ok\")` ou `(False, motivo)`. As quatro condições: a `classe` precisa casar com o `operador` (`vector_cosine_ops`↔`<=>`, `vector_ip_ops`↔`<#>`, `vector_l2_ops`↔`<->`) senão `\"operador não casa com a classe\"`; a `forma` precisa ser `\"operador\"` senão `\"ORDER BY com expressão\"` (para `\"expressao\"`) ou `\"ORDER BY DESC\"` (para `\"desc\"`); e precisa haver `limit` (não nulo) senão `\"sem LIMIT\"`. Verifique nessa ordem.","esqueleto":"def usa_indice(consulta):\n    ...\n","testes":[{"nome":"tudo certo","codigo":"assert usa_indice({\"classe\": \"vector_cosine_ops\", \"operador\": \"<=>\", \"forma\": \"operador\", \"limit\": 12}) == (True, \"ok\")"},{"nome":"classe errada","codigo":"assert usa_indice({\"classe\": \"vector_cosine_ops\", \"operador\": \"<->\", \"forma\": \"operador\", \"limit\": 12}) == (False, \"operador não casa com a classe\")"},{"nome":"expressão no ORDER BY","codigo":"assert usa_indice({\"classe\": \"vector_cosine_ops\", \"operador\": \"<=>\", \"forma\": \"expressao\", \"limit\": 12}) == (False, \"ORDER BY com expressão\")"},{"nome":"DESC","codigo":"assert usa_indice({\"classe\": \"vector_l2_ops\", \"operador\": \"<->\", \"forma\": \"desc\", \"limit\": 12}) == (False, \"ORDER BY DESC\")"},{"nome":"sem LIMIT","codigo":"assert usa_indice({\"classe\": \"vector_ip_ops\", \"operador\": \"<#>\", \"forma\": \"operador\", \"limit\": None}) == (False, \"sem LIMIT\")"}],"solucao":"```python\nPARES = {\"vector_cosine_ops\": \"<=>\", \"vector_ip_ops\": \"<#>\", \"vector_l2_ops\": \"<->\"}\n\ndef usa_indice(consulta):\n    if PARES.get(consulta[\"classe\"]) != consulta[\"operador\"]:\n        return (False, \"operador não casa com a classe\")\n    if consulta[\"forma\"] == \"expressao\":\n        return (False, \"ORDER BY com expressão\")\n    if consulta[\"forma\"] == \"desc\":\n        return (False, \"ORDER BY DESC\")\n    if not consulta[\"limit\"]:\n        return (False, \"sem LIMIT\")\n    return (True, \"ok\")\n```\nSão as quatro formas de perder o índice em silêncio. Em todas elas a consulta continua **correta** — só fica cem vezes mais lenta.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-02"},{"cap":6,"tipo":"sql","nivel":2,"tempo":10,"titulo":"A consulta que usa o índice","enunciado":"Escreva a consulta do projeto: os 50 trechos mais próximos de `%s::vector` em `rag.trecho_normativo`, com `1 - (embedding <=> %s::vector) AS similaridade` no SELECT, filtrando `modelo_embedding = %s`, ordenando pelo operador puro e limitando a 50. A similaridade **não** pode aparecer no `ORDER BY`.","esqueleto":"SELECT ...\n","checks":[{"re":"1\\s*-\\s*\\(\\s*embedding\\s*<=>\\s*%s::vector\\s*\\)\\s+AS\\s+similaridade","msg":"similaridade calculada no SELECT"},{"re":"ORDER BY\\s+embedding\\s*<=>\\s*%s::vector\\s*(?:ASC\\s*)?LIMIT","flags":"is","msg":"ORDER BY pelo operador puro, seguido de LIMIT"},{"re":"LIMIT\\s+50","msg":"limita a 50"},{"re":"WHERE\\s+modelo_embedding\\s*=\\s*%s","msg":"trava pelo modelo"},{"re":"ORDER BY[\\s\\S]*(?:DESC|1\\s*-)","deve":false,"msg":"nada de DESC nem de expressão no ORDER BY"}],"solucao":"```sql\nSELECT id, dispositivo, 1 - (embedding <=> %s::vector) AS similaridade\nFROM rag.trecho_normativo\nWHERE modelo_embedding = %s\nORDER BY embedding <=> %s::vector\nLIMIT 50;\n```\nA expressão no `SELECT` é grátis: o planejador usa o índice para ordenar e só avalia `1 - (…)` nas 50 linhas devolvidas. A mesma expressão no `ORDER BY` derruba o índice.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-03"},{"cap":6,"tipo":"dados","nivel":2,"tempo":6,"titulo":"As quatro formas de perder o índice","enunciado":"Escreva, uma por linha, as quatro formas de o planejador ignorar o índice vetorial, usando exatamente estes rótulos: `expressao no ORDER BY`, `ORDER BY DESC`, `sem LIMIT`, `operador diferente da classe do indice`.","modo":"conjunto","esperado":"expressao no ORDER BY\nORDER BY DESC\nsem LIMIT\noperador diferente da classe do indice","solucao":"Ordenar por `1 - (embedding <=> q)` em vez de pelo operador; usar `DESC`; esquecer o `LIMIT`; e consultar com um operador que não casa com a classe do índice. Em todos os casos a consulta devolve o resultado certo — por varredura completa.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-04"},{"cap":6,"tipo":"js","nivel":2,"tempo":10,"titulo":"O verificador de consulta em JavaScript","enunciado":"Escreva `verificar({classe, operador, forma, limit})` que devolve `{usa: true, motivo: \"ok\"}` ou `{usa: false, motivo}` com os mesmos motivos e a mesma ordem de checagem do exercício em Python: `\"operador não casa com a classe\"`, `\"ORDER BY com expressão\"` (forma `\"expressao\"`), `\"ORDER BY DESC\"` (forma `\"desc\"`), `\"sem LIMIT\"`.","esqueleto":"function verificar(c) {\n  // ...\n}\n","exports":["verificar"],"testes":[{"nome":"ok","codigo":"iguais(verificar({classe: \"vector_cosine_ops\", operador: \"<=>\", forma: \"operador\", limit: 12}), {usa: true, motivo: \"ok\"})"},{"nome":"classe errada vem primeiro","codigo":"verificar({classe: \"vector_cosine_ops\", operador: \"<->\", forma: \"expressao\", limit: 12}).motivo === \"operador não casa com a classe\""},{"nome":"sem limit","codigo":"verificar({classe: \"vector_l2_ops\", operador: \"<->\", forma: \"operador\", limit: 0}).motivo === \"sem LIMIT\""}],"solucao":"```js\nconst PARES = { vector_cosine_ops: \"<=>\", vector_ip_ops: \"<#>\", vector_l2_ops: \"<->\" };\n\nfunction verificar(c) {\n  if (PARES[c.classe] !== c.operador) return { usa: false, motivo: \"operador não casa com a classe\" };\n  if (c.forma === \"expressao\") return { usa: false, motivo: \"ORDER BY com expressão\" };\n  if (c.forma === \"desc\") return { usa: false, motivo: \"ORDER BY DESC\" };\n  if (!c.limit) return { usa: false, motivo: \"sem LIMIT\" };\n  return { usa: true, motivo: \"ok\" };\n}\n```","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-05"},{"cap":6,"tipo":"python","nivel":3,"tempo":12,"titulo":"Ler o EXPLAIN","enunciado":"Escreva `ler_explain(texto)` que recebe a saída do `EXPLAIN (ANALYZE, BUFFERS)` e devolve `{\"indice\": nome ou None, \"linhas\": int, \"ms\": float, \"do_disco\": bool}`: o nome do índice em `Index Scan using <nome>` (ou `None` se houver `Seq Scan`), o `rows=` da primeira linha do plano, o `Execution Time` em ms, e `do_disco` verdadeiro se `Buffers` tiver um `read=` maior que zero.","esqueleto":"import re\n\ndef ler_explain(texto):\n    ...\n","testes":[{"nome":"índice usado, tudo em cache","codigo":"T = \"\"\"Limit (cost=0.00..1.00 rows=12) (actual time=1.84..2.31 rows=12 loops=1)\n  ->  Index Scan using trecho_emb_hnsw on trecho_normativo (actual time=1.83..2.29 rows=12 loops=1)\n        Buffers: shared hit=143\nPlanning Time: 0.21 ms\nExecution Time: 2.40 ms\"\"\"\nassert ler_explain(T) == {\"indice\": \"trecho_emb_hnsw\", \"linhas\": 12, \"ms\": 2.40, \"do_disco\": False}"},{"nome":"varredura e disco","codigo":"T = \"\"\"Limit (cost=0.00..9.00 rows=12) (actual time=210.0..240.0 rows=12 loops=1)\n  ->  Seq Scan on trecho_normativo (actual time=0.1..238.0 rows=30000 loops=1)\n        Buffers: shared hit=12 read=4200\nExecution Time: 241.7 ms\"\"\"\nr = ler_explain(T)\nassert r[\"indice\"] is None and r[\"do_disco\"] is True and r[\"ms\"] == 241.7"},{"nome":"linhas menores que o LIMIT","codigo":"T = \"\"\"Limit (cost=0.00..1.00 rows=12) (actual time=1.0..1.2 rows=3 loops=1)\n  ->  Index Scan using trecho_emb_hnsw on trecho_normativo (actual time=1.0..1.2 rows=3 loops=1)\n        Buffers: shared hit=90\nExecution Time: 1.3 ms\"\"\"\nassert ler_explain(T)[\"linhas\"] == 3"}],"solucao":"```python\nimport re\n\ndef ler_explain(texto):\n    m = re.search(r\"Index Scan using (\\w+)\", texto)\n    linhas = re.search(r\"actual time=[\\d.]+\\.\\.[\\d.]+ rows=(\\d+)\", texto)\n    ms = re.search(r\"Execution Time: ([\\d.]+) ms\", texto)\n    read = re.search(r\"read=(\\d+)\", texto)\n    return {\n        \"indice\": m.group(1) if m else None,\n        \"linhas\": int(linhas.group(1)) if linhas else 0,\n        \"ms\": float(ms.group(1)) if ms else 0.0,\n        \"do_disco\": bool(read and int(read.group(1)) > 0),\n    }\n```\nOs três sintomas que este parser detecta são os três do capítulo: `indice = None` (perdeu o índice), `do_disco = True` (índice frio, capítulo 8) e `linhas` menor que o `LIMIT` (pós-filtragem, capítulo 7).","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-06"},{"cap":6,"tipo":"texto","nivel":2,"tempo":6,"titulo":"A expressão no ORDER BY","enunciado":"Em 3 linhas: por que `ORDER BY 1 - (embedding <=> q) DESC LIMIT 12` não usa o índice, o que ela devolve, e qual é a forma certa.","rubrica":["O planejador só reconhece o operador de distância puro, em ordem crescente","A consulta devolve o resultado certo, por varredura completa: o erro é silencioso, de desempenho","A forma certa é ordenar pelo operador no ORDER BY e calcular a similaridade no SELECT"],"solucao":"O planejador só sabe usar o índice quando o `ORDER BY` é o operador de distância puro, em ordem crescente — `1 - (…)` é uma expressão qualquer para ele, e `DESC` inverte o sentido que o índice conhece. O resultado sai certo, por `Seq Scan` com `Sort`: nenhum erro, só uma consulta que passa de milissegundos a centenas de milissegundos. A forma certa é `ORDER BY embedding <=> q LIMIT 12`, com `1 - (embedding <=> q) AS similaridade` no `SELECT`.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-07"},{"cap":6,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"Quando o vector não cabe no índice","enunciado":"Os índices HNSW e IVFFlat sobre o tipo `vector` aceitam até 2.000 dimensões; sobre `halfvec`, até 4.000. Um vetor tem 3.072 dimensões.","campos":[{"label":"bytes de um vetor de 3.072 dimensões em vector (4 bytes/dim)","valor":12288,"tol":1},{"label":"bytes do mesmo vetor em halfvec (2 bytes/dim)","valor":6144,"tol":1},{"label":"dimensões que sobram até o limite do índice sobre halfvec","valor":928,"tol":1}],"solucao":"3.072 dimensões em `vector` são 12.288 bytes e **não podem ser indexadas** (limite de 2.000). Em `halfvec` são 6.144 bytes e cabem, com 928 dimensões de folga até o limite de 4.000. É a advertência do montador de índice: com 3.072 dimensões, ou você trunca (página 2), ou usa `halfvec`, ou fica sem índice.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-08"},{"cap":6,"tipo":"texto","nivel":1,"tempo":5,"titulo":"O que procurar no EXPLAIN","enunciado":"Em 4 linhas: as quatro coisas que você procura na saída de `EXPLAIN (ANALYZE, BUFFERS)` de uma consulta vetorial.","rubrica":["A linha `Index Scan using <nome>`: o índice foi usado (se aparecer `Seq Scan` com `Sort`, não foi)","O `actual time` / `Execution Time`: a latência real, não a estimada","Buffers `shared hit` contra `read`: quanto veio da memória e quanto do disco (índice frio)","`rows` igual ao `LIMIT`: se vier menor, é pós-filtragem (capítulo 7)"],"solucao":"Primeiro, `Index Scan using trecho_emb_hnsw`: se no lugar aparecer `Seq Scan` com `Sort`, o índice foi ignorado e a forma da consulta está errada. Segundo, o `Execution Time`, que é a latência real (o `cost` é só estimativa). Terceiro, `Buffers: shared hit=` contra `read=`: leitura de disco em toda consulta significa índice frio ou memória insuficiente. Quarto, `rows` igual ao `LIMIT`: menos linhas que o pedido é o sintoma da pós-filtragem.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-09"},{"cap":6,"tipo":"python","nivel":1,"tempo":8,"titulo":"Escolher a classe pela métrica","enunciado":"Escreva `classe_para(operador)` que devolve a classe de operador correspondente, e `compativel(classe, operador)` que devolve `True` se casarem. Operadores desconhecidos devolvem `None` e `False`.","esqueleto":"def classe_para(operador):\n    ...\n\ndef compativel(classe, operador):\n    ...\n","testes":[{"nome":"os três pares","codigo":"assert classe_para(\"<=>\") == \"vector_cosine_ops\" and classe_para(\"<#>\") == \"vector_ip_ops\" and classe_para(\"<->\") == \"vector_l2_ops\""},{"nome":"desconhecido","codigo":"assert classe_para(\"<~>\") is None and compativel(\"vector_cosine_ops\", \"<~>\") is False"},{"nome":"compatível","codigo":"assert compativel(\"vector_cosine_ops\", \"<=>\") is True"},{"nome":"incompatível","codigo":"assert compativel(\"vector_cosine_ops\", \"<->\") is False"}],"solucao":"```python\nCLASSES = {\"<=>\": \"vector_cosine_ops\", \"<#>\": \"vector_ip_ops\", \"<->\": \"vector_l2_ops\"}\n\ndef classe_para(operador):\n    return CLASSES.get(operador)\n\ndef compativel(classe, operador):\n    return CLASSES.get(operador) == classe\n```\nCom vetores normalizados as três métricas dão o mesmo ranking (página 2), então o projeto cria **um** índice, de cosseno, e usa `<=>` em todas as consultas.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-10"},{"cap":6,"tipo":"sql","nivel":1,"tempo":6,"titulo":"Onde definir o ef_search","enunciado":"Escreva as três formas de definir `hnsw.ef_search = 100`, uma por linha: para a sessão, para a transação, e como padrão do banco `rag` para novas conexões.","esqueleto":"-- sessão\n-- transação\n-- banco\n","checks":[{"re":"^\\s*SET\\s+hnsw\\.ef_search\\s*=\\s*100","flags":"im","msg":"SET para a sessão"},{"re":"SET LOCAL\\s+hnsw\\.ef_search\\s*=\\s*100","flags":"i","msg":"SET LOCAL para a transação"},{"re":"ALTER DATABASE\\s+rag\\s+SET\\s+hnsw\\.ef_search\\s*=\\s*100","flags":"i","msg":"ALTER DATABASE para novas conexões"}],"solucao":"```sql\nSET hnsw.ef_search = 100;                        -- vale para a sessão\nSET LOCAL hnsw.ef_search = 100;                  -- vale só para a transação\nALTER DATABASE rag SET hnsw.ef_search = 100;     -- padrão para novas conexões\n```\nO ia-worker usa `SET LOCAL` dentro da transação de busca: com um pool de conexões, é a única forma de garantir que o valor não vaze de uma requisição para outra — e fica no código, versionado junto com a consulta.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-11"},{"cap":6,"tipo":"python","nivel":2,"tempo":10,"titulo":"Quantos índices essa coluna precisa","enunciado":"Escreva `indices_necessarios(operadores_usados, normalizados)` que devolve a lista ordenada de classes de operador a criar. Se os vetores forem `normalizados`, as três métricas dão o mesmo ranking (página 2) e basta `[\"vector_cosine_ops\"]`, qualquer que seja o conjunto de operadores usados. Se não forem, é preciso uma classe para cada operador realmente usado.","esqueleto":"def indices_necessarios(operadores_usados, normalizados):\n    ...\n","testes":[{"nome":"normalizados: um índice só","codigo":"assert indices_necessarios([\"<=>\", \"<#>\", \"<->\"], True) == [\"vector_cosine_ops\"]"},{"nome":"normalizados com um operador só","codigo":"assert indices_necessarios([\"<->\"], True) == [\"vector_cosine_ops\"]"},{"nome":"não normalizados: um por operador","codigo":"assert indices_necessarios([\"<=>\", \"<->\"], False) == [\"vector_cosine_ops\", \"vector_l2_ops\"]"},{"nome":"sem repetir","codigo":"assert indices_necessarios([\"<#>\", \"<#>\"], False) == [\"vector_ip_ops\"]"},{"nome":"nenhum operador","codigo":"assert indices_necessarios([], False) == []"}],"solucao":"```python\nCLASSES = {\"<=>\": \"vector_cosine_ops\", \"<#>\": \"vector_ip_ops\", \"<->\": \"vector_l2_ops\"}\n\ndef indices_necessarios(operadores_usados, normalizados):\n    if not operadores_usados:\n        return []\n    if normalizados:\n        return [\"vector_cosine_ops\"]\n    return sorted({CLASSES[op] for op in operadores_usados})\n```\nDá para ter um índice por métrica na mesma coluna, e o planejador escolhe pelo operador da consulta — mas cada um custa memória e construção. Como os vetores do projeto são normalizados, dois índices seriam duas cópias do mesmo ranking: a regra é um índice por métrica **realmente** necessária, o que aqui significa um.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-12"},{"cap":6,"tipo":"calculo","nivel":1,"tempo":5,"titulo":"O preço de perder o índice","enunciado":"Com o índice, a consulta leva 2,4 ms. Sem ele (por causa de uma expressão no `ORDER BY`), 240 ms. O sistema atende 20 consultas por segundo em horário de pico.","campos":[{"label":"quantas vezes mais lenta a consulta fica","valor":100,"tol":1},{"label":"tempo total gasto em busca por segundo, com índice (ms)","valor":48,"tol":1},{"label":"tempo total por segundo, sem índice (ms)","valor":4800,"tol":10}],"solucao":"100× mais lenta. Com índice, 20 × 2,4 = 48 ms de trabalho por segundo — folgado. Sem índice, 4.800 ms por segundo de trabalho para 1.000 ms de tempo real: a fila explode e o sistema para. E tudo isso sem uma linha de erro em lugar nenhum, porque a consulta continua correta.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-13"},{"cap":6,"tipo":"python","nivel":2,"tempo":10,"titulo":"Dá para indexar essa dimensão?","enunciado":"Escreva `pode_indexar(dims, tipo=\"vector\")` que devolve `(True, \"\")` ou `(False, sugestao)`: os índices HNSW e IVFFlat aceitam até 2.000 dimensões sobre `vector` e até 4.000 sobre `halfvec`. Acima do limite do `vector`, sugira `\"use halfvec\"` se couber em `halfvec`, e `\"trunque o vetor\"` se nem lá couber. Sobre `halfvec` acima de 4.000, a sugestão é sempre `\"trunque o vetor\"`.","esqueleto":"def pode_indexar(dims, tipo=\"vector\"):\n    ...\n","testes":[{"nome":"768 cabe","codigo":"assert pode_indexar(768) == (True, \"\")"},{"nome":"3072 não cabe em vector","codigo":"assert pode_indexar(3072) == (False, \"use halfvec\")"},{"nome":"3072 cabe em halfvec","codigo":"assert pode_indexar(3072, \"halfvec\") == (True, \"\")"},{"nome":"acima de 4000 não tem jeito","codigo":"assert pode_indexar(5000) == (False, \"trunque o vetor\") and pode_indexar(5000, \"halfvec\") == (False, \"trunque o vetor\")"},{"nome":"exatamente no limite","codigo":"assert pode_indexar(2000) == (True, \"\") and pode_indexar(4000, \"halfvec\") == (True, \"\")"}],"solucao":"```python\nLIMITES = {\"vector\": 2000, \"halfvec\": 4000}\n\ndef pode_indexar(dims, tipo=\"vector\"):\n    if dims <= LIMITES[tipo]:\n        return (True, \"\")\n    if tipo == \"vector\" and dims <= LIMITES[\"halfvec\"]:\n        return (False, \"use halfvec\")\n    return (False, \"trunque o vetor\")\n```\nÉ a advertência do montador de índice do capítulo 6, e mais um motivo para o projeto truncar o `gemini-embedding-001` de 3.072 para 768 (página 2): com 3.072 em `vector` não existe índice possível.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-14"},{"cap":6,"tipo":"projeto","nivel":2,"tempo":30,"titulo":"EXPLAIN das quatro formas de errar","enunciado":"No banco do Ex. 3, com o índice HNSW criado, rode `EXPLAIN (ANALYZE, BUFFERS)` em cinco variações da mesma consulta: a forma certa; com `1 - (embedding <=> q)` no `ORDER BY`; com `DESC`; sem `LIMIT`; e com `<->` em vez de `<=>`. Anote o plano e o `Execution Time` de cada uma.","entrega":"Tabela variação × (plano, Execution Time) e a conclusão.","rubrica":["Rodei as cinco variações contra a mesma tabela e o mesmo vetor de consulta","Vi `Index Scan using trecho_emb_hnsw` só na forma certa","Vi `Seq Scan` (ou `Sort`) nas outras quatro, com resultado correto e tempo muito maior","Registrei a diferença de Execution Time entre a forma certa e a pior"],"solucao":"O esperado: só a primeira mostra `Index Scan using trecho_emb_hnsw`; as outras quatro caem em `Seq Scan` + `Sort` e devolvem exatamente as mesmas linhas, mais devagar. Em bases pequenas a diferença pode ser de poucos milissegundos e passar despercebida — que é justamente o perigo: o erro só aparece quando a base cresce, em produção. Por isso a verificação entra no roteiro de testes, não na inspeção visual.","ligacoes":["03-busca-vetorial.html#c6"],"id":"p3-c6-15"},{"cap":7,"tipo":"python","nivel":2,"tempo":12,"titulo":"Pós-filtragem: o que sobra","enunciado":"Escreva `pos_filtragem(candidatos, passa, k)` que simula o comportamento padrão do pgvector: `candidatos` são os ids que o índice devolveu **por distância**, já ordenados; `passa` é um dicionário `id → bool` com o resultado do `WHERE`. Devolva `(devolvidos, faltaram)`: os até `k` primeiros candidatos que passam no filtro, e quantos faltaram para completar `k`.","esqueleto":"def pos_filtragem(candidatos, passa, k):\n    ...\n","testes":[{"nome":"completa o k","codigo":"C = [\"a\", \"b\", \"c\", \"d\", \"e\"]; P = {\"a\": True, \"b\": False, \"c\": True, \"d\": True, \"e\": True}\nassert pos_filtragem(C, P, 3) == ([\"a\", \"c\", \"d\"], 0)"},{"nome":"filtro seletivo rouba resultados","codigo":"C = [\"a\", \"b\", \"c\", \"d\", \"e\"]; P = {\"a\": False, \"b\": False, \"c\": True, \"d\": False, \"e\": False}\nassert pos_filtragem(C, P, 3) == ([\"c\"], 2)"},{"nome":"ninguém passa","codigo":"assert pos_filtragem([\"a\", \"b\"], {\"a\": False, \"b\": False}, 2) == ([], 2)"},{"nome":"sobra candidato","codigo":"assert pos_filtragem([\"a\", \"b\", \"c\"], {\"a\": True, \"b\": True, \"c\": True}, 2) == ([\"a\", \"b\"], 0)"}],"solucao":"```python\ndef pos_filtragem(candidatos, passa, k):\n    devolvidos = [c for c in candidatos if passa.get(c)][:k]\n    return (devolvidos, k - len(devolvidos))\n```\nO índice escolhe os candidatos **antes** de saber do filtro. Se o filtro é seletivo, o `LIMIT 12` vira 2 linhas — sem erro, sem aviso. O sintoma no `EXPLAIN` é `rows` menor que o `LIMIT`.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-01"},{"cap":7,"tipo":"python","nivel":3,"tempo":15,"titulo":"Os três modos, comparados","enunciado":"Escreva `buscar(q, base, k, ef, modo, ano)` que devolve `(ids, distancias)` sobre a `BASE` (id → `(valor, ano)`), com `dist(a, b)` já definida. Modos: `\"posfiltro\"` pega os `ef` mais próximos por distância e depois filtra por `ano`, ficando com até `k`; `\"iterativo\"` vai pegando os mais próximos que passam no filtro até juntar `k` (examinando no máximo `ef * 10` candidatos); `\"exato\"` filtra primeiro e ordena só o que passou. `distancias` é quantos itens da base foram examinados em cada modo (`ef`, o número examinado até completar, e o total de linhas que passam no filtro, respectivamente). Empates pelo id.","esqueleto":"import math\n\n# base sintética: id -> (vetor 1D, ano de vigência)\nBASE = {f\"t{i:02d}\": (float(i), 2021 if i % 5 == 0 else 2024) for i in range(1, 41)}\n\ndef dist(a, b):\n    return abs(a - b)\n\ndef buscar(q, base, k, ef, modo, ano):\n    ...\n","setup":"import math\n\n# base sintética: id -> (vetor 1D, ano de vigência)\nBASE = {f\"t{i:02d}\": (float(i), 2021 if i % 5 == 0 else 2024) for i in range(1, 41)}\n\ndef dist(a, b):\n    return abs(a - b)\n","testes":[{"nome":"pós-filtro devolve menos que k","codigo":"ids, d = buscar(20.0, BASE, 5, 10, \"posfiltro\", 2021)\nassert len(ids) < 5 and d == 10"},{"nome":"iterativo completa o k","codigo":"ids, d = buscar(20.0, BASE, 5, 10, \"iterativo\", 2021)\nassert len(ids) == 5 and d > 10"},{"nome":"exato examina só quem passa","codigo":"ids, d = buscar(20.0, BASE, 5, 10, \"exato\", 2021)\nassert len(ids) == 5 and d == 8"},{"nome":"os três concordam quando o filtro é frouxo","codigo":"a = buscar(20.0, BASE, 3, 20, \"posfiltro\", 2024)[0]\nb = buscar(20.0, BASE, 3, 20, \"iterativo\", 2024)[0]\nc = buscar(20.0, BASE, 3, 20, \"exato\", 2024)[0]\nassert a == b == c"}],"solucao":"```python\ndef buscar(q, base, k, ef, modo, ano):\n    por_dist = sorted(base, key=lambda i: (dist(q, base[i][0]), i))\n    if modo == \"posfiltro\":\n        candidatos = por_dist[:ef]\n        return ([i for i in candidatos if base[i][1] == ano][:k], ef)\n    if modo == \"iterativo\":\n        achados, examinados = [], 0\n        for i in por_dist[: ef * 10]:\n            examinados += 1\n            if base[i][1] == ano:\n                achados.append(i)\n                if len(achados) == k:\n                    break\n        return (achados, examinados)\n    passam = [i for i in por_dist if base[i][1] == ano]\n    return (passam[:k], len(passam))\n```\nOs três devolvem a mesma coisa quando o filtro é frouxo; quando ele é seletivo, o primeiro devolve menos linhas, o segundo paga mais candidatos para completar, e o terceiro é o mais barato **e** exato. É a razão de a escolha depender da seletividade.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-02"},{"cap":7,"tipo":"calculo","nivel":2,"tempo":8,"titulo":"Quantos sobram depois do filtro","enunciado":"Consulta com `LIMIT 12` e `hnsw.ef_search = 40`, sem varredura iterativa. O filtro de vigência deixa passar uma fração das linhas.","campos":[{"label":"linhas esperadas com filtro que passa 90%","valor":12,"tol":0.5},{"label":"linhas esperadas com filtro que passa 10%","valor":4,"tol":0.5},{"label":"linhas esperadas com filtro que passa 4%","valor":1.6,"tol":0.2},{"label":"ef_search necessário para esperar 12 linhas com filtro de 10%","valor":120,"tol":2}],"solucao":"Com 90% passando, dos 40 candidatos sobram 36: o `LIMIT 12` é atendido. Com 10%, sobram 4; com 4%, 1,6. Para esperar 12 linhas com filtro de 10% seria preciso `ef_search = 120` — e com 4%, 300. É por isso que subir o `ef_search` só resolve filtros moderados.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-03"},{"cap":7,"tipo":"python","nivel":2,"tempo":10,"titulo":"Escolher a solução pela seletividade","enunciado":"Escreva `solucao_filtro(seletividade, filtro_fixo)` que devolve a estratégia recomendada: `\"exata pre-filtrada\"` se a seletividade for menor que 0,02; `\"indice parcial\"` se o filtro for sempre o mesmo (`filtro_fixo`); `\"iterative_scan\"` se a seletividade for menor que 0,5; `\"ef_search\"` caso contrário. Verifique nessa ordem.","esqueleto":"def solucao_filtro(seletividade, filtro_fixo):\n    ...\n","testes":[{"nome":"muito seletivo","codigo":"assert solucao_filtro(0.01, False) == \"exata pre-filtrada\""},{"nome":"filtro fixo","codigo":"assert solucao_filtro(0.2, True) == \"indice parcial\""},{"nome":"seletivo e variável","codigo":"assert solucao_filtro(0.1, False) == \"iterative_scan\""},{"nome":"pouco seletivo","codigo":"assert solucao_filtro(0.9, False) == \"ef_search\""},{"nome":"muito seletivo vence o filtro fixo","codigo":"assert solucao_filtro(0.005, True) == \"exata pre-filtrada\""}],"solucao":"```python\ndef solucao_filtro(seletividade, filtro_fixo):\n    if seletividade < 0.02:\n        return \"exata pre-filtrada\"\n    if filtro_fixo:\n        return \"indice parcial\"\n    if seletividade < 0.5:\n        return \"iterative_scan\"\n    return \"ef_search\"\n```\nA ordem importa: quando sobram poucas centenas de linhas, a busca exata sobre elas ganha de qualquer índice, e ainda tem recall 100%. O projeto usa `iterative_scan` porque o filtro de vigência é variável e, no caso comum, pouco seletivo.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-04"},{"cap":7,"tipo":"sql","nivel":2,"tempo":10,"titulo":"A busca com vigência","enunciado":"Escreva a consulta de busca do projeto: 50 trechos de `rag.trecho_normativo`, filtrando `modelo_embedding = %s` e a vigência na data do documento (`vigencia_inicio <= %s::date` e `vigencia_fim` nulo ou maior que essa data), ordenados por `embedding <=> %s::vector`, com a similaridade no SELECT.","esqueleto":"SELECT ...\n","checks":[{"re":"vigencia_inicio\\s*<=\\s*%s::date","msg":"vigência começou antes da data"},{"re":"vigencia_fim\\s+IS\\s+NULL\\s+OR\\s+vigencia_fim\\s*>\\s*%s::date","flags":"is","msg":"vigência não terminou (nulo ou posterior)"},{"re":"modelo_embedding\\s*=\\s*%s","msg":"trava pelo modelo"},{"re":"ORDER BY\\s+embedding\\s*<=>\\s*%s::vector","msg":"ordena pelo operador puro"},{"re":"LIMIT\\s+50","msg":"limita a 50"},{"re":"1\\s*-\\s*\\(\\s*embedding\\s*<=>","msg":"similaridade no SELECT"}],"solucao":"```sql\nSELECT id, dispositivo, 1 - (embedding <=> %s::vector) AS similaridade\nFROM rag.trecho_normativo\nWHERE modelo_embedding = %s\n  AND vigencia_inicio <= %s::date\n  AND (vigencia_fim IS NULL OR vigencia_fim > %s::date)\nORDER BY embedding <=> %s::vector\nLIMIT 50;\n```\nO `vigencia_fim IS NULL` é o dispositivo ainda vigente. Esta consulta roda dentro da transação com `SET LOCAL hnsw.iterative_scan = relaxed_order`, senão os documentos antigos (filtro seletivo) voltam com menos linhas que o pedido.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-05"},{"cap":7,"tipo":"texto","nivel":3,"tempo":8,"titulo":"O sintoma e as quatro soluções","enunciado":"Em até 6 linhas: qual é o sintoma de um filtro seletivo sobre um índice aproximado, e quais são as quatro soluções com o critério de escolha de cada uma.","rubrica":["Sintoma: menos linhas que o LIMIT, sem erro nem aviso (`rows` menor que o LIMIT no EXPLAIN, ou prompt curto demais)","Subir ef_search: funciona para filtros moderados; para os seletivos o ef precisaria ser enorme","Varredura iterativa (hnsw.iterative_scan): o índice continua expandindo até juntar k linhas que passem — solução geral, a do projeto","Índice parcial (CREATE INDEX … WHERE): quando o filtro é quase sempre o mesmo","Pré-filtragem exata: quando o filtro deixa poucas centenas de linhas, a busca exata sobre elas é mais rápida e tem recall 100%"],"solucao":"O sintoma é silencioso: a consulta devolve menos linhas que o `LIMIT` e não reclama. No `EXPLAIN` aparece como `rows` menor que o pedido; na aplicação, como um contexto de prompt misteriosamente curto. Subir o `ef_search` resolve filtros moderados e vira inviável nos seletivos. A varredura iterativa (`hnsw.iterative_scan`) faz o índice continuar expandindo até completar `k` linhas que passem, e é a solução geral — a que o projeto usa. Um índice parcial (`CREATE INDEX … WHERE vigente`) elimina o problema quando o filtro é sempre o mesmo. E quando sobram poucas centenas de linhas, a busca exata pré-filtrada ganha em tudo, inclusive em recall.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-06"},{"cap":7,"tipo":"sql","nivel":2,"tempo":8,"titulo":"Índice parcial","enunciado":"Escreva um índice HNSW parcial chamado `trecho_emb_vigente` sobre `rag.trecho_normativo (embedding)` com `vector_cosine_ops`, cobrindo apenas as linhas com `vigencia_fim IS NULL` (os dispositivos ainda vigentes), com `m = 16` e `ef_construction = 64`.","esqueleto":"CREATE INDEX ...\n","checks":[{"re":"CREATE INDEX\\s+trecho_emb_vigente","msg":"nome do índice"},{"re":"USING\\s+hnsw\\s*\\(\\s*embedding\\s+vector_cosine_ops\\s*\\)","msg":"hnsw com a classe de cosseno"},{"re":"WHERE\\s+vigencia_fim\\s+IS\\s+NULL","msg":"cláusula WHERE do índice parcial"},{"re":"m\\s*=\\s*16","msg":"m = 16"},{"re":"ef_construction\\s*=\\s*64","msg":"ef_construction = 64"}],"solucao":"```sql\nCREATE INDEX trecho_emb_vigente ON rag.trecho_normativo\n  USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64)\n  WHERE vigencia_fim IS NULL;\n```\nMenor, mais rápido de construir, e sem pós-filtragem para o caso mais comum. O preço é que ele **só** serve para consultas que incluam exatamente esse `WHERE` — consultas com data retroativa continuam precisando do índice completo.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-07"},{"cap":7,"tipo":"js","nivel":2,"tempo":8,"titulo":"A pós-filtragem em JavaScript","enunciado":"Escreva `posFiltragem(candidatos, passa, k)` que devolve `{devolvidos, faltaram}`: os até `k` primeiros candidatos (array de ids, já em ordem de distância) cujo `passa[id]` é verdadeiro, e quantos faltaram para `k`.","esqueleto":"function posFiltragem(candidatos, passa, k) {\n  // ...\n}\n","exports":["posFiltragem"],"testes":[{"nome":"completa","codigo":"(() => { const r = posFiltragem([\"a\", \"b\", \"c\"], {a: true, b: true, c: true}, 2); return iguais(r.devolvidos, [\"a\", \"b\"]) && r.faltaram === 0; })()"},{"nome":"rouba resultados","codigo":"(() => { const r = posFiltragem([\"a\", \"b\", \"c\"], {a: false, b: true, c: false}, 3); return iguais(r.devolvidos, [\"b\"]) && r.faltaram === 2; })()"},{"nome":"ninguém passa","codigo":"posFiltragem([\"a\"], {a: false}, 1).faltaram === 1"}],"solucao":"```js\nfunction posFiltragem(candidatos, passa, k) {\n  const devolvidos = candidatos.filter((c) => passa[c]).slice(0, k);\n  return { devolvidos, faltaram: k - devolvidos.length };\n}\n```","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-08"},{"cap":7,"tipo":"dados","nivel":1,"tempo":6,"titulo":"relaxed_order ou strict_order","enunciado":"Para cada situação, escreva `situacao: modo` com `relaxed_order` ou `strict_order`. Situações: `a busca hibrida vai reordenar tudo por RRF`, `a ordem exata por distancia importa no resultado final`, `prioridade e latencia`, `o projeto`.","modo":"conjunto","esperado":"a busca hibrida vai reordenar tudo por RRF: relaxed_order\na ordem exata por distancia importa no resultado final: strict_order\nprioridade e latencia: relaxed_order\no projeto: relaxed_order","solucao":"Na varredura iterativa, o índice pode achar numa rodada posterior uma linha mais próxima que outra já devolvida. `strict_order` segura os resultados para garantir a ordem por distância, e custa mais; `relaxed_order` entrega na ordem em que encontra. Como a busca híbrida reordena tudo por RRF (página 4), a ordem exata não importa: se algo vai reordenar depois, relaxe a ordem agora.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-09"},{"cap":7,"tipo":"python","nivel":2,"tempo":10,"titulo":"O teto da varredura iterativa","enunciado":"A varredura iterativa não expande para sempre: para em `hnsw.max_scan_tuples` (padrão 20.000). Escreva `iterativa(seletividade, k, max_scan=20_000)` que devolve `(linhas_esperadas, bateu_teto)`: quantas linhas se espera obter examinando até `max_scan` candidatos (no máximo `k`), e se o teto foi atingido antes de completar `k`.","esqueleto":"import math\n\ndef iterativa(seletividade, k, max_scan=20_000):\n    ...\n","testes":[{"nome":"filtro comum completa fácil","codigo":"assert iterativa(0.9, 12) == (12, False)"},{"nome":"filtro seletivo ainda completa","codigo":"assert iterativa(0.01, 12) == (12, False)"},{"nome":"filtro raríssimo bate o teto","codigo":"assert iterativa(0.0001, 12) == (2, True)"},{"nome":"nada passa","codigo":"assert iterativa(0.0, 12) == (0, True)"}],"solucao":"```python\nimport math\n\ndef iterativa(seletividade, k, max_scan=20_000):\n    alcance = int(max_scan * seletividade)\n    if alcance >= k:\n        return (k, False)\n    return (alcance, True)\n```\nCom 0,01% passando, 20.000 candidatos rendem só 2 linhas: o teto existe para a consulta não virar uma varredura completa disfarçada. Quando ele é atingido de verdade, a resposta certa é índice parcial ou pré-filtragem exata, não subir o teto.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-10"},{"cap":7,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"Quando a exata pré-filtrada ganha","enunciado":"Base de 30.000 linhas. Um filtro deixa passar 2%. A busca exata custa cerca de 0,8 µs por linha examinada; o HNSW com varredura iterativa examinou 9.000 candidatos a 0,5 µs cada.","campos":[{"label":"linhas que passam no filtro","valor":600,"tol":1},{"label":"tempo da exata sobre as linhas filtradas (ms)","valor":0.48,"tol":0.02},{"label":"tempo da varredura iterativa (ms)","valor":4.5,"tol":0.1}],"solucao":"600 linhas passam; percorrê-las custa 0,48 ms com recall 100%. A varredura iterativa gastou 4,5 ms para ter recall aproximado. Com filtro muito seletivo, o índice atrapalha: o certo é forçar a pré-filtragem (uma CTE materializada ou `enable_indexscan = off` naquela consulta).","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-11"},{"cap":7,"tipo":"texto","nivel":1,"tempo":5,"titulo":"O filtro por modelo também rouba?","enunciado":"Em 3 linhas: por que o filtro `modelo_embedding = …` não causa o problema de pós-filtragem no dia a dia, e quando ele passaria a causar.","rubrica":["Na prática todas as linhas passam: a coluna existe como trava e o índice só tem um modelo","Filtro que todo mundo passa não tira candidatos, então não rouba resultados","Passaria a causar durante uma migração com dois modelos na mesma tabela — e aí a solução é índice parcial por modelo, ou tabelas separadas"],"solucao":"Porque, em operação normal, 100% das linhas passam: a coluna é uma trava contra índices misturados, e o índice contém vetores de um modelo só. Um filtro que ninguém reprova não remove candidato nenhum. A situação muda numa migração, quando a tabela guarda vetores de dois modelos ao mesmo tempo: aí o filtro corta metade dos candidatos, e a solução é separar fisicamente — índice parcial por modelo ou tabelas distintas.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-12"},{"cap":7,"tipo":"python","nivel":3,"tempo":15,"titulo":"Diagnosticar pelo EXPLAIN","enunciado":"Escreva `diagnosticar(plano)` que recebe `{\"indice\": nome ou None, \"linhas\": int, \"limit\": int, \"read\": int}` e devolve a lista ordenada de diagnósticos: `\"indice ignorado\"` se `indice` for `None`; `\"pos-filtragem\"` se `linhas < limit` **e** o índice foi usado; `\"indice frio\"` se `read > 0`. Lista vazia significa consulta saudável.","esqueleto":"def diagnosticar(plano):\n    ...\n","testes":[{"nome":"saudável","codigo":"assert diagnosticar({\"indice\": \"trecho_emb_hnsw\", \"linhas\": 12, \"limit\": 12, \"read\": 0}) == []"},{"nome":"pós-filtragem","codigo":"assert diagnosticar({\"indice\": \"trecho_emb_hnsw\", \"linhas\": 3, \"limit\": 12, \"read\": 0}) == [\"pos-filtragem\"]"},{"nome":"sem índice não é pós-filtragem","codigo":"assert diagnosticar({\"indice\": None, \"linhas\": 3, \"limit\": 12, \"read\": 0}) == [\"indice ignorado\"]"},{"nome":"frio e pós-filtrado","codigo":"assert diagnosticar({\"indice\": \"x\", \"linhas\": 2, \"limit\": 12, \"read\": 4200}) == [\"indice frio\", \"pos-filtragem\"]"}],"solucao":"```python\ndef diagnosticar(plano):\n    fora = []\n    if plano[\"indice\"] is None:\n        fora.append(\"indice ignorado\")\n    elif plano[\"linhas\"] < plano[\"limit\"]:\n        fora.append(\"pos-filtragem\")\n    if plano[\"read\"] > 0:\n        fora.append(\"indice frio\")\n    return sorted(fora)\n```\nO `elif` é o ponto do exercício: sem índice, a varredura é exata e devolver menos linhas que o `LIMIT` significa apenas que não havia mais linhas — não é pós-filtragem. O diagnóstico depende de qual plano rodou.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-13"},{"cap":7,"tipo":"dados","nivel":2,"tempo":6,"titulo":"Solução por caso","enunciado":"Para cada caso, escreva `caso: solucao` com uma de `ef_search`, `iterative_scan`, `indice parcial`, `exata pre-filtrada`. Casos: `vigencia na data do documento, base variada`, `filtro fixo vigencia_fim IS NULL`, `filtro que deixa 300 linhas de 30 mil`, `filtro que passa 85% das linhas`.","modo":"conjunto","esperado":"vigencia na data do documento, base variada: iterative_scan\nfiltro fixo vigencia_fim IS NULL: indice parcial\nfiltro que deixa 300 linhas de 30 mil: exata pre-filtrada\nfiltro que passa 85% das linhas: ef_search","solucao":"Filtro variável e moderadamente seletivo: varredura iterativa (o caso do projeto). Filtro sempre igual: índice parcial. Filtro que deixa poucas centenas: exata pré-filtrada, mais rápida e com recall 100%. Filtro frouxo: nem precisa de solução, `ef_search` já cobre.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-14"},{"cap":7,"tipo":"projeto","nivel":2,"tempo":25,"titulo":"O filtro que rouba, medido","enunciado":"No experimento \"O filtro que rouba resultados\", com filtro em 10% e `ef_search = 40`, rode as 60 consultas no modo padrão e anote quantas linhas voltam em média (o pedido é 12). Suba o `ef_search` até voltar 12 e anote o custo em distâncias. Depois troque para varredura iterativa com `ef_search = 40`. Por fim, filtro em 2% no modo exato.","entrega":"Tabela (modo, filtro, ef_search) × (linhas devolvidas, distâncias) com as quatro rodadas e a conclusão.","rubrica":["Rodei o modo padrão e vi menos de 12 linhas voltarem","Descobri o ef_search necessário para completar 12 e anotei o custo","Vi a varredura iterativa completar 12 com ef_search 40 e custo intermediário","Com filtro em 2%, vi a exata pré-filtrada ganhar em linhas e em custo"],"solucao":"O padrão: com 10% passando e `ef_search = 40`, voltam cerca de 4 linhas das 12 pedidas; para completar 12 o `ef_search` precisa ir a ~120, triplicando as distâncias. A varredura iterativa entrega as 12 partindo de `ef_search = 40` com custo intermediário, porque só expande o quanto precisa. Com o filtro em 2%, sobram tão poucas linhas que percorrê-las todas é mais barato que navegar no grafo — e ainda dá recall 100%.","ligacoes":["03-busca-vetorial.html#c7"],"id":"p3-c7-15"},{"cap":8,"tipo":"python","nivel":2,"tempo":12,"titulo":"Os percentis da latência","enunciado":"Escreva `percentil(valores, p)` que devolve o percentil `p` (0 a 100) de uma lista, pelo método do índice mais próximo: ordene, calcule `i = ceil(p/100 * n) - 1`, limite ao intervalo válido. E `resumo(latencias)` que devolve `{\"p50\": …, \"p95\": …, \"max\": …}`.","esqueleto":"import math\n\ndef percentil(valores, p):\n    ...\n\ndef resumo(latencias):\n    ...\n","testes":[{"nome":"mediana","codigo":"assert percentil([1, 2, 3, 4, 5], 50) == 3"},{"nome":"p95 de vinte valores","codigo":"assert percentil(list(range(1, 21)), 95) == 19"},{"nome":"extremos","codigo":"assert percentil([5, 1, 3], 0) == 1 and percentil([5, 1, 3], 100) == 5"},{"nome":"resumo","codigo":"assert resumo([2.0, 2.1, 2.2, 9.0]) == {\"p50\": 2.1, \"p95\": 9.0, \"max\": 9.0}"}],"solucao":"```python\nimport math\n\ndef percentil(valores, p):\n    ordenados = sorted(valores)\n    i = math.ceil(p / 100 * len(ordenados)) - 1\n    return ordenados[min(max(i, 0), len(ordenados) - 1)]\n\ndef resumo(latencias):\n    return {\"p50\": percentil(latencias, 50), \"p95\": percentil(latencias, 95), \"max\": max(latencias)}\n```\nLatência se reporta em percentis, não em média: um p50 de 2 ms com p95 de 9 ms conta uma história que a média de 3,8 ms esconde.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-01"},{"cap":8,"tipo":"python","nivel":3,"tempo":20,"titulo":"O protocolo de medição","enunciado":"Escreva `medir(consultas, exata, aproximada, k)` onde `exata(qv, k)` e `aproximada(qv, k)` devolvem `(ids, ms)`. Devolva `{\"recall\": média dos recalls, \"p50_idx\": …, \"p95_idx\": …, \"p50_exata\": …}`, com os recalls calculados como a fração dos ids exatos presentes nos aproximados e os percentis pelo método do índice mais próximo. Arredonde o recall a 3 casas.","esqueleto":"import math\n\ndef percentil(valores, p):\n    ordenados = sorted(valores)\n    i = math.ceil(p / 100 * len(ordenados)) - 1\n    return ordenados[min(max(i, 0), len(ordenados) - 1)]\n\ndef medir(consultas, exata, aproximada, k):\n    ...\n","setup":"import math\n\ndef percentil(valores, p):\n    ordenados = sorted(valores)\n    i = math.ceil(p / 100 * len(ordenados)) - 1\n    return ordenados[min(max(i, 0), len(ordenados) - 1)]\n","testes":[{"nome":"índice perfeito","codigo":"ex = lambda q, k: ([\"a\", \"b\"], 10.0)\nap = lambda q, k: ([\"a\", \"b\"], 2.0)\nr = medir([1, 2, 3], ex, ap, 2)\nassert r[\"recall\"] == 1.0 and r[\"p50_idx\"] == 2.0 and r[\"p50_exata\"] == 10.0"},{"nome":"índice perde metade","codigo":"ex = lambda q, k: ([\"a\", \"b\"], 10.0)\nap = lambda q, k: ([\"a\", \"z\"], 2.0)\nassert medir([1], ex, ap, 2)[\"recall\"] == 0.5"},{"nome":"percentis diferentes","codigo":"tempos = iter([1.0, 2.0, 3.0, 50.0])\nex = lambda q, k: ([\"a\"], 9.0)\nap = lambda q, k: ([\"a\"], next(tempos))\nr = medir([1, 2, 3, 4], ex, ap, 1)\nassert r[\"p50_idx\"] == 2.0 and r[\"p95_idx\"] == 50.0"}],"solucao":"```python\ndef medir(consultas, exata, aproximada, k):\n    recalls, t_idx, t_ex = [], [], []\n    for qv in consultas:\n        ids_ex, ms_ex = exata(qv, k)\n        ids_ap, ms_ap = aproximada(qv, k)\n        recalls.append(len(set(ids_ex) & set(ids_ap)) / len(ids_ex) if ids_ex else 0.0)\n        t_ex.append(ms_ex); t_idx.append(ms_ap)\n    return {\n        \"recall\": round(sum(recalls) / len(recalls), 3),\n        \"p50_idx\": percentil(t_idx, 50), \"p95_idx\": percentil(t_idx, 95),\n        \"p50_exata\": percentil(t_ex, 50),\n    }\n```\nÉ o `medir_indice.py` do capítulo, sem o banco. Injetar as duas funções é o que permite testá-lo: em produção, `exata` roda com `SET LOCAL enable_indexscan = off` e `aproximada` com o índice ligado.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-02"},{"cap":8,"tipo":"python","nivel":2,"tempo":12,"titulo":"A calculadora de memória","enunciado":"Escreva `tamanho(n, dims, tipo=\"vector\", m=16)` que devolve `{\"vetores\": bytes, \"ligacoes\": bytes, \"total\": bytes}`: os vetores ocupam `n * dims * (4 se vector, 2 se halfvec)`; as ligações, `n * 2 * m * 4` bytes (só a camada 0, que domina). Total é a soma.","esqueleto":"def tamanho(n, dims, tipo=\"vector\", m=16):\n    ...\n","testes":[{"nome":"base do projeto","codigo":"assert tamanho(30_000, 768) == {\"vetores\": 92_160_000, \"ligacoes\": 3_840_000, \"total\": 96_000_000}"},{"nome":"halfvec corta os vetores","codigo":"r = tamanho(30_000, 768, \"halfvec\")\nassert r[\"vetores\"] == 46_080_000 and r[\"ligacoes\"] == 3_840_000"},{"nome":"m dobra as ligações","codigo":"assert tamanho(1000, 768, \"vector\", 32)[\"ligacoes\"] == 256_000"}],"solucao":"```python\ndef tamanho(n, dims, tipo=\"vector\", m=16):\n    vetores = n * dims * (2 if tipo == \"halfvec\" else 4)\n    ligacoes = n * 2 * m * 4\n    return {\"vetores\": vetores, \"ligacoes\": ligacoes, \"total\": vetores + ligacoes}\n```\nO segundo teste é a lição: `halfvec` corta os vetores pela metade e **não toca nas ligações**. É uma estimativa de ordem de grandeza; o número real vem de `pg_relation_size`.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-03"},{"cap":8,"tipo":"calculo","nivel":2,"tempo":8,"titulo":"Dois cenários de infraestrutura","enunciado":"Vetores de 768 dimensões em `vector` (4 bytes por dimensão), HNSW com `m = 16` (ligações: 2·m por linha, 4 bytes cada).","campos":[{"label":"MB totais com 30 mil linhas (1 MB = 10⁶ bytes)","valor":96,"tol":1},{"label":"GB totais com 3 milhões de linhas","valor":9.6,"tol":0.1},{"label":"GB de vetores com 3 milhões em halfvec","valor":4.6,"tol":0.1}],"solucao":"30 mil linhas: 92 MB de vetores + 4 MB de ligações = 96 MB — cabe em qualquer instância. 3 milhões: 9,2 GB + 0,4 GB = 9,6 GB, e agora existe uma decisão de infraestrutura, porque o índice precisa caber na memória para as consultas não irem ao disco. Em `halfvec`, os vetores caem para 4,6 GB e as ligações continuam 0,4 GB.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-04"},{"cap":8,"tipo":"sql","nivel":2,"tempo":8,"titulo":"Forçar a busca exata","enunciado":"Escreva o bloco que mede a busca exata dentro de uma transação: desliga o uso de índice **só naquela transação** (`enable_indexscan`), roda o `EXPLAIN (ANALYZE, BUFFERS)` da consulta com `LIMIT 12`, e no fim consulta o tamanho do índice `trecho_emb_hnsw` com `pg_size_pretty(pg_relation_size(...))`.","esqueleto":"BEGIN;\n...\nCOMMIT;\n","checks":[{"re":"SET LOCAL\\s+enable_indexscan\\s*=\\s*off","msg":"desliga o índice só na transação"},{"re":"EXPLAIN\\s*\\(\\s*ANALYZE\\s*,\\s*BUFFERS\\s*\\)","msg":"EXPLAIN com ANALYZE e BUFFERS"},{"re":"LIMIT\\s+12","msg":"consulta com LIMIT 12"},{"re":"pg_size_pretty\\s*\\(\\s*pg_relation_size\\s*\\(\\s*'trecho_emb_hnsw'","msg":"tamanho do índice"},{"re":"COMMIT\\s*;","msg":"fecha a transação"}],"solucao":"```sql\nBEGIN;\nSET LOCAL enable_indexscan = off;\nEXPLAIN (ANALYZE, BUFFERS)\nSELECT id FROM rag.trecho_normativo\nWHERE modelo_embedding = 'gemini-embedding-001'\nORDER BY embedding <=> '[…]'::vector\nLIMIT 12;\nCOMMIT;\n\nSELECT pg_size_pretty(pg_relation_size('trecho_emb_hnsw'));\n```\n`SET LOCAL` garante que a próxima transação volta a usar o índice. É assim que o `medir_indice.py` obtém a lista de referência para calcular o recall.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-05"},{"cap":8,"tipo":"texto","nivel":1,"tempo":6,"titulo":"O protocolo em cinco passos","enunciado":"Escreva o protocolo de medição do índice em cinco passos e os três números que você reporta ao final.","rubrica":["1. Carregar os trechos e construir o índice com maintenance_work_mem suficiente","2. Para cada consulta do conjunto de avaliação, rodar a busca exata (enable_indexscan = off) e a aproximada","3. Registrar recall@k e os tempos das duas","4. Repetir para dois ou três valores de ef_search","5. Escolher o menor ef que atinge o recall alvo, e guardar o resultado com a data e a versão do índice","Os três números: recall do índice, latência (p50/p95) e tamanho do índice"],"solucao":"Carregar e construir o índice com `maintenance_work_mem` suficiente; para cada consulta do conjunto de avaliação, rodar a exata (`enable_indexscan = off`) e a aproximada; registrar recall@k e os tempos das duas; repetir para dois ou três valores de `ef_search`; escolher o menor `ef` que atinge o alvo. No fim se reportam três números: recall do índice, latência p50/p95 com o índice quente, e tamanho do índice — guardados com a data e a versão da base, para servirem de referência quando algo mudar.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-06"},{"cap":8,"tipo":"texto","nivel":2,"tempo":6,"titulo":"Consultas reais, não aleatórias","enunciado":"Em 3 linhas: por que medir o recall do índice com as perguntas do conjunto de avaliação, e não com vetores aleatórios.","rubrica":["O recall do índice depende de onde a consulta cai: regiões densas perdem mais vizinhos","Consultas reais caem onde os usuários perguntam, que é onde o recall importa","Vetores aleatórios medem o comportamento do índice numa região que ninguém consulta"],"solucao":"Porque recall de índice não é um número único: ele varia por região do espaço. Onde há muitos trechos quase empatados — os incisos de um mesmo artigo, por exemplo — o grafo perde mais vizinhos; em regiões vazias, quase nunca erra. Vetores aleatórios caem espalhados, inclusive onde ninguém pergunta, e produzem um número que não descreve o sistema. Meça onde o tráfego está.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-07"},{"cap":8,"tipo":"js","nivel":2,"tempo":8,"titulo":"Percentis em JavaScript","enunciado":"Escreva `percentil(valores, p)` (método do índice mais próximo: ordena, `i = ceil(p/100 * n) - 1`, limitado ao intervalo) e `resumo(latencias)` devolvendo `{p50, p95, max}`.","esqueleto":"function percentil(valores, p) {\n  // ...\n}\nfunction resumo(latencias) {\n  // ...\n}\n","exports":["percentil","resumo"],"testes":[{"nome":"mediana","codigo":"percentil([1, 2, 3, 4, 5], 50) === 3"},{"nome":"ordena antes","codigo":"percentil([5, 1, 3], 100) === 5 && percentil([5, 1, 3], 0) === 1"},{"nome":"resumo","codigo":"iguais(resumo([2.0, 2.1, 2.2, 9.0]), {p50: 2.1, p95: 9.0, max: 9.0})"}],"solucao":"```js\nfunction percentil(valores, p) {\n  const o = [...valores].sort((a, b) => a - b);\n  const i = Math.ceil(p / 100 * o.length) - 1;\n  return o[Math.min(Math.max(i, 0), o.length - 1)];\n}\nfunction resumo(latencias) {\n  return { p50: percentil(latencias, 50), p95: percentil(latencias, 95), max: Math.max(...latencias) };\n}\n```","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-08"},{"cap":8,"tipo":"texto","nivel":2,"tempo":6,"titulo":"Índice quente","enunciado":"Em 3 linhas: o que é um índice quente, por que a primeira consulta depois de reiniciar o banco é lenta, e onde isso aparece no `EXPLAIN`.","rubrica":["Índice quente: páginas no cache do PostgreSQL (shared_buffers) ou do sistema operacional, não no disco","A primeira consulta depois de reiniciar traz as páginas do disco; as seguintes são rápidas","No EXPLAIN aparece em `Buffers: shared read=` (disco) contra `shared hit=` (cache)","Latência de produção é a do índice em memória: dimensione a memória para o índice inteiro"],"solucao":"Índice quente é aquele cujas páginas já estão no cache do PostgreSQL ou do sistema operacional. A primeira consulta depois de um reinício paga a leitura do disco para trazê-las, e por isso se mede a partir da segunda execução. O `EXPLAIN (ANALYZE, BUFFERS)` mostra isso em `Buffers`: `shared hit` é o que veio da memória, `shared read` é o que veio do disco. `read` grande em toda consulta significa que o índice não cabe no cache — e a latência sobe uma ordem de grandeza.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-09"},{"cap":8,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"Cabe na memória?","enunciado":"Uma instância com 4 GB de `shared_buffers` guarda a tabela e o índice. A tabela com 3 milhões de linhas ocupa 9,2 GB de vetores e o índice HNSW, 0,4 GB de ligações.","campos":[{"label":"GB necessários para tudo caber na memória","valor":9.6,"tol":0.1},{"label":"GB que faltam com 4 GB disponíveis","valor":5.6,"tol":0.1},{"label":"GB necessários usando halfvec (vetores pela metade)","valor":5.0,"tol":0.1}],"solucao":"Faltam 5,6 GB: cada consulta vai buscar páginas no disco, e o `shared read` do `EXPLAIN` denuncia. Com `halfvec` o total cai para 5,0 GB — ainda acima dos 4 GB, mas perto o bastante para a decisão ser entre truncar dimensões (página 2) e aumentar a instância.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-10"},{"cap":8,"tipo":"python","nivel":2,"tempo":10,"titulo":"Escolher o ef pelo alvo e pelo teto de latência","enunciado":"Escreva `escolher(medicoes, recall_alvo, p95_maximo)` que recebe uma lista de `{\"ef\", \"recall\", \"p95\"}` e devolve o menor `ef` que atinge o recall alvo **sem** ultrapassar o teto de latência; `None` se nenhum servir.","esqueleto":"def escolher(medicoes, recall_alvo, p95_maximo):\n    ...\n","testes":[{"nome":"o menor que serve","codigo":"M = [{\"ef\": 40, \"recall\": 0.92, \"p95\": 3.0}, {\"ef\": 100, \"recall\": 0.96, \"p95\": 6.0}, {\"ef\": 200, \"recall\": 0.97, \"p95\": 14.0}]\nassert escolher(M, 0.95, 10.0) == 100"},{"nome":"latência barra o único que atinge","codigo":"M = [{\"ef\": 40, \"recall\": 0.92, \"p95\": 3.0}, {\"ef\": 200, \"recall\": 0.97, \"p95\": 14.0}]\nassert escolher(M, 0.95, 10.0) is None"},{"nome":"recall alto e rápido","codigo":"M = [{\"ef\": 40, \"recall\": 0.99, \"p95\": 2.0}]\nassert escolher(M, 0.95, 10.0) == 40"}],"solucao":"```python\ndef escolher(medicoes, recall_alvo, p95_maximo):\n    validos = [m[\"ef\"] for m in medicoes if m[\"recall\"] >= recall_alvo and m[\"p95\"] <= p95_maximo]\n    return min(validos) if validos else None\n```\nO segundo teste é o caso interessante: existe um `ef` que atinge o recall, e ele não serve porque estoura a latência. A resposta então não é \"aceitar o lento\", é reconstruir com `m` maior — mover o teto em vez de escorregar por baixo dele.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-11"},{"cap":8,"tipo":"dados","nivel":1,"tempo":5,"titulo":"Os três números do relatório","enunciado":"Escreva, uma por linha, os três números que se reportam ao medir um índice, usando exatamente estes rótulos: `recall do indice`, `latencia p50 e p95 com indice quente`, `tamanho do indice`.","modo":"conjunto","esperado":"recall do indice\nlatencia p50 e p95 com indice quente\ntamanho do indice","solucao":"Recall do índice (contra a busca exata, com as consultas de avaliação), latência em percentis com o índice quente, e tamanho do índice em disco. Os três são guardados com a data e a versão da base: quando a base crescer ou o modelo mudar, eles são o ponto de comparação.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-12"},{"cap":8,"tipo":"texto","nivel":1,"tempo":5,"titulo":"O aviso do maintenance_work_mem","enunciado":"Em 3 linhas: como você sabe que o `maintenance_work_mem` foi insuficiente na construção do índice, e o que fazer.","rubrica":["O pgvector emite uma notificação (\"hnsw graph no longer fits into maintenance_work_mem\") e a construção fica muito mais lenta","Definir SET maintenance_work_mem antes do CREATE INDEX, com o valor que a calculadora de tamanho indicar","Usar max_parallel_maintenance_workers para paralelizar a construção"],"solucao":"O pgvector avisa: aparece uma notificação dizendo que o grafo não cabe mais no `maintenance_work_mem`, e a construção despenca de velocidade porque passa a usar disco. A correção é definir `SET maintenance_work_mem = '2GB'` (ou o que a calculadora do capítulo indicar) antes do `CREATE INDEX`, e subir `max_parallel_maintenance_workers` para paralelizar. O aviso existe: leia os logs da construção em vez de esperar terminar.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-13"},{"cap":8,"tipo":"python","nivel":1,"tempo":8,"titulo":"Quente ou frio, pelos buffers","enunciado":"Escreva `taxa_de_cache(hit, read)` que devolve a fração das páginas servidas pela memória (`hit / (hit + read)`, ou `1.0` quando não houve leitura nenhuma) e `esta_frio(hit, read, minimo=0.99)` que devolve `True` quando essa fração fica abaixo do mínimo.","esqueleto":"def taxa_de_cache(hit, read):\n    ...\n\ndef esta_frio(hit, read, minimo=0.99):\n    ...\n","testes":[{"nome":"tudo em cache","codigo":"assert taxa_de_cache(143, 0) == 1.0 and esta_frio(143, 0) is False"},{"nome":"índice frio","codigo":"assert abs(taxa_de_cache(12, 4188) - 0.00285714) < 1e-6 and esta_frio(12, 4188) is True"},{"nome":"sem páginas","codigo":"assert taxa_de_cache(0, 0) == 1.0"},{"nome":"quase tudo em cache ainda acusa","codigo":"assert esta_frio(980, 20) is True and esta_frio(9990, 10, 0.99) is False"}],"solucao":"```python\ndef taxa_de_cache(hit, read):\n    total = hit + read\n    return 1.0 if total == 0 else hit / total\n\ndef esta_frio(hit, read, minimo=0.99):\n    return taxa_de_cache(hit, read) < minimo\n```\nÉ a leitura da linha `Buffers: shared hit=… read=…` do `EXPLAIN`. O limiar alto (99%) é proposital: em consulta vetorial, ir ao disco em 1% das páginas já dobra a latência.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-14"},{"cap":8,"tipo":"projeto","nivel":3,"tempo":60,"titulo":"Medir o índice do Ex. 3","enunciado":"Adapte o `medir_indice.py` do capítulo ao seu banco e rode com `ef_search` em 40, 100 e 200, usando as perguntas do seu conjunto de avaliação como consultas. Registre recall@12, p50 e p95 com índice e com busca exata, e o tamanho do índice.","entrega":"Tabela ef_search × (recall@12, p50, p95) mais o tamanho do índice e a data da medição.","rubrica":["Usei as perguntas do conjunto de avaliação, embutidas com RETRIEVAL_QUERY","Rodei exata e aproximada na mesma transação, com SET LOCAL","Descartei a primeira execução (índice frio) antes de medir latência","Escolhi o menor ef_search que atinge o alvo e registrei o resultado com a data e a versão da base"],"solucao":"Com a base do guia (poucos milhares de trechos), o esperado é recall alto já em `ef_search = 40` e uma diferença pequena de latência para a exata — porque a base ainda é pequena, exatamente como o capítulo 9 prevê. O valor do exercício não é o número, é o script: ele é o que vai ser rodado de novo a cada reindexação, e a comparação entre datas é o que revela degradação.","ligacoes":["03-busca-vetorial.html#c8"],"id":"p3-c8-15"},{"cap":9,"tipo":"python","nivel":3,"tempo":12,"titulo":"O ajudante de decisão","enunciado":"Escreva `decidir(linhas, qps, atualizacoes, filtros_seletivos)` que devolve `{\"indice\": …, \"ef_search\": …, \"iterative_scan\": bool}`. Regras da página: menos de 20.000 linhas → `\"nenhum\"` (varredura exata), `ef_search` `None`; caso contrário `\"hnsw\"` com `ef_search` 100, ou 200 se `qps >= 100`. `iterative_scan` é `True` quando há filtros seletivos e existe índice. Se `atualizacoes == \"raras\"` e as linhas passarem de 1 milhão, o índice ainda é `\"hnsw\"` — o IVFFlat só entra se `atualizacoes == \"raras\"` **e** `memoria_limitada` for passado como `True` (quarto caso, parâmetro opcional).","esqueleto":"def decidir(linhas, qps, atualizacoes, filtros_seletivos, memoria_limitada=False):\n    ...\n","testes":[{"nome":"base pequena não indexa","codigo":"assert decidir(5_000, 1, \"raras\", True) == {\"indice\": \"nenhum\", \"ef_search\": None, \"iterative_scan\": False}"},{"nome":"o projeto hoje","codigo":"assert decidir(30_000, 1, \"raras\", True) == {\"indice\": \"hnsw\", \"ef_search\": 100, \"iterative_scan\": True}"},{"nome":"muito tráfego","codigo":"assert decidir(3_000_000, 100, \"raras\", False) == {\"indice\": \"hnsw\", \"ef_search\": 200, \"iterative_scan\": False}"},{"nome":"memória apertada e base estável","codigo":"assert decidir(3_000_000, 10, \"raras\", False, True)[\"indice\"] == \"ivfflat\""},{"nome":"atualizações frequentes descartam o ivfflat","codigo":"assert decidir(3_000_000, 10, \"frequentes\", False, True)[\"indice\"] == \"hnsw\""}],"solucao":"```python\ndef decidir(linhas, qps, atualizacoes, filtros_seletivos, memoria_limitada=False):\n    if linhas < 20_000:\n        return {\"indice\": \"nenhum\", \"ef_search\": None, \"iterative_scan\": False}\n    indice = \"ivfflat\" if (memoria_limitada and atualizacoes == \"raras\") else \"hnsw\"\n    return {\n        \"indice\": indice,\n        \"ef_search\": 200 if qps >= 100 else 100,\n        \"iterative_scan\": bool(filtros_seletivos),\n    }\n```\nO primeiro teste é a regra que mais se esquece: com 5 mil linhas, o índice certo é nenhum. Criar um \"porque é o certo\" adiciona memória, construção e recall abaixo de 100% sem ganho nenhum.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-01"},{"cap":9,"tipo":"sql","nivel":2,"tempo":10,"titulo":"Construir sem travar a tabela","enunciado":"Escreva a sequência de manutenção: definir `maintenance_work_mem = '2GB'`, criar o índice `trecho_emb_hnsw` com `CREATE INDEX CONCURRENTLY` (hnsw, `vector_cosine_ops`, `m = 16`, `ef_construction = 64`) e rodar o `ANALYZE` da tabela.","esqueleto":"SET ...\n","checks":[{"re":"SET\\s+maintenance_work_mem\\s*=\\s*'2GB'","msg":"define maintenance_work_mem = '2GB'"},{"re":"CREATE INDEX CONCURRENTLY\\s+trecho_emb_hnsw","msg":"CREATE INDEX CONCURRENTLY"},{"re":"USING\\s+hnsw\\s*\\(\\s*embedding\\s+vector_cosine_ops\\s*\\)","msg":"hnsw com a classe de cosseno"},{"re":"m\\s*=\\s*16[^)]*ef_construction\\s*=\\s*64","flags":"is","msg":"os dois parâmetros"},{"re":"ANALYZE\\s+rag\\.trecho_normativo","msg":"ANALYZE depois de construir"}],"solucao":"```sql\nSET maintenance_work_mem = '2GB';\n\nCREATE INDEX CONCURRENTLY trecho_emb_hnsw ON rag.trecho_normativo\n  USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);\n\nANALYZE rag.trecho_normativo;\n```\nO `CONCURRENTLY` é mais lento e não bloqueia inserções nem consultas: é o certo para reconstruir em produção. E o `ANALYZE` não é opcional — sem estatísticas atualizadas, o planejador pode preferir a varredura mesmo com o índice pronto.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-02"},{"cap":9,"tipo":"texto","nivel":1,"tempo":6,"titulo":"Quando não indexar","enunciado":"Em 3 linhas: por que uma tabela de 8 mil dispositivos, com a busca exata respondendo em 3 ms, não deve receber um índice.","rubrica":["A varredura exata nessa escala é rápida, tem recall 100% e não exige manutenção nenhuma","O índice custaria memória, tempo de construção e um recall abaixo de 100%, sem ganho de latência perceptível","A regra: medir a exata e indexar quando a latência exigir — não \"porque é o certo\""],"solucao":"Porque não há problema a resolver. Em 8 mil linhas a varredura responde em 3 ms, com recall 100% por definição e zero manutenção. Um HNSW ali cobraria memória, tempo de construção, `VACUUM`/`REINDEX` no futuro e um recall que já não seria 1,0 — tudo isso para economizar uma fração de milissegundo que ninguém percebe. A regra é medir a exata e indexar quando a latência exigir.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-03"},{"cap":9,"tipo":"python","nivel":2,"tempo":10,"titulo":"A rotina de manutenção","enunciado":"Escreva `acao(evento)` que devolve a operação de índice para cada evento da rotina do projeto: `\"norma nova\"` → `\"inserir\"`; `\"troca de modelo\"` → `\"reindexar tudo\"`; `\"correcao de texto de um dispositivo\"` → `\"remover e inserir\"`; `\"muitas remocoes acumuladas\"` → `\"reindex\"`; qualquer outro → `\"nada\"`.","esqueleto":"def acao(evento):\n    ...\n","testes":[{"nome":"os quatro eventos","codigo":"assert [acao(e) for e in [\"norma nova\", \"troca de modelo\", \"correcao de texto de um dispositivo\", \"muitas remocoes acumuladas\"]] == [\"inserir\", \"reindexar tudo\", \"remover e inserir\", \"reindex\"]"},{"nome":"evento desconhecido","codigo":"assert acao(\"deploy da aplicacao\") == \"nada\""}],"solucao":"```python\nROTINA = {\n    \"norma nova\": \"inserir\",\n    \"troca de modelo\": \"reindexar tudo\",\n    \"correcao de texto de um dispositivo\": \"remover e inserir\",\n    \"muitas remocoes acumuladas\": \"reindex\",\n}\n\ndef acao(evento):\n    return ROTINA.get(evento, \"nada\")\n```\nO terceiro caso é o que costuma confundir: \"atualizar o vetor de uma linha\" não existe como operação de HNSW — é uma remoção mais uma inserção, e é por isso que remoções frequentes degradam o grafo.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-04"},{"cap":9,"tipo":"texto","nivel":3,"tempo":8,"titulo":"Migrar de modelo sem misturar","enunciado":"Em até 5 linhas: como migrar de modelo de embedding sem misturar vetores incompatíveis no mesmo índice.","rubrica":["Não misturar na mesma coluna: uma coluna por modelo (com índice por coluna ou índice parcial) ou uma tabela por modelo","Reindexar tudo com o modelo novo: espaços diferentes são incompatíveis, não existe \"só os novos\"","Manter os dois índices até validar o novo (recall medido no conjunto de avaliação)","A trava WHERE modelo_embedding = … continua na consulta, mas a separação física é o que impede o índice de ver vetores incompatíveis"],"solucao":"A regra é separação física: coluna nova (ou tabela nova) para o modelo novo, com índice próprio. Reindexa-se tudo, porque os espaços de dois modelos não são comparáveis e não existe migração incremental. Os dois convivem até o novo ser validado pelo recall no conjunto de avaliação, e só então o antigo é derrubado. A trava `WHERE modelo_embedding = …` continua na consulta como rede de segurança, mas ela não basta sozinha: sem separar fisicamente, o índice enxerga os dois espaços e os rankings perdem sentido.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-05"},{"cap":9,"tipo":"dados","nivel":1,"tempo":6,"titulo":"Antes ou depois dos dados","enunciado":"Para cada índice, escreva `indice: quando` com `antes ou depois` ou `so depois`, indicando quando ele pode ser criado em relação à carga dos dados. Índices: `hnsw`, `ivfflat`. Acrescente duas linhas com o motivo, no formato `motivo hnsw: ...` e `motivo ivfflat: ...`, usando exatamente `aceita insercoes incrementais` e `centroides vem de k-means sobre os dados`.","modo":"conjunto","esperado":"hnsw: antes ou depois\nivfflat: so depois\nmotivo hnsw: aceita insercoes incrementais\nmotivo ivfflat: centroides vem de k-means sobre os dados","solucao":"O HNSW pode ser criado com a tabela vazia (as inserções constroem o grafo), embora seja mais rápido carregar primeiro e indexar depois. O IVFFlat **precisa** dos dados: sem eles não há k-means, e um índice criado antes fica com centroides inúteis.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-06"},{"cap":9,"tipo":"python","nivel":2,"tempo":10,"titulo":"Quando reindexar o IVFFlat","enunciado":"Escreva `precisa_reindex(linhas_no_build, linhas_agora, desequilibrio, limite_crescimento=1.5, limite_desequilibrio=3.0)` que devolve a lista ordenada de motivos: `\"cresceu demais\"` se a base passou do limite de crescimento em relação ao build, e `\"listas desequilibradas\"` se o desequilíbrio passou do limite. Lista vazia = tudo bem.","esqueleto":"def precisa_reindex(linhas_no_build, linhas_agora, desequilibrio, limite_crescimento=1.5, limite_desequilibrio=3.0):\n    ...\n","testes":[{"nome":"tudo bem","codigo":"assert precisa_reindex(10_000, 12_000, 1.4) == []"},{"nome":"cresceu","codigo":"assert precisa_reindex(10_000, 20_000, 1.4) == [\"cresceu demais\"]"},{"nome":"desequilibrado","codigo":"assert precisa_reindex(10_000, 11_000, 5.0) == [\"listas desequilibradas\"]"},{"nome":"os dois","codigo":"assert precisa_reindex(10_000, 30_000, 9.0) == [\"cresceu demais\", \"listas desequilibradas\"]"},{"nome":"no limite não acusa","codigo":"assert precisa_reindex(10_000, 15_000, 3.0) == []"}],"solucao":"```python\ndef precisa_reindex(linhas_no_build, linhas_agora, desequilibrio, limite_crescimento=1.5, limite_desequilibrio=3.0):\n    motivos = []\n    if linhas_agora > linhas_no_build * limite_crescimento:\n        motivos.append(\"cresceu demais\")\n    if desequilibrio > limite_desequilibrio:\n        motivos.append(\"listas desequilibradas\")\n    return sorted(motivos)\n```\nÉ a manutenção que o IVFFlat exige e o HNSW não: os centroides envelhecem, e as duas métricas — crescimento e desequilíbrio — dizem quando refazer o k-means.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-07"},{"cap":9,"tipo":"texto","nivel":1,"tempo":5,"titulo":"Por que ANALYZE depois de construir","enunciado":"Em 3 linhas: por que rodar `ANALYZE` depois de criar o índice.","rubrica":["ANALYZE atualiza as estatísticas que o planejador usa para escolher entre índice e varredura","Também alimenta a estimativa de seletividade dos filtros do WHERE","Sem estatísticas atualizadas o planejador pode ignorar o índice mesmo com ele pronto"],"solucao":"Porque o índice existir não basta: o planejador precisa acreditar que vale usá-lo, e essa decisão vem das estatísticas da tabela. Elas também alimentam a estimativa de quantas linhas o `WHERE` deixa passar, que é o que faz o planejador escolher entre pós-filtragem e outros caminhos. Sem `ANALYZE` depois de uma carga grande, é comum ver um índice novinho sendo ignorado.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-08"},{"cap":9,"tipo":"js","nivel":1,"tempo":8,"titulo":"O ajudante de decisão em JavaScript","enunciado":"Escreva `decidir({linhas, qps, filtrosSeletivos})` que devolve `{indice, efSearch, iterativeScan}`: menos de 20.000 linhas → `indice: \"nenhum\"`, `efSearch: null`, `iterativeScan: false`; senão `\"hnsw\"` com `efSearch` 200 se `qps >= 100`, 100 caso contrário, e `iterativeScan` igual a `filtrosSeletivos`.","esqueleto":"function decidir({ linhas, qps, filtrosSeletivos }) {\n  // ...\n}\n","exports":["decidir"],"testes":[{"nome":"base pequena","codigo":"iguais(decidir({linhas: 5000, qps: 1, filtrosSeletivos: true}), {indice: \"nenhum\", efSearch: null, iterativeScan: false})"},{"nome":"o projeto","codigo":"iguais(decidir({linhas: 30000, qps: 1, filtrosSeletivos: true}), {indice: \"hnsw\", efSearch: 100, iterativeScan: true})"},{"nome":"muito tráfego","codigo":"decidir({linhas: 3e6, qps: 100, filtrosSeletivos: false}).efSearch === 200"}],"solucao":"```js\nfunction decidir({ linhas, qps, filtrosSeletivos }) {\n  if (linhas < 20000) return { indice: \"nenhum\", efSearch: null, iterativeScan: false };\n  return { indice: \"hnsw\", efSearch: qps >= 100 ? 200 : 100, iterativeScan: !!filtrosSeletivos };\n}\n```","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-09"},{"cap":9,"tipo":"calculo","nivel":2,"tempo":6,"titulo":"A janela de reconstrução","enunciado":"Uma reconstrução completa de 3 milhões de vetores leva 25 minutos com a construção normal. O `CREATE INDEX CONCURRENTLY` costuma levar cerca de o dobro. O sistema atende 10 consultas por segundo.","campos":[{"label":"minutos com CREATE INDEX CONCURRENTLY","valor":50,"tol":2},{"label":"consultas atendidas durante a janela, com CONCURRENTLY","valor":30000,"rel":0.02},{"label":"consultas que seriam recusadas com a construção normal bloqueante (25 min)","valor":15000,"rel":0.02}],"solucao":"O `CONCURRENTLY` leva 50 minutos e atende as 30.000 consultas do período; a construção normal termina em 25 minutos, mas bloqueia escritas e derruba as 15.000 consultas da janela. É a troca do capítulo: concorrente custa tempo, bloquear custa disponibilidade.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-10"},{"cap":9,"tipo":"texto","nivel":2,"tempo":6,"titulo":"Particionar ajuda?","enunciado":"Em 3 linhas: quando particionar a tabela resolve o problema do filtro, e quando não resolve.","rubrica":["Resolve quando as consultas sempre filtram pela chave de partição (por modelo de embedding, por órgão): o filtro vira poda de partição, e cada partição tem um índice menor","Não resolve para filtros variados como vigência na data do documento","Partição resolve o filtro fixo; iterative_scan resolve o variável"],"solucao":"Particionar resolve quando o filtro é sempre o mesmo e coincide com a chave de partição — por modelo de embedding, por órgão. Aí o PostgreSQL nem olha as outras partições (poda de partição) e cada índice é menor e mais rápido. Não resolve para filtros variados como \"vigente na data do documento\", que atravessam todas as partições e voltam a exigir pós-filtragem. Partição para o filtro fixo, `iterative_scan` para o variável.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-11"},{"cap":9,"tipo":"dados","nivel":2,"tempo":6,"titulo":"A rotina do índice do projeto","enunciado":"Escreva a rotina de operação do índice do projeto, uma linha por evento, no formato `evento: acao`. Eventos: `carga inicial`, `entra norma nova`, `troca o modelo de embedding`, `muitas remocoes`. Ações permitidas: `carregar e depois CREATE INDEX`, `inserir (o grafo aceita)`, `nova coluna ou tabela e reindexar tudo`, `VACUUM e REINDEX`.","modo":"conjunto","esperado":"carga inicial: carregar e depois CREATE INDEX\nentra norma nova: inserir (o grafo aceita)\ntroca o modelo de embedding: nova coluna ou tabela e reindexar tudo\nmuitas remocoes: VACUUM e REINDEX","solucao":"Carga em massa primeiro, índice depois (mais rápido, com `maintenance_work_mem` generoso). Norma nova entra por inserção, que o HNSW absorve sem degradar. Troca de modelo é reindexação completa em espaço separado. E remoções acumuladas deixam versões mortas: `VACUUM` limpa, e o `REINDEX` recupera a qualidade do grafo quando a rotatividade foi alta.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-12"},{"cap":9,"tipo":"python","nivel":3,"tempo":15,"titulo":"O plano de manutenção","enunciado":"Escreva `plano(estado)` que recebe `{\"linhas\", \"linhas_no_build\", \"remocoes\", \"modelo_atual\", \"modelo_indice\", \"analyze_pendente\"}` e devolve a lista ordenada de ações necessárias: `\"analyze\"` se `analyze_pendente`; `\"reindex\"` se as remoções passarem de 20% das linhas; `\"reindexar tudo\"` se o modelo do índice for diferente do configurado; `\"nada\"` (lista com esse único item) se nenhuma se aplicar.","esqueleto":"def plano(estado):\n    ...\n","testes":[{"nome":"tudo em ordem","codigo":"E = {\"linhas\": 30_000, \"linhas_no_build\": 30_000, \"remocoes\": 100, \"modelo_atual\": \"m\", \"modelo_indice\": \"m\", \"analyze_pendente\": False}\nassert plano(E) == [\"nada\"]"},{"nome":"modelo divergente","codigo":"E = {\"linhas\": 30_000, \"linhas_no_build\": 30_000, \"remocoes\": 0, \"modelo_atual\": \"novo\", \"modelo_indice\": \"m\", \"analyze_pendente\": False}\nassert plano(E) == [\"reindexar tudo\"]"},{"nome":"remoções demais e analyze","codigo":"E = {\"linhas\": 10_000, \"linhas_no_build\": 10_000, \"remocoes\": 3_000, \"modelo_atual\": \"m\", \"modelo_indice\": \"m\", \"analyze_pendente\": True}\nassert plano(E) == [\"analyze\", \"reindex\"]"},{"nome":"no limite não acusa","codigo":"E = {\"linhas\": 10_000, \"linhas_no_build\": 10_000, \"remocoes\": 2_000, \"modelo_atual\": \"m\", \"modelo_indice\": \"m\", \"analyze_pendente\": False}\nassert plano(E) == [\"nada\"]"}],"solucao":"```python\ndef plano(estado):\n    acoes = []\n    if estado[\"analyze_pendente\"]:\n        acoes.append(\"analyze\")\n    if estado[\"remocoes\"] > 0.2 * estado[\"linhas\"]:\n        acoes.append(\"reindex\")\n    if estado[\"modelo_atual\"] != estado[\"modelo_indice\"]:\n        acoes.append(\"reindexar tudo\")\n    return sorted(acoes) if acoes else [\"nada\"]\n```\nÉ o que um job semanal verificaria. A ação mais grave, \"reindexar tudo\", é a única que não pode esperar: enquanto o modelo do índice diferir do configurado, a busca está comparando espaços incompatíveis.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-13"},{"cap":9,"tipo":"calculo","nivel":2,"tempo":8,"titulo":"Quando a base vai exigir o índice","enunciado":"A base curada tem 30.000 dispositivos e a varredura exata responde em 24 ms. O orçamento de latência da recuperação é 50 ms, e a base cresce cerca de 30% ao ano com a entrada de acórdãos e enunciados.","campos":[{"label":"linhas em que a varredura bate o orçamento","valor":62500,"rel":0.02},{"label":"linhas depois de dois anos de crescimento","valor":50700,"rel":0.02},{"label":"anos até a varredura estourar o orçamento (aproximado)","valor":2.8,"tol":0.15}],"solucao":"O orçamento se esgota em 62.500 linhas. Crescendo 30% ao ano, a base sai de 30.000 para 39.000 e 50.700 nos dois primeiros anos, e cruza o limite perto do terceiro (1,3ⁿ = 62.500/30.000 → n ≈ 2,8). É essa conta, e não o tamanho de hoje, que justifica criar o índice antes de precisar dele — construir com calma vale mais que construir sob pressão.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-14"},{"cap":9,"tipo":"projeto","nivel":2,"tempo":30,"titulo":"O ajudante de decisão, nos dois cenários","enunciado":"No experimento \"Ajudante de decisão\", descreva o projeto como ele é hoje (30 mil linhas, 1 consulta/s, atualizações raras, filtros de vigência, 768 dimensões) e leia a recomendação. Depois descreva o cenário \"toda a jurisprudência\" (3 milhões de linhas, 100 consultas/s) e leia de novo.","entrega":"As duas recomendações, o que mudou entre elas e o que permaneceu.","rubrica":["Rodei os dois cenários e anotei as recomendações completas","Identifiquei o que mudou (ef_search, exigência de memória, janela de reconstrução)","Identifiquei o que não mudou (HNSW com cosseno, iterative_scan por causa da vigência)","Relacionei com a calculadora de memória do capítulo 8"],"solucao":"O que muda com a escala: o `ef_search` sobe (mais tráfego, mais exigência de latência previsível), a memória deixa de ser detalhe e vira decisão de infraestrutura (9,6 GB contra 96 MB), e a reconstrução passa a exigir `CONCURRENTLY` numa janela planejada. O que não muda: HNSW com `vector_cosine_ops`, porque a base cresce e o filtro é variável, e o `iterative_scan` por causa da vigência. É útil ver que a arquitetura sobrevive a duas ordens de grandeza — o que muda são os números.","ligacoes":["03-busca-vetorial.html#c9"],"id":"p3-c9-15"},{"cap":10,"tipo":"sql","nivel":2,"tempo":12,"titulo":"Os índices do projeto","enunciado":"Escreva as três criações de índice da tabela `rag.trecho_normativo`, seguidas do `ANALYZE`: o HNSW `trecho_emb_hnsw` sobre `embedding` com `vector_cosine_ops`, `m = 16` e `ef_construction = 64`; o B-tree `trecho_vig_idx` sobre `(vigencia_inicio, vigencia_fim)`; e o B-tree `trecho_norma_idx` sobre `(norma)`.","esqueleto":"CREATE INDEX ...\n","checks":[{"re":"CREATE INDEX\\s+trecho_emb_hnsw[\\s\\S]*USING\\s+hnsw\\s*\\(\\s*embedding\\s+vector_cosine_ops\\s*\\)","msg":"HNSW de cosseno sobre embedding"},{"re":"m\\s*=\\s*16[^)]*ef_construction\\s*=\\s*64","flags":"is","msg":"m = 16 e ef_construction = 64"},{"re":"CREATE INDEX\\s+trecho_vig_idx\\s+ON\\s+rag\\.trecho_normativo\\s*\\(\\s*vigencia_inicio\\s*,\\s*vigencia_fim\\s*\\)","flags":"is","msg":"B-tree de vigência"},{"re":"CREATE INDEX\\s+trecho_norma_idx\\s+ON\\s+rag\\.trecho_normativo\\s*\\(\\s*norma\\s*\\)","flags":"is","msg":"B-tree de norma"},{"re":"ANALYZE\\s+rag\\.trecho_normativo","msg":"ANALYZE ao final"}],"solucao":"```sql\nCREATE INDEX trecho_emb_hnsw ON rag.trecho_normativo\n  USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);\nCREATE INDEX trecho_vig_idx ON rag.trecho_normativo (vigencia_inicio, vigencia_fim);\nCREATE INDEX trecho_norma_idx ON rag.trecho_normativo (norma);\nANALYZE rag.trecho_normativo;\n```\nO HNSW ordena por distância; os B-tree ajudam o planejador a estimar a seletividade dos filtros e a resolvê-los quando a consulta não é vetorial. Falta ainda o GIN sobre o `tsvector`, que a página 4 acrescenta.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-01"},{"cap":10,"tipo":"python","nivel":3,"tempo":20,"titulo":"A transação de busca completa","enunciado":"Escreva `buscar(cur, vetor, modelo, data, k=50, ef=100)` que executa, **nesta ordem**, no cursor: `SET LOCAL hnsw.ef_search = <ef>`, `SET LOCAL hnsw.iterative_scan = relaxed_order`, e a consulta com os parâmetros `(vetor, modelo, data, data, vetor, k)`; depois devolve a lista de ids de `cur.fetchall()`. A consulta precisa conter `ORDER BY embedding <=> %s::vector` e `LIMIT %s`. `CursorFalso` já está definido para o teste.","esqueleto":"class CursorFalso:\n    \"\"\"Imita um cursor do psycopg: registra os comandos e devolve linhas fixas.\"\"\"\n    def __init__(self, linhas=None):\n        self.comandos = []\n        self.linhas = linhas if linhas is not None else [(\"L14133-art75-incI\",), (\"L14133-art74\",)]\n        self._ultimo = []\n\n    def execute(self, sql, params=None):\n        self.comandos.append((\" \".join(sql.split()), params))\n        self._ultimo = [] if sql.strip().upper().startswith(\"SET\") else list(self.linhas)\n\n    def fetchall(self):\n        return self._ultimo\n\ndef buscar(cur, vetor, modelo, data, k=50, ef=100):\n    ...\n","setup":"class CursorFalso:\n    \"\"\"Imita um cursor do psycopg: registra os comandos e devolve linhas fixas.\"\"\"\n    def __init__(self, linhas=None):\n        self.comandos = []\n        self.linhas = linhas if linhas is not None else [(\"L14133-art75-incI\",), (\"L14133-art74\",)]\n        self._ultimo = []\n\n    def execute(self, sql, params=None):\n        self.comandos.append((\" \".join(sql.split()), params))\n        self._ultimo = [] if sql.strip().upper().startswith(\"SET\") else list(self.linhas)\n\n    def fetchall(self):\n        return self._ultimo\n","testes":[{"nome":"ordem dos comandos","codigo":"c = CursorFalso(); buscar(c, \"[0.1]\", \"gemini-embedding-001\", \"2021-04-01\")\nassert c.comandos[0][0] == \"SET LOCAL hnsw.ef_search = 100\"\nassert c.comandos[1][0] == \"SET LOCAL hnsw.iterative_scan = relaxed_order\"\nassert len(c.comandos) == 3"},{"nome":"a consulta tem a forma certa","codigo":"c = CursorFalso(); buscar(c, \"[0.1]\", \"m\", \"2021-04-01\")\nsql = c.comandos[2][0]\nassert \"ORDER BY embedding <=> %s::vector\" in sql and \"LIMIT %s\" in sql"},{"nome":"parâmetros na ordem","codigo":"c = CursorFalso(); buscar(c, \"[0.1]\", \"m\", \"2021-04-01\", k=12, ef=40)\nassert c.comandos[2][1] == (\"[0.1]\", \"m\", \"2021-04-01\", \"2021-04-01\", \"[0.1]\", 12)\nassert c.comandos[0][0] == \"SET LOCAL hnsw.ef_search = 40\""},{"nome":"devolve os ids","codigo":"c = CursorFalso([(\"a\",), (\"b\",), (\"c\",)])\nassert buscar(c, \"[0.1]\", \"m\", \"2021-04-01\") == [\"a\", \"b\", \"c\"]"}],"solucao":"```python\nSQL = \"\"\"SELECT id, dispositivo, 1 - (embedding <=> %s::vector) AS similaridade\nFROM rag.trecho_normativo\nWHERE modelo_embedding = %s\n  AND vigencia_inicio <= %s::date\n  AND (vigencia_fim IS NULL OR vigencia_fim > %s::date)\nORDER BY embedding <=> %s::vector\nLIMIT %s\"\"\"\n\ndef buscar(cur, vetor, modelo, data, k=50, ef=100):\n    cur.execute(f\"SET LOCAL hnsw.ef_search = {int(ef)}\")\n    cur.execute(\"SET LOCAL hnsw.iterative_scan = relaxed_order\")\n    cur.execute(SQL, (vetor, modelo, data, data, vetor, k))\n    return [linha[0] for linha in cur.fetchall()]\n```\nO `SET` não aceita parâmetros vinculados, daí o `int(ef)` na interpolação — que é seguro porque a conversão rejeita qualquer coisa que não seja número. Os dois `SET LOCAL` valem só para esta transação, o que importa quando há pool de conexões.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-02"},{"cap":10,"tipo":"texto","nivel":2,"tempo":8,"titulo":"A busca do projeto, de ponta a ponta","enunciado":"Descreva em até 6 linhas o caminho de uma pergunta até os 12 trechos que chegam ao prompt, citando `ef_search`, `iterative_scan`, o número de candidatos de cada lado, a fusão e o filtro.","rubrica":["A pergunta é embutida com RETRIEVAL_QUERY pelo mesmo modelo do índice (trava por modelo_embedding)","A transação define SET LOCAL hnsw.ef_search = 100 e hnsw.iterative_scan = relaxed_order","A busca vetorial pede 50 candidatos, filtrando por vigência na data do documento","A busca lexical pede outros 50 (página 4)","RRF funde as duas listas e os 12 primeiros vão ao prompt"],"solucao":"A pergunta é embutida com `RETRIEVAL_QUERY` pelo mesmo modelo que indexou os trechos. Abre-se a transação com `SET LOCAL hnsw.ef_search = 100` (acima dos 50 pedidos) e `hnsw.iterative_scan = relaxed_order`, para o filtro de vigência não roubar candidatos. A consulta vetorial traz 50 trechos vigentes na data do documento, ordenados pelo operador `<=>` puro. Em paralelo, a busca lexical traz outros 50 (página 4). O RRF funde as duas listas — e por isso a ordem exata da varredura iterativa não importa — e os 12 primeiros vão para o prompt.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-03"},{"cap":10,"tipo":"python","nivel":3,"tempo":12,"titulo":"A trava antes da consulta","enunciado":"Escreva `preparar(cfg, indice)` que valida antes de qualquer consulta e devolve a lista ordenada de comandos `SET LOCAL` a executar. Lance `ValueError` começando por `\"indice incompativel\"` se `cfg[\"modelo\"] != indice[\"modelo\"]` ou `cfg[\"dims\"] != indice[\"dims\"]`. Se `cfg[\"ef_search\"] < cfg[\"k\"]`, use `cfg[\"k\"] * 2` como `ef_search` em vez do valor configurado. Inclua o `iterative_scan` só quando `cfg[\"filtra_vigencia\"]` for verdadeiro.","esqueleto":"def preparar(cfg, indice):\n    ...\n","testes":[{"nome":"caso do projeto","codigo":"cfg = {\"modelo\": \"m\", \"dims\": 768, \"k\": 50, \"ef_search\": 100, \"filtra_vigencia\": True}\nassert preparar(cfg, {\"modelo\": \"m\", \"dims\": 768}) == [\"SET LOCAL hnsw.ef_search = 100\", \"SET LOCAL hnsw.iterative_scan = relaxed_order\"]"},{"nome":"sem filtro de vigência","codigo":"cfg = {\"modelo\": \"m\", \"dims\": 768, \"k\": 12, \"ef_search\": 100, \"filtra_vigencia\": False}\nassert preparar(cfg, {\"modelo\": \"m\", \"dims\": 768}) == [\"SET LOCAL hnsw.ef_search = 100\"]"},{"nome":"ef abaixo do k é corrigido","codigo":"cfg = {\"modelo\": \"m\", \"dims\": 768, \"k\": 50, \"ef_search\": 40, \"filtra_vigencia\": False}\nassert preparar(cfg, {\"modelo\": \"m\", \"dims\": 768}) == [\"SET LOCAL hnsw.ef_search = 100\"]"},{"nome":"modelo divergente","codigo":"cfg = {\"modelo\": \"novo\", \"dims\": 768, \"k\": 12, \"ef_search\": 100, \"filtra_vigencia\": True}\ntry:\n    preparar(cfg, {\"modelo\": \"m\", \"dims\": 768}); assert False\nexcept ValueError as e:\n    assert str(e).startswith(\"indice incompativel\")"}],"solucao":"```python\ndef preparar(cfg, indice):\n    if cfg[\"modelo\"] != indice[\"modelo\"] or cfg[\"dims\"] != indice[\"dims\"]:\n        raise ValueError(f\"indice incompativel: indice {indice}, config {cfg['modelo']}/{cfg['dims']}\")\n    ef = cfg[\"ef_search\"] if cfg[\"ef_search\"] >= cfg[\"k\"] else cfg[\"k\"] * 2\n    comandos = [f\"SET LOCAL hnsw.ef_search = {ef}\"]\n    if cfg[\"filtra_vigencia\"]:\n        comandos.append(\"SET LOCAL hnsw.iterative_scan = relaxed_order\")\n    return comandos\n```\nDuas travas em uma: a de modelo (página 2), que evita rankings sem sentido, e a de `ef_search` abaixo do `k`, que evita a consulta devolver menos linhas do que pediu.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-04"},{"cap":10,"tipo":"dados","nivel":1,"tempo":6,"titulo":"A configuração de busca do projeto","enunciado":"Escreva, uma por linha, os cinco valores da configuração de busca do projeto, no formato `parametro: valor`: `m`, `ef_construction`, `hnsw.ef_search`, `hnsw.iterative_scan`, `candidatos vetoriais`.","modo":"conjunto","esperado":"m: 16\nef_construction: 64\nhnsw.ef_search: 100\nhnsw.iterative_scan: relaxed_order\ncandidatos vetoriais: 50","solucao":"`m = 16` e `ef_construction = 64` no `CREATE INDEX`; `hnsw.ef_search = 100` e `hnsw.iterative_scan = relaxed_order` por transação; 50 candidatos vetoriais (mais 50 lexicais) antes da fusão RRF, que entrega 12 ao prompt.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-05"},{"cap":10,"tipo":"dados","nivel":1,"tempo":6,"titulo":"O docker compose do Ex. 3","enunciado":"Escreva o JSON do serviço `db` do `docker-compose` do capítulo, com as chaves `image` e `environment` (um objeto com `POSTGRES_USER`, `POSTGRES_PASSWORD` e `POSTGRES_DB`) e `ports` (lista com uma string).","modo":"json","esperado":"{\"image\": \"pgvector/pgvector:pg16\", \"environment\": {\"POSTGRES_USER\": \"rag\", \"POSTGRES_PASSWORD\": \"rag\", \"POSTGRES_DB\": \"rag\"}, \"ports\": [\"5432:5432\"]}","solucao":"```json\n{\"image\": \"pgvector/pgvector:pg16\",\n \"environment\": {\"POSTGRES_USER\": \"rag\", \"POSTGRES_PASSWORD\": \"rag\", \"POSTGRES_DB\": \"rag\"},\n \"ports\": [\"5432:5432\"]}\n```\nA imagem `pgvector/pgvector` já traz a extensão compilada; ainda assim é preciso o `CREATE EXTENSION IF NOT EXISTS vector` dentro do banco. As credenciais aqui são de desenvolvimento local — nada disso vale para um banco exposto.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-06"},{"cap":10,"tipo":"sql","nivel":2,"tempo":10,"titulo":"A conferência depois de construir","enunciado":"Escreva as três verificações que se rodam depois de criar o índice: o `EXPLAIN (ANALYZE, BUFFERS)` da consulta de busca com `LIMIT 50`; o tamanho do índice com `pg_size_pretty(pg_relation_size('trecho_emb_hnsw'))`; e a contagem de linhas por modelo (`SELECT modelo_embedding, count(*) FROM rag.trecho_normativo GROUP BY 1`).","esqueleto":"-- 1) o índice é usado?\n-- 2) quanto ele ocupa?\n-- 3) tem mais de um modelo na tabela?\n","checks":[{"re":"EXPLAIN\\s*\\(\\s*ANALYZE\\s*,\\s*BUFFERS\\s*\\)","msg":"EXPLAIN com ANALYZE e BUFFERS"},{"re":"LIMIT\\s+50","msg":"consulta com LIMIT 50"},{"re":"pg_size_pretty\\s*\\(\\s*pg_relation_size\\s*\\(\\s*'trecho_emb_hnsw'","msg":"tamanho do índice"},{"re":"SELECT\\s+modelo_embedding\\s*,\\s*count\\(\\*\\)[\\s\\S]*GROUP BY","flags":"i","msg":"contagem por modelo"}],"solucao":"```sql\n-- 1) o índice é usado?\nEXPLAIN (ANALYZE, BUFFERS)\nSELECT id FROM rag.trecho_normativo\nORDER BY embedding <=> '[…]'::vector\nLIMIT 50;\n\n-- 2) quanto ele ocupa?\nSELECT pg_size_pretty(pg_relation_size('trecho_emb_hnsw'));\n\n-- 3) tem mais de um modelo na tabela?\nSELECT modelo_embedding, count(*) FROM rag.trecho_normativo GROUP BY 1;\n```\nA terceira é a mais fácil de esquecer e a que pega o erro mais caro: se aparecer mais de uma linha, há dois espaços vetoriais no mesmo índice e todos os rankings estão comprometidos.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-07"},{"cap":10,"tipo":"calculo","nivel":1,"tempo":6,"titulo":"O índice do projeto, em números","enunciado":"Base curada de 30.000 dispositivos, `vector(768)` (4 bytes por dimensão), HNSW com `m = 16` (2·m ligações por linha na camada 0, 4 bytes cada).","campos":[{"label":"MB dos vetores (1 MB = 10⁶ bytes)","valor":92.16,"tol":0.5},{"label":"MB das ligações do índice","valor":3.84,"tol":0.1},{"label":"MB no total","valor":96,"tol":1}],"solucao":"92,16 MB de vetores e 3,84 MB de ligações: 96 MB no total, que cabem em memória com folga em qualquer instância pequena. É por isso que a decisão de indexar no projeto não veio do tamanho de hoje, e sim da previsão de crescimento com acórdãos e enunciados do TCU.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-08"},{"cap":10,"tipo":"python","nivel":2,"tempo":12,"titulo":"Registrar a medição com a versão","enunciado":"Escreva `registro(recall, p50, p95, tamanho_bytes, ef_search, versao_base, data)` que devolve o dicionário do relatório com as chaves `recall`, `p50_ms`, `p95_ms`, `tamanho_mb` (bytes / 10⁶, arredondado a 1 casa), `ef_search`, `versao_base` e `data`. É o que vai para o card do Linear a cada reindexação.","esqueleto":"def registro(recall, p50, p95, tamanho_bytes, ef_search, versao_base, data):\n    ...\n","testes":[{"nome":"formato","codigo":"r = registro(0.962, 2.4, 6.1, 96_000_000, 100, \"2026-09\", \"2026-09-06\")\nassert r == {\"recall\": 0.962, \"p50_ms\": 2.4, \"p95_ms\": 6.1, \"tamanho_mb\": 96.0, \"ef_search\": 100, \"versao_base\": \"2026-09\", \"data\": \"2026-09-06\"}"},{"nome":"arredonda o tamanho","codigo":"assert registro(0.9, 1.0, 2.0, 3_456_789, 40, \"v1\", \"d\")[\"tamanho_mb\"] == 3.5"}],"solucao":"```python\ndef registro(recall, p50, p95, tamanho_bytes, ef_search, versao_base, data):\n    return {\n        \"recall\": recall, \"p50_ms\": p50, \"p95_ms\": p95,\n        \"tamanho_mb\": round(tamanho_bytes / 1e6, 1),\n        \"ef_search\": ef_search, \"versao_base\": versao_base, \"data\": data,\n    }\n```\nO que faz esse registro valer é a comparação: um recall de 0,96 isolado não diz nada, mas 0,96 hoje contra 0,98 na reindexação anterior, com a mesma `versao_base`, é um sinal de que algo mudou.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-09"},{"cap":10,"tipo":"js","nivel":2,"tempo":10,"titulo":"Montar o CREATE INDEX","enunciado":"Escreva `montarIndice({nome, tabela, coluna, metrica, m, efConstruction})` que devolve a string do `CREATE INDEX` numa linha só. A métrica escolhe a classe: `cosseno` → `vector_cosine_ops`, `ip` → `vector_ip_ops`, `l2` → `vector_l2_ops`. Formato exato: `CREATE INDEX <nome> ON <tabela> USING hnsw (<coluna> <classe>) WITH (m = <m>, ef_construction = <ef>);`","esqueleto":"function montarIndice(cfg) {\n  // ...\n}\n","exports":["montarIndice"],"testes":[{"nome":"o índice do projeto","codigo":"montarIndice({nome: \"trecho_emb_hnsw\", tabela: \"rag.trecho_normativo\", coluna: \"embedding\", metrica: \"cosseno\", m: 16, efConstruction: 64}) === \"CREATE INDEX trecho_emb_hnsw ON rag.trecho_normativo USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);\""},{"nome":"outra métrica","codigo":"montarIndice({nome: \"i\", tabela: \"t\", coluna: \"v\", metrica: \"l2\", m: 32, efConstruction: 200}).includes(\"vector_l2_ops\")"},{"nome":"parâmetros","codigo":"montarIndice({nome: \"i\", tabela: \"t\", coluna: \"v\", metrica: \"ip\", m: 8, efConstruction: 40}).endsWith(\"WITH (m = 8, ef_construction = 40);\")"}],"solucao":"```js\nconst CLASSES = { cosseno: \"vector_cosine_ops\", ip: \"vector_ip_ops\", l2: \"vector_l2_ops\" };\n\nfunction montarIndice({ nome, tabela, coluna, metrica, m, efConstruction }) {\n  return `CREATE INDEX ${nome} ON ${tabela} USING hnsw (${coluna} ${CLASSES[metrica]}) ` +\n    `WITH (m = ${m}, ef_construction = ${efConstruction});`;\n}\n```\nÉ o montador do capítulo 6 reduzido ao essencial. Gerar o DDL a partir de uma configuração — em vez de escrevê-lo à mão em cada ambiente — é o que garante que desenvolvimento e produção têm o mesmo índice.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-10"},{"cap":10,"tipo":"python","nivel":3,"tempo":20,"titulo":"O script de medição, montado","enunciado":"Escreva `rodada(cur, consultas, efs, k=12)` que, para cada `ef` de `efs`, mede recall e latência sobre todas as `consultas` e devolve a lista de `{\"ef\": …, \"recall\": …, \"p50\": …}` na ordem de `efs`. Use as funções auxiliares `exata(cur, qv, k)` e `aproximada(cur, qv, k, ef)`, já definidas, que devolvem `(ids, ms)`. Recall é a fração dos ids exatos presentes nos aproximados; `p50` é a mediana pelo método do índice mais próximo. Arredonde recall a 3 casas.","esqueleto":"import math\n\ndef rodada(cur, consultas, efs, k=12):\n    ...\n","setup":"import math\n\ndef percentil(valores, p):\n    o = sorted(valores)\n    i = math.ceil(p / 100 * len(o)) - 1\n    return o[min(max(i, 0), len(o) - 1)]\n\n# simuladores: o \"índice\" perde vizinhos quando o ef é baixo\ndef exata(cur, qv, k):\n    return (list(\"abcdefghij\")[:k], 10.0)\n\ndef aproximada(cur, qv, k, ef):\n    perdidos = max(0, (100 - ef) // 20)\n    ids = list(\"abcdefghij\")[:k]\n    for j in range(min(perdidos, len(ids))):\n        ids[-(j + 1)] = \"z\" + str(j)\n    return (ids, 1.0 + ef / 50)\n","testes":[{"nome":"uma linha por ef","codigo":"r = rodada(None, [1, 2, 3], [40, 100], k=10)\nassert [x[\"ef\"] for x in r] == [40, 100]"},{"nome":"recall sobe com o ef","codigo":"r = rodada(None, [1, 2, 3], [40, 100], k=10)\nassert r[0][\"recall\"] == 0.7 and r[1][\"recall\"] == 1.0"},{"nome":"latência sobe com o ef","codigo":"r = rodada(None, [1], [40, 100], k=10)\nassert r[0][\"p50\"] == 1.8 and r[1][\"p50\"] == 3.0"}],"solucao":"```python\ndef rodada(cur, consultas, efs, k=12):\n    saida = []\n    for ef in efs:\n        recalls, tempos = [], []\n        for qv in consultas:\n            ids_ex, _ = exata(cur, qv, k)\n            ids_ap, ms = aproximada(cur, qv, k, ef)\n            recalls.append(len(set(ids_ex) & set(ids_ap)) / len(ids_ex))\n            tempos.append(ms)\n        saida.append({\"ef\": ef, \"recall\": round(sum(recalls) / len(recalls), 3), \"p50\": percentil(tempos, 50)})\n    return saida\n```\nÉ o laço externo do `medir_indice.py`: uma linha da tabela por valor de `ef_search`, que é o que permite escolher o menor `ef` que atinge o alvo.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-11"},{"cap":10,"tipo":"texto","nivel":2,"tempo":6,"titulo":"Por que indexar antes de precisar","enunciado":"Em 4 linhas: o capítulo 9 diz para não indexar bases pequenas, e o projeto indexou 30 mil linhas que a varredura resolveria em 24 ms. Explique a decisão.","rubrica":["A varredura ainda cabe no orçamento hoje (24 ms de 50 ms)","A base cresce com acórdãos e enunciados: a previsão é cruzar o orçamento em poucos anos","Construir e medir com calma vale mais que construir sob pressão, com o sistema já lento","O índice custa pouco nessa escala (96 MB) e o recall é medido a cada reindexação"],"solucao":"A regra do capítulo 9 é \"meça a exata e indexe quando a latência exigir\", e a resposta aqui é que a exigência é previsível: 24 ms de um orçamento de 50 ms, com a base crescendo continuamente pela entrada de acórdãos e enunciados — o cruzamento acontece em poucos anos. O custo de antecipar é baixo (96 MB e uma construção de segundos) e o benefício é grande: o protocolo de medição já está rodando, com números de referência de várias reindexações, quando o índice passar a ser necessário de fato. O erro que a regra proíbe é indexar sem medir nem prever; aqui houve as duas coisas.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-12"},{"cap":10,"tipo":"calculo","nivel":2,"tempo":8,"titulo":"O orçamento da recuperação","enunciado":"Na busca híbrida, a etapa vetorial responde em 2,4 ms (p50) e a lexical em 4 ms; a fusão RRF custa 0,3 ms. O orçamento total da recuperação é 50 ms e as duas buscas rodam em paralelo.","campos":[{"label":"tempo da recuperação em paralelo (ms)","valor":4.3,"tol":0.1},{"label":"tempo se rodassem em série (ms)","valor":6.7,"tol":0.1},{"label":"folga sobre o orçamento, em paralelo (ms)","valor":45.7,"tol":0.2}],"solucao":"Em paralelo, a etapa mais lenta manda: 4 ms da lexical + 0,3 da fusão = 4,3 ms, com 45,7 ms de folga. Em série seriam 6,7 ms — a diferença é pequena aqui justamente porque as duas buscas já são rápidas. É a folga que permite subir o `ef_search` sem discussão quando o recall pedir.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-13"},{"cap":10,"tipo":"texto","nivel":1,"tempo":6,"titulo":"A próxima página","enunciado":"Em 3 linhas: o que a busca vetorial desta página não resolve e que a página 4 vai tratar.","rubrica":["O vetor não vê termos exatos: número de artigo, siglas, expressões literais (página 2, capítulo 6)","A página 4 traz a busca lexical (tsvector, BM25) e a fusão das duas listas por RRF","As duas buscas erram em lugares diferentes: é isso que faz a híbrida valer a pena"],"solucao":"O índice desta página deixa a busca vetorial rápida, mas não muda **o que** ela enxerga: continua sem ver \"art. 75, inc. I\" como um identificador, nem uma sigla interna, nem uma expressão que precisa bater literalmente. A página 4 traz o outro lado — `tsvector`, BM25, o índice GIN — e a fusão por RRF. O argumento central é que as duas buscas erram em lugares diferentes, e é por isso que juntá-las rende mais do que aperfeiçoar qualquer uma delas sozinha.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-14"},{"cap":10,"tipo":"projeto","nivel":3,"tempo":90,"titulo":"Ex. 3 (VIN-7): índice, medição e EXPLAIN","enunciado":"Feche a página 3 com o Ex. 3: suba o PostgreSQL com pgvector via `docker compose`, crie a tabela com as colunas de versionamento (página 2), carregue os trechos do Ex. 2, construa o índice HNSW com os parâmetros do projeto e rode o `medir_indice.py` com dois ou três valores de `ef_search`, guardando a tabela de recall e latência no card do Linear.","entrega":"Scripts de criação, carga e medição; a tabela de recall × latência por ef_search; a saída do EXPLAIN mostrando o índice em uso; e o tamanho do índice.","rubrica":["Tabela e índice criados com m = 16, ef_construction = 64 e vector_cosine_ops, seguidos de ANALYZE","Carga com os trechos do Ex. 2, vetores normalizados e as colunas de versionamento preenchidas","EXPLAIN (ANALYZE, BUFFERS) mostrando `Index Scan using trecho_emb_hnsw` e rows igual ao LIMIT","Recall do índice medido contra a busca exata, com as perguntas do conjunto de avaliação, para dois ou três ef_search","Resultado registrado com a data, a versão da base e o tamanho do índice; chave só no .env"],"solucao":"O resultado esperado com uma base pequena: recall próximo de 1,0 já com `ef_search = 40`, latências de fração de milissegundo nas duas buscas, e um índice de poucos MB. Isso não é um anticlímax — é a confirmação do capítulo 9: nessa escala o índice ainda não é necessário, e o que o exercício constrói é o **instrumento**, não o ganho. Quando a base crescer, o script já existe, os números de referência já existem, e a decisão de subir `ef_search` ou reconstruir com `m` maior vira uma leitura de tabela em vez de um chute.","ligacoes":["03-busca-vetorial.html#c10"],"id":"p3-c10-15"}]};
